import socket
import struct
import time
import threading
import signal
import sys
import os
import traceback

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

try:
    from adafruit_mcp3008 import MCP3008
except ImportError:
    MCP3008 = None

try:
    from gpiozero import DigitalOutputDevice, PWMOutputDevice
except ImportError:
    DigitalOutputDevice = None
    PWMOutputDevice = None

# Constants
DEFAULT_THRESHOLD = 30.0
DEFAULT_DURATION = 5
DEFAULT_GPIO_PIN = 27
DEFAULT_PWM_FREQUENCY = 1000
SENSOR_READING_COUNT = 5
SENSOR_READING_DELAY = 0.02
HEALTH_CHECK_INTERVAL = 60
MAX_PLANT_ID = 10
MCP3008_CHANNEL_PLANT_1 = 0
MCP3008_CHANNEL_PLANT_2 = 1
MOTOR_A_FORWARD_PIN = 27
MOTOR_A_BACKWARD_PIN = 22
MOTOR_B_CLOCKWISE_PIN = 24
MOTOR_B_COUNTERCLOCKWISE_PIN = 25
MOTOR_A_ENABLE_PIN = 17
MOTOR_B_ENABLE_PIN = 23
SPI_CLK_PIN = 11
SPI_MOSI_PIN = 10
SPI_MISO_PIN = 9
SPI_CS_1_PIN = 8
SPI_CS_2_PIN = 7

# Global state
running = True
plant_id_map = {}
motor_a_pwm = None
motor_b_pwm = None
motor_a_forward = None
motor_a_backward = None
motor_b_clockwise = None
motor_b_counter = None
spi = None
sensor_a = None
sensor_b = None


def signal_handler(signum, frame):
    global running
    running = False


def initialize_gpio():
    global motor_a_pwm, motor_b_pwm, motor_a_forward, motor_a_backward, motor_b_clockwise, motor_b_counter, spi, sensor_a, sensor_b
    if GPIO is None:
        print("RPi.GPIO not available; running in software-only mode.")
        return
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(MOTOR_A_FORWARD_PIN, GPIO.OUT)
        GPIO.setup(MOTOR_A_BACKWARD_PIN, GPIO.OUT)
        GPIO.setup(MOTOR_B_CLOCKWISE_PIN, GPIO.OUT)
        GPIO.setup(MOTOR_B_COUNTERCLOCKWISE_PIN, GPIO.OUT)
        GPIO.setup(MOTOR_A_ENABLE_PIN, GPIO.OUT)
        GPIO.setup(MOTOR_B_ENABLE_PIN, GPIO.OUT)
        GPIO.setup(SPI_CLK_PIN, GPIO.OUT)
        GPIO.setup(SPI_MOSI_PIN, GPIO.OUT)
        GPIO.setup(SPI_MISO_PIN, GPIO.IN)
        GPIO.setup(SPI_CS_1_PIN, GPIO.OUT)
        GPIO.setup(SPI_CS_2_PIN, GPIO.OUT)
        motor_a_pwm = PWMOutputDevice(MOTOR_A_ENABLE_PIN, frequency=DEFAULT_PWM_FREQUENCY)
        motor_b_pwm = PWMOutputDevice(MOTOR_B_ENABLE_PIN, frequency=DEFAULT_PWM_FREQUENCY)
        motor_a_forward = DigitalOutputDevice(MOTOR_A_FORWARD_PIN)
        motor_a_backward = DigitalOutputDevice(MOTOR_A_BACKWARD_PIN)
        motor_b_clockwise = DigitalOutputDevice(MOTOR_B_CLOCKWISE_PIN)
        motor_b_counter = DigitalOutputDevice(MOTOR_B_COUNTERCLOCKWISE_PIN)
        spi = [DigitalOutputDevice(SPI_CLK_PIN), DigitalOutputDevice(SPI_MOSI_PIN), DigitalOutputDevice(SPI_MISO_PIN)]
        spi_cs_1 = DigitalOutputDevice(SPI_CS_1_PIN)
        spi_cs_2 = DigitalOutputDevice(SPI_CS_2_PIN)
        spi.append(spi_cs_1)
        spi.append(spi_cs_2)
        sensor_a = MCP3008(spi, cs=spi_cs_1, clock=spi[0], mosi=spi[1], miso=spi[2], channel=MCP3008_CHANNEL_PLANT_1)
        sensor_b = MCP3008(spi, cs=spi_cs_2, clock=spi[0], mosi=spi[1], miso=spi[2], channel=MCP3008_CHANNEL_PLANT_2)
        GPIO.output(MOTOR_A_ENABLE_PIN, GPIO.LOW)
        GPIO.output(MOTOR_B_ENABLE_PIN, GPIO.LOW)
        motor_a_pwm.value = 0.0
        motor_b_pwm.value = 0.0
    except Exception as e:
        print(f"GPIO initialization failed: {e}")
        traceback.print_exc()
        motor_a_pwm = None
        motor_b_pwm = None
        motor_a_forward = None
        motor_a_backward = None
        motor_b_clockwise = None
        motor_b_counter = None
        spi = None
        sensor_a = None
        sensor_b = None


def read_moisture_sensor(sensor, sensor_id):
    if sensor is None:
        return -1
    try:
        raw = sensor.read_adc(0)
        if raw is None or not 0 <= raw <= 1023:
            return -1
        return sum(raw) / len(raw)
    except Exception as e:
        print(f"Error reading sensor {sensor_id}: {e}")
        return -1


def control_motor(motor_a, motor_b, pwm_a, pwm_b, forward, backward, clockwise, counter, enable_pwm, sensor_id, moisture_level, threshold, duration):
    if motor_a is None or motor_b is None or pwm_a is None or pwm_b is None or forward is None or backward is None or clockwise is None or counter is None or enable_pwm is None:
        return
    try:
        if moisture_level < threshold:
            if forward:
                motor_a_forward.on()
                motor_a_backward.off()
                motor_b_clockwise.on()
                motor_b_counter.off()
            else:
                motor_a_forward.off()
                motor_a_backward.on()
                motor_b_clockwise.off()
                motor_b_counter.on()
            enable_pwm.value = 0.5
        else:
            enable_pwm.value = 0.0
    except Exception as e:
        print(f"Error controlling motor {sensor_id}: {e}")


def handle_client(client_socket, client_address, threshold, duration):
    global running
    try:
        while running:
            try:
                data = client_socket.recv(1024)
                if not data:
                    break
                command = data.decode('utf-8').strip()
                print(f"Received command from {client_address}: {command}")
                parts = command.split()
                if not parts:
                    continue
                if parts[0] == "WATER_PLANT_1":
                    moisture_level = read_moisture_sensor(sensor_a, 1)
                    control_motor(motor_a_forward, motor_b_clockwise, motor_a_pwm, motor_b_pwm, True, False, True, False, motor_a_pwm, 1, moisture_level, threshold, duration)
                elif parts[0] == "WATER_PLANT_2":
                    moisture_level = read_moisture_sensor(sensor_b, 2)
                    control_motor(motor_a_forward, motor_b_counter, motor_a_pwm, motor_b_pwm, False, True, False, True, motor_b_pwm, 2, moisture_level, threshold, duration)
                elif parts[0] == "GET_SENSOR_DATA":
                    data_a = sensor_a.read_adc(0)
                    data_b = sensor_b.read_adc(0)
                    if data_a is not None and data_b is not None:
                        print(f"Sensor 1: {data_a}, Sensor 2: {data_b}")
                        client_socket.sendall(struct.pack('>f', data_a) + struct.pack('>f', data_b))
                    else:
                        client_socket.sendall(b"-1,-1")
                elif parts[0] == "SET_THRESHOLD":
                    try:
                        new_threshold = float(parts[1])
                        threshold = new_threshold
                        client_socket.sendall(struct.pack('>f', threshold))
                    except (IndexError, ValueError):
                        client_socket.sendall(b"Invalid threshold value")
                elif parts[0] == "SET_WATERING_DURATION":
                    try:
                        new_duration = int(parts[1])
                        duration = new_duration
                        client_socket.sendall(struct.pack('>i', duration))
                    except (IndexError, ValueError):
                        client_socket.sendall(b"Invalid duration value")
                else:
                    client_socket.sendall(b"Invalid command")
            except Exception as e:
                print(f"Error handling client {client_address}: {e}")
                break
    except Exception as e:
        print(f"Socket error with {client_address}: {e}")
    finally:
        try:
            client_socket.close()
        except Exception:
            pass


def health_check():
    global running
    try:
        if sensor_a is not None:
            avg_a = sum(sensor_a.read_adc(0) for _ in range(SENSOR_READING_COUNT)) / SENSOR_READING_COUNT
            if avg_a < 0:
                print("Sensor A unavailable or error.")
            else:
                print(f"Sensor A average: {avg_a}")
        if sensor_b is not None:
            avg_b = sum(sensor_b.read_adc(0) for _ in range(SENSOR_READING_COUNT)) / SENSOR_READING_COUNT
            if avg_b < 0:
                print("Sensor B unavailable or error.")
            else:
                print(f"Sensor B average: {avg_b}")
    except Exception as e:
        print(f"Health check error: {e}")
    finally:
        time.sleep(HEALTH_CHECK_INTERVAL)


def cleanup():
    global running
    running = False
    if motor_a_pwm is not None:
        try:
            motor_a_pwm.value = 0.0
            motor_a_pwm.close()
        except Exception:
            pass
    if motor_b_pwm is not None:
        try:
            motor_b_pwm.value = 0.0
            motor_b_pwm.close()
        except Exception:
            pass
    if motor_a_forward is not None:
        try:
            motor_a_forward.close()
        except Exception:
            pass
    if motor_a_backward is not None:
        try:
            motor_a_backward.close()
        except Exception:
            pass
    if motor_b_clockwise is not None:
        try:
            motor_b_clockwise.close()
        except Exception:
            pass
    if motor_b_counter is not None:
        try:
            motor_b_counter.close()
        except Exception:
            pass
    if spi is not None:
        try:
            for dev in spi:
                dev.close()
        except Exception:
            pass
    if GPIO is not None:
        try:
            GPIO.cleanup()
        except Exception:
            pass


def main():
    global running, plant_id_map
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        initialize_gpio()
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind(('0.0.0.0', 12345))
        server_socket.listen(5)
        server_socket.settimeout(1.0)
        print("Watering system server started on port 12345...")
        while running:
            try:
                client_socket, client_address = server_socket.accept()
                client_address_str = str(client_address[0]) + ":" + str(client_address[1])
                print(f"Connection from {client_address_str}")
                threshold = DEFAULT_THRESHOLD
                duration = DEFAULT_DURATION
                t = threading.Thread(target=handle_client, args=(client_socket, client_address_str, threshold, duration))
                t.daemon = True
                t.start()
            except socket.timeout:
                continue
            except Exception as e:
                print(f"Socket accept error: {e}")
            health_check()
    except Exception as e:
        print(f"Fatal error: {e}")
        traceback.print_exc()
    finally:
        cleanup()
        print("Server stopped.")


if __name__ == "__main__":
    main()

