import smbus2
import time
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ADS1x15:
    REG_POINTER_CONVERT = 0x00
    REG_POINTER_CONFIG = 0x01
    REG_POINTER_LOWTHRESH = 0x02
    REG_POINTER_HITHRESH = 0x03
    REG_POINTER_PGA = 0x08
    REG_POINTER_MODE = 0x09
    REG_POINTER_DR = 0x0A
    REG_POINTER_CQUE = 0x0C
    REG_POINTER_CQUE_SRC = 0x0D
    REG_POINTER_CQUE_MODE = 0x0E
    REG_POINTER_CQUE_CLOCK = 0x0F

    def __init__(self, address=0x48, busnum=1, debug=False):
        self.address = address
        self.debug = debug
        self.bus = None
        self._running = True
        try:
            self.bus = smbus2.SMBus(busnum)
        except FileNotFoundError:
            logging.error(f"I2C bus {busnum} not found. Enable I2C and check /dev/i2c-{busnum}.")
            raise
        except PermissionError:
            logging.error(f"Permission denied on /dev/i2c-{busnum}. Add user to the 'i2c' group or run with appropriate privileges.")
            raise
        except Exception as e:
            logging.error(f"Failed to initialize I2C bus {busnum}: {e}")
            raise

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None

    def _log_error(self, message):
        logging.error(message)

    def _read_register(self, reg):
        try:
            return self.bus.read_byte_data(self.address, reg)
        except OSError as e:
            self._log_error(f"I2C read error at register 0x{reg:02X}: {e}")
            raise

    def _write_register(self, reg, value):
        try:
            self.bus.write_byte_data(self.address, reg, value)
        except OSError as e:
            self._log_error(f"I2C write error at register 0x{reg:02X}: {e}")
            raise

    def _read_config(self):
        try:
            return self.bus.read_i2c_block_data(self.address, self.REG_POINTER_CONFIG, 2)
        except OSError as e:
            self._log_error(f"I2C read error at config register: {e}")
            raise

    def _write_config(self, data):
        try:
            self.bus.write_i2c_block_data(self.address, self.REG_POINTER_CONFIG, data)
        except OSError as e:
