ADS1115_OS_BEGIN = 0x8000
ADS1115_OS_READY = 0x8000
ADS1115_MUX_OFFSET = 12
ADS1115_PGA_4_096V = 0x0200
ADS1115_MODE_SINGLE = 0x0100
ADS1115_DR_128SPS = 0x0080
ADS1115_CQUE_NONE = 0x0003

# Timing
CONVERSION_TIMEOUT_S = 0.1
POLL_INTERVAL_S = 0.001
LOOP_DELAY_S = 0.05

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _to_signed16(val):
    return val - 0x10000 if val >= 0x8000 else val


def _read_config(bus, addr):
    return bus.read_word_data(addr, ADS1115_REG_CONFIG)


def _write_config(bus, addr, config):
    bus.write_word_data(addr, ADS1115_REG_CONFIG, config)


def _read_conversion(bus, addr):
    return bus.read_word_data(addr, ADS1115_REG_CONVERSION)


def _read_channel(bus, addr, channel):
    config = (
        ADS1115_OS_BEGIN
        | (ADS1115_MUX_OFFSET + (channel & 0x07))
        | ADS1115_PGA_4_096V
        | ADS1115_MODE_SINGLE
        | ADS1115_DR_128SPS
        | ADS1115_CQUE_NONE
    )
    _write_config(bus, addr, config)
    start = time.monotonic()
    while True:
        status = _read_config(bus, addr)
        if not (status & ADS1115_OS_BEGIN):
            return _to_signed16(_read_conversion(bus, addr))
        if time.monotonic() - start > CONVERSION_TIMEOUT_S:
            raise TimeoutError(f"ADS1115 channel {channel} conversion timed out")
        time.sleep(POLL_INTERVAL_S)


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(1)
    except OSError as exc:
        print(f"Error: cannot open I2C bus 1: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                vals = [None] * 4
                for ch in range(4):
                    vals[ch] = _read_channel(bus, ADS1115_ADDRESS, ch)
