import spidev
import time
import signal
import sys

# Configuration
SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 1350000
ADC_CHANNEL = 0
SAMPLE_COUNT = 12
SAMPLE_INTERVAL = 0.5
THRESHOLD_SAFE = 150
THRESHOLD_WARNING = 400

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


class GasSensor:
    def __init__(self, spi_bus, spi_device, spi_speed, adc_channel):
        self.spi = spidev.SpiDev()
        try:
            self.spi.open(spi_bus, spi_device)
            self.spi.max_speed_hz = spi_speed
            self.spi.mode = 0
        except OSError as e:
            raise RuntimeError(f"Failed to open SPI bus {spi_bus}, device {spi_device}: {e}") from e

        self.adc_channel = adc_channel

    def read_raw(self):
        try:
            # MCP3008 single-ended read: start bit, config byte, padding
            # Byte 1: 0x01 (start bit)
            # Byte 2: (8 + adc_channel) << 4  -> config byte
            # Byte 3: 0x00 (padding)
            adc = self.spi.xfer2([0x01, (8 + self.adc_channel) << 4, 0x00])
            # 10-bit result: bits 1-0 of adc[1] and all of adc[2]
            return ((adc[1] & 0x03) << 8) | adc[2]
        except OSError as e:
            raise RuntimeError(f"SPI read error on channel {self.adc_channel}: {e}") from e

    def close(self):
        try:
            self.spi.close()
        except OSError:
            pass


def raw_to_ppm(raw_value):
    # Linear mapping: 0 = 0 ppm, 1023 = 400 ppm
    return (raw_value / 1023.0) * 400.0


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    sensor = None
    try:
        sensor = GasSensor(SPI_BUS, SPI_DEVICE, SPI_SPEED_HZ, ADC_CHANNEL)
        print(f"Gas sensor initialized on SPI bus {SPI_BUS}, device {SPI_DEVICE}.")

        for i in range(SAMPLE_COUNT):
            if not _running:
                print("\nInterrupted by user.")
                break

            try:
                raw = sensor.read_raw()
                ppm = raw_to_ppm(raw)
                level = "safe" if ppm < THRESHOLD_SAFE else "warning" if ppm < THRESHOLD_WARNING else "danger"
                print(f"Sample {i + 1}/{SAMPLE_COUNT}: raw={raw:3d} ppm={ppm:5.1f} {level}")
            except RuntimeError as e:
                print(f"Sample {i + 1}/{SAMPLE_COUNT}: read error - {e}")
            except OSError as e:
                print(f"Sample {i + 1}/{SAMPLE_COUNT}: SPI error - {e}")

            if i < SAMPLE_COUNT - 1 and _running:
                time.sleep(SAMPLE_INTERVAL)

    except RuntimeError as e:
        print(f"Initialization error: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if sensor is not None:
            sensor.close()
        print("Resources released. Exiting.")


if __name__ == "__main__":
    main()

