import time
import signal
import sys
import logging
from datetime import datetime, timezone

try:
    import board
    import busio
    from adafruit_max30102 import MAX30102
except ImportError as exc:
    print(f"Missing required library: {exc}", file=sys.stderr)
    print("Install with: pip install adafruit-circuitpython-max30102", file=sys.stderr)
    sys.exit(1)

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
LOG_FILE = "heart_rate_log.txt"
SAMPLE_INTERVAL_S = 1.0          # ~1 Hz sampling
WINDOW_SECONDS = 4.0             # rolling window for peak detection
I2C_SCL = board.SCL
I2C_SDA = board.SDA

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("heart_rate")

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_sensor = None
_i2c = None
_running = True


def _format_value(value):
    """Defensively format any library-returning value to a string."""
    try:
        return str(value)
    except Exception:
        try:
            return str(int(value)) if isinstance(value, (float, complex)) else str(value)
        except Exception:
            return str(value)


def _signal_handler(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False
    log.info("Signal %s received – shutting down …", signum)


def _init_sensor():
    """Initialise the MAX30102; return None on failure."""
    global _sensor, _i2c
    try:
        _i2c = busio.I2C(I2C_SCL, I2C_SDA)
    except Exception as exc:
        log.error("Failed to initialise I2C bus: %s", exc)
        return None

    try:
        _sensor = MAX30102(_i2c)
        _sensor.setup()
        _sensor.set_sample_rate(100)
        _sensor.set_pulse_width(411)
        log.info("MAX30102 initialised (sample_rate=100 Hz, pulse_width=411 µs).")
        return _sensor
    except Exception as exc:
        log.error("MAX30102 not detected on I2C bus: %s", exc)
        _sensor = None
        return None


def _read_sensor():
    """Return (ir, red) or (None, None) on any error."""
    if _sensor is None:
        log.error("Sensor not initialised.")
        return None, None
    try:
        ir = _sensor.next_sample()
        red = _sensor.next_sample()
        return ir, red
    except Exception as exc:
        log.error("Sensor read error: %s", exc)
        return None, None


def _estimate_heart_rate(ir_window, red_window):
    """Estimate BPM from a rolling window of peaks.

    The MAX30102 does not expose BPM in hardware; this is a simple
    peak-count-based approximation using the rolling window.
    """
    if ir_window is None or red_window is None:
        return None

    peaks = 0
    prev_red = None

    for red in red_window:
        if prev_red is not None and red > prev_red:
            peaks += 1
        prev_red = red

    if peaks == 0:
        return None

    # Simplified BPM estimate: beats per window seconds
    return int(peaks / (WINDOW_SECONDS / SAMPLE_INTERVAL_S))


def _log_and_print(ir, red, hr):
    """Log a single sample and print to console."""
    ir_str = _format_value(ir)
    red_str = _format_value(red)
    hr_str = _format_value(hr)

    timestamp = datetime.now(timezone.utc).isoformat()
    line = f"{timestamp}  IR: {ir_str}, RED: {red_str}, HR: {hr_str}\n"

    try:
        with open(LOG_FILE, "a", encoding="utf-8") as fh:
            fh.write(line)
    except OSError as exc:
        log.error("Failed to write log file: %s", exc)

    print(line, end="")


def main():
    global _sensor

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _sensor = _init_sensor()
    if _sensor is None:
        log.error("Cannot continue without a working sensor.")
        sys.exit(1)

    window = []
    log.info("Starting heart-rate monitoring (Ctrl-C to stop).")

    try:
        while _running:
            ir, red = _read_sensor()
            if ir is not None and red is not None:
                window.append(red)
                if len(window) > WINDOW_SECONDS * SAMPLE_INTERVAL_S:
                    window.pop(0)

                hr = _estimate_heart_rate(window, red)
                if hr is not None:
                    log.info("Heart rate: %d bpm", hr)
                    _log_and_print(ir, red, hr)
            else:
                log.warning("Skipping sample due to read error.")

            # Sleep in small increments so signals are caught promptly
            slept = 0.0
            while _running and slept < SAMPLE_INTERVAL_S:
                time.sleep(0.1)
                slept += 0.1
    finally:
        if _sensor is not None:
            try:
                _sensor.deinit()
            except Exception:
                pass
        if _i2c is not None:
            try:
                _i2c.deinit()
            except Exception:
                pass
        log.info("Program terminated.")


if __name__ == "__main__":
    main()

