import time
import json
import logging
import signal
import sys
import os
from typing import Dict, Any, Optional

import cv2
import numpy as np
from gpiozero import OutputDevice
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "bird_detection_model": "model.json",
    "config.json": "config.json",
    "output_dir": "output",
    "resolution_width": 224,
    "resolution_height": 224,
    "threshold": 0.6,
    "log_level": "INFO",
    "camera_resolution": "preview",
    "gpio_door_control": False,
    "led_pin": 17,
    "feeder_door_pin": 18
}

class Bird:
    def __init__(self, label: str, confidence: float):
        self.label = label
        self.confidence = confidence

    def __repr__(self):
        return f" Bird(label={self.label}, confidence={self.confidence})"

def load_config(config_file: str) -> Dict[str, Any]:
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        logging.info(f"Configuration loaded from {config_file}")
        return config
    except FileNotFoundError:
        logging.warning(f"Configuration file not found: {config_file}. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error(f"Error decoding JSON from {config_file}: {e}. Using defaults.")
        return DEFAULT_CONFIG.copy()

def detect_birds(image: np.ndarray, model_path: str) -> Optional[List[Bird]]:
    try:
        if not os.path.exists(model_path):
            logging.error(f"Model file not found: {model_path}")
            return None
        with open(model_path, "rb") as f:
            data = f.read()
        logging.info("Model loaded successfully.")
        model = cv2.dnn.readNetFromTensorFlowProto(data)
        (h, w) = image.shape[:2]
        blob = cv2.dnn.blobFromImage(image, 1.0, (224, 224), (104.0, 177.0, 123.0))
        model.setInput(blob)
        detections = model.forward()
        birds = []
        for i in range(0, detections.shape[2]):
            confidence = detections[0, 0, i, 2]
            if confidence > 0.5:
                label = detections[0, 0, i, 1]
                birds.append(Bird(label, confidence))
        return birds
    except cv2.error as e:
        logging.error(f"OpenCV error during inference: {e}")
        return None
    except Exception as e:
        logging.error(f"Error during bird detection: {e}")
        return None

def indicate_bird(led_pin: int):
    try:
        led = OutputDevice(led_pin)
        led.on()
        time.sleep(1)
        led.off()
        logging.info("Indicator LED activated for 1 second.")
    except Exception as e:
        logging.error(f"Error controlling LED: {e}")

def control_feeder_door(feeder_door_pin: int, state: bool):
    try:
        if state:
            feeder = OutputDevice(feeder_door_pin)
            feeder.on()
            logging.info("Feeder door opened.")
        else:
            feeder = OutputDevice(feeder_door_pin)
            feeder.off()
            logging.info("Feeder door closed.")
    except Exception as e:
        logging.error(f"Error controlling feeder door: {e}")

def signal_handler(sig, frame, picam2: Optional[Picamera2], led: Optional[OutputDevice], feeder: Optional[OutputDevice]):
    logging.info("Signal received, cleaning up...")
    if picam2:
        picam2.stop()
    if led:
        led.close()
    if feeder:
        feeder.close()
    sys.exit(0)

def main():
    config = load_config(CONFIG_FILE)
    log_level = config.get("log_level", "INFO").upper()
    logging.getLogger().setLevel(log_level)
    picam2 = None
    led = None
    feeder = None
    try:
        picam2 = Picamera2()
        camera_config = picam2.create_preview_configuration(
            main={"size": (config["resolution_width"], config["resolution_height"])}
        )
        picam2.configure(camera_config)
        picam2.start()
        logging.info("Camera initialized successfully.")

        if config.get("gpio_door_control", False):
            led = OutputDevice(config["led_pin"])
            feeder = OutputDevice(config["feeder_door_pin"])
            logging.info("GPIO pins configured for door control.")
        else:
            logging.info("GPIO pins not configured for door control.")

        signal.signal(signal.SIGINT, lambda s, f: signal_handler(s, f, picam2, led, feeder))
        signal.signal(signal.SIGTERM, lambda s, f: signal_handler(s, f, picam2, led, feeder))

        while True:
            image = picam2.capture_array()
            if image is None:
                logging.warning("Failed to capture image.")
                time.sleep(0.1)
                continue
            birds = detect_birds(image, config["bird_detection_model"])
            if birds:
                logging.info(f"Detected {len(birds)} bird(s) with confidence > 0.5")
                for bird in birds:
                    indicate_bird(config["led_pin"])
            time.sleep(0.1)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if picam2:
            picam2.stop()
        if led:
            led.close()
        if feeder:
            feeder.close()
        logging.info("Program finished.")

if __name__ == "__main__":
    main()

