import cv2
import numpy as np
import time
import signal
import sys
from typing import Optional, Tuple

# Constants for camera and object detection
CAMERA_INDEX = 0
CASCADE_CLASSIFIER_PATH = '/home/raspberry/RaspPi_CV/haarcascade_frontalface_default.xml'
LED_PIN = 14
BUTTON_PIN = 15
SERVO_PIN = 18
SERVO_FREQUENCY = 50
SERVO_INCREMENT = 20
SERVO_MIN_ANGLE = 0
SERVO_MAX_ANGLE = 180
DISPLAY_WINDOW_NAME = "Human Detection"
FRAME_WIDTH = 32
FRAME_HEIGHT = 32

# Global state for signal handling
_running = True
_camera: Optional[cv2.VideoCapture] = None
_classifier: Optional[cv2.CascadeClassifier] = None
_servo = None


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def initialize_camera(camera_index: int = CAMERA_INDEX) -> Optional[cv2.VideoCapture]:
    """Initializes the camera with error handling."""
    try:
        camera = cv2.VideoCapture(camera_index)
        if not camera.isOpened():
            raise IOError(f"Cannot open camera {camera_index}")
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        return None


def initialize_face_detector(cascade_path: str) -> Optional[cv2.CascadeClassifier]:
    """Initializes the face detector with error handling."""
    try:
        face_cascade = cv2.CascadeClassifier(cascade_path)
        if face_cascade.empty():
            raise IOError(f"Unable to load face cascade file: {cascade_path}")
        return face_cascade
    except Exception as e:
        print(f"Error initializing face detector: {e}", file=sys.stderr)
        return None


def detect_faces(image, face_cascade) -> Optional[np.ndarray]:
    """Detects faces in the given image."""
    gray_image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    faces = face_cascade.detectMultiScale(gray_image, 1.3, 5)
    return gray_image if faces.any() else None


def draw_rectangles(image, faces) -> None:
    """Draws rectangles around detected faces."""
    for (x, y, w, h) in faces:
        cv2.rectangle(image, (x, y), (x + w, y + h), (255, 0, 0), 2)


def process_frame(image, face_cascade) -> Optional[np.ndarray]:
    """Processes a single frame, detects faces, and draws rectangles."""
    faces = detect_faces(image, face_cascade)
    if faces is not None:
        draw_rectangles(image, faces)
    return image


def get_center_x(image) -> Optional[float]:
    """Calculates the horizontal center of the image."""
    height, width = image.shape[:2]
    center_x = width // 2
    return center_x


def control_servo(servo, center_x) -> None:
    """Controls the servo motor based on the center x-coordinate."""
    if servo is None:
        return
    try:
        if center_x < SERVO_MIN_ANGLE:
            servo.ChangeDutyCycle(2.5)
        elif center_x > SERVO_MAX_ANGLE:
            servo.ChangeDutyCycle(12.5)
        else:
            servo.ChangeDutyCycle(7.5)
        time.sleep(0.02)
    except Exception as e:
        print(f"Error controlling servo: {e}", file=sys.stderr)


def initialize_gpio() -> Tuple[Optional[GPIO], Optional[GPIO], Optional[GPIO]]:
    """Initializes GPIO pins for LED, button, and servo."""
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(SERVO_PIN, GPIO.OUT)
        servo = GPIO.PWM(SERVO_PIN, SERVO_FREQUENCY)
        servo.start(7.5)
        return GPIO, GPIO, servo
    except ImportError:
        print("RPi.GPIO not found. Running without GPIO control.", file=sys.stderr)
        return None, None, None
    except Exception as e:
        print(f"Error initializing GPIO: {e}", file=sys.stderr)
        return None, None, None


def cleanup_gpio() -> None:
    """Cleans up GPIO resources."""
    if _servo is not None:
        try:
            _servo.stop()
        except Exception:
            pass
    try:
        import RPi.GPIO as GPIO
        GPIO.cleanup()
    except Exception:
        pass


def main() -> None:
    """Main function to run the human detection program."""
    global _camera, _classifier, _servo

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _camera = initialize_camera()
    if _camera is None:
        print("Exiting due to camera initialization failure.", file=sys.stderr)
        sys.exit(0)

    _classifier = initialize_face_detector(CASCADE_CLASSIFIER_PATH)
    if _classifier is None:
        print("Exiting due to face detector initialization failure.", file=sys.stderr)
        _cleanup()
        sys.exit(0)

    gpio, led_gpio, servo = initialize_gpio()

    try:
        while _running:
            ret, frame = _camera.read()
            if not ret:
                print("Failed to grab frame", file=sys.stderr)
                break

            processed_frame = process_frame(frame, _classifier)
            if processed_frame is None:
                print("No faces detected.")
            else:
                cv2.imshow(DISPLAY_WINDOW_NAME, processed_frame)

            if gpio is not None:
                try:
                    if cv2.getWindowProperty(DISPLAY_WINDOW_NAME, cv2.WND_PROP_VISIBLE) >= 0:
                        if cv2.countNonZero(processed_frame) > 0:
                            GPIO.output(LED_PIN, GPIO.HIGH)
                            GPIO.output(led_gpio, GPIO.HIGH)
                        else:
                            GPIO.output(LED_PIN, GPIO.LOW)
                            GPIO.output(led_gpio, GPIO.LOW)
                    else:
                        GPIO.output(LED_PIN, GPIO.LOW)
                        GPIO.output(led_gpio, GPIO.LOW)
                except Exception as e:
                    print(f"Error controlling LED: {e}", file=sys.stderr)

            center_x = get_center_x(processed_frame)
            control_servo(servo, center_x)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)
    finally:
        _cleanup()


def _cleanup() -> None:
    """Releases all resources."""
    if _camera is not None:
        _camera.release()
        _camera = None
    cv2.destroyAllWindows()
    if gpio is not None:
        cleanup_gpio()


if __name__ == "__main__":
    main()

