# --- Sensor Classes ---

class Sensor:
    def __init__(self, sensor_type, address, id, bus):
        self.sensor_type = sensor_type
        self.address = address
        self.id = id
        self.bus = bus
        self.valid = False
        self.pressure = None
        self.temperature = None
        self.humidity = None

    def read(self):
        try:
            if self.sensor_type == 'BMP280':
                # Placeholder for BMP280 reading logic
                self.pressure = 100000
                self.temperature = 25.0
            elif self.sensor_type == 'BME280':
                # Placeholder for BME280 reading logic
                self.pressure = 101325
                self.temperature = 20.0
                self.humidity = 50.0
            elif self.sensor_type == 'MS8607':
                # Placeholder for MS8607 reading logic
                self.pressure = 100000
                self.temperature = 22.0
                self.humidity = 60.0
            else:
                logging.error(f"Unknown sensor type: {self.sensor_type}")
                return False

            self.valid = True
            self.pressure = self.pressure if 70000 <= self.pressure <= 110000 else None
            self.temperature = self.temperature if -20 <= self.temperature <= 50 else None
            self.humidity = self.humidity if 0 <= self.humidity <= 100 else None

            return True
        except Exception as e:
            logging.error(f"Error reading {self.sensor_type} at address {self.address}: {e}")
            self.valid = False
            return False

    def get_data(self):
        if self.valid:
            return self.pressure, self.temperature, self.humidity
        return None, None, None

# --- SensorManager ---

class SensorManager:
