    print("Error: RPi.GPIO not installed. Run on a Raspberry Pi.", file=sys.stderr)
    sys.exit(1)

PCF8574_I2C_ADDR = 0x77
GPIO17 = 17
POLL_INTERVAL = 1.0
DEBOUNCE_MS = 50

_running = True
_bus = None
_sensor_pin = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _bus, _sensor_pin
    if _bus is not None:
        try:
            _bus.close()
        except Exception:
            pass
        _bus = None
    if _sensor_pin is not None:
        try:
            GPIO.remove_event_detect(_sensor_pin)
        except Exception:
            pass
        _sensor_pin = None
    try:
        GPIO.cleanup()
    except Exception:
        pass


def _read_sensor(bus):
    try:
        data = bus.read_byte(PCF8574_I2C_ADDR)
    except OSError as exc:
        print(f"I2C read error: {exc}", file=sys.stderr)
        return None
    if data is None:
        print("I2C device not responding.", file=sys.stderr)
        return None
    return data


def _handle_interrupt(channel):
    global _running
    if not _running:
        return
    time.sleep(DEBOUNCE_MS / 1000.0)
    if not _running:
        return
    try:
        data = _read_sensor(_bus)
    except Exception:
        return
    if data is None:
        return
    for i in range(8):
        if not (data & (1 << i)):
            print(f"Obstacle detected by sensor {i}")


def main():
    global _bus, _sensor_pin

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _bus = smbus.SMBus(1)
    except OSError as exc:
        print(f"Failed to open I2C bus 1: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(GPIO17, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        _sensor_pin = GPIO17
        GPIO.add_event_detect(_sensor_pin, GPIO.FALLING, callback=_handle_interrupt, bouncetime=DEBOUNCE_MS)
    except Exception as exc:
        print(f"GPIO setup error: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    print("Proximity sensor monitoring started. Press Ctrl+C to exit.")

    try:
        while _running:
            time.sleep(POLL_INTERVAL)
    except Exception as exc:
        print(f"Unexpected error in main loop: {exc}", file=sys.stderr)
    finally:
        _cleanup()
        print("Program terminated.")


if __name__ == "__main__":
    main()

