import cv2
import numpy as np
import logging
import signal
import sys
import time

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

running = True

def signal_handler(signum, frame):
    global running
    logger.info(f"Signal {signum} received, shutting down...")
    running = False

def initialize_camera(camera_id):
    try:
        camera = cv2.VideoCapture(camera_id, cv2.CAP_V4L2)
        if not camera.isOpened():
            logger.error(f"Failed to open camera {camera_id}")
            return None
        camera.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
        camera.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
        camera.set(cv2.CAP_PROP_FPS, 30)
        camera.set(cv2.CAP_PROP_FRAME_FORMAT, 'RGB888')
        actual_w = camera.get(cv2.CAP_PROP_FRAME_WIDTH)
        actual_h = camera.get(cv2.CAP_PROP_FRAME_HEIGHT)
        logger.info(f"Camera {camera_id} initialized: {actual_w:.0f}x{actual_h:.0f} @ 30fps")
        return camera
    except Exception as e:
        logger.error(f"Error initializing camera {camera_id}: {e}")
        return None

def process_frame(camera1, camera2):
    try:
        ret1, frame1 = camera1.read()
        ret2, frame2 = camera2.read()
        if not ret1 or not ret2:
            logger.warning("Failed to read frames from one or both cameras")
            return None
        return np.hstack((frame1, frame2))
    except Exception as e:
        logger.error(f"Error processing frames: {e}")
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    camera1 = initialize_camera(0)
    camera2 = initialize_camera(1)
    if camera1 is None or camera2 is None:
        logger.error("One or both cameras failed to initialize. Exiting.")
        if camera1:
            camera1.release()
        if camera2:
            camera2.release()
        cv2.destroyAllWindows()
        sys.exit(1)

    try:
        while running:
            frame = process_frame(camera1, camera2)
            if frame is None:
                break
            cv2.imshow("Dual CSI Cameras", frame)
            if cv2.waitKey(30) & 0xFF == 27:
                logger.info("ESC key pressed, exiting...")
                break
    except KeyboardInterrupt:
        logger.info("KeyboardInterrupt received, exiting...")
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        logger.info("Releasing resources...")
        try:
            if camera1 and camera1.isOpened():
                camera1.release()
        except Exception as e:
            logger.error(f"Error releasing camera1: {e}")
        try:
            if camera2 and camera2.isOpened():
                camera2.release()
        except Exception as e:
            logger.error(f"Error releasing camera2: {e}")
        cv2.destroyAllWindows()
        logger.info("Cleanup complete.")

if __name__ == "__main__":
    main()

