                else:
                    logger.error("Failed to save picture.")
            else:
                logger.error("Failed to capture picture.")
        except Exception as e:
            logger.error(f"Error taking picture: {e}")
    else:
        logger.warning("Camera unavailable. Simulating picture capture.")

