            elif command == "turn off the lights":
                GPIO.output(LIGHT_PIN, LIGHT_OFF)
                logger.info("Lights turned off.")
            else:
                logger.warning(f"Unknown light command: {command}")
        except Exception as e:
            logger.error(f"Error controlling lights: {e}")
    else:
        logger.warning("GPIO unavailable. Simulating light control.")

