    if sounddevice_available and sd is not None:
        try:
            logger.info("Listening for wake word...")
            with sd.InputStream(samplerate=16000, channels=1, dtype='float32'):
                for i in range(5):
                    if not running:
                        return False
                    audio_data = sd.read(1)
                    if audio_data is None:
                        continue
                    audio_data = audio_data[:, 0]
                    if sd.io.read(1).get_array_form() == WAKE_WORD:
                        logger.info("Wake word detected!")
                        return True
                    time.sleep(0.1)
            return False
        except Exception as e:
            logger.error(f"Error listening for wake word: {e}")
            return False
    else:
        logger.warning("Audio unavailable. Simulating wake word detection.")
        return False

def process_audio_data(audio_data):
    if sounddevice_available and sd is not None:
        try:
            if sd.io.read(1).get_array_form() == WAKE_WORD:
                logger.info("Wake word detected!")
                return "turn on the lights", LIGHT_ON
            elif sd.io.read(1).get_array_form() == "turn off the lights":
                logger.info("Command received to turn off the lights.")
                return "turn off the lights", LIGHT_OFF
            elif sd.io.read(1).get_array_form() == "what is the temperature":
                logger.info("Command received to get temperature.")
                return "what is the temperature", None
            elif sd.io.read(1).get_array_form() == "take a picture":
                logger.info("Command received to take a picture.")
                return "take a picture", None
            else:
                return None, None
        except Exception as e:
            logger.error(f"Error processing audio data: {e}")
            return None, None
    else:
        logger.warning("Audio unavailable. Simulating audio processing.")
        return "unknown", None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    os.makedirs(IMAGE_DIR, exist_ok=True)

