    init_dht11()
    init_camera()
    init_sounddevice()

    logger.info("Greenhouse control system started.")

    try:
        while running:
            if listen_for_wake_word():
                break
            if not running:
                break
            time.sleep(1)

        if not running:
            break

        while running:
            temperature, humidity = read_dht11()
            if temperature is None:
                logger.warning("DHT11 failed. Using simulated temperature.")
                temperature = random.uniform(TEMPERATURE_MIN, TEMPERATURE_MAX)
            else:
                logger.info(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")

            if temperature is not None:
                if temperature > 30:
                    logger.info("Temperature is high. Turning off the lights.")
                    control_lights("turn off the lights")
                elif temperature < 20:
                    logger.info("Temperature is low. Turning on the lights.")
                    control_lights("turn on the lights")
            else:
                logger.warning("Temperature unavailable. Simulating light control.")

            if "take a picture" in globals():
                take_picture()

            if "process_audio_data" in globals():
                audio_data = sd.read(1)
                if audio_data is not None:
                    command, light_state = process_audio_data(audio_data)
                    if command:
                        control_lights(command)
            else:
                time.sleep(1)

    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup()
        logger.info("Greenhouse control system stopped.")

if __name__ == "__main__":
    main()

