        logger.warning("GPIO unavailable. Simulating light control.")

def listen_for_wake_word():
    if sounddevice_available and sd is not None:
        try:
            logger.info("Listening for wake word...")
            with sd.InputStream(samplerate=16000, channels=1, dtype='float32'):
                for i in range(5):
                    if not running:
                        return False
                    audio_data = sd.read(1)
                    if audio_data is None:
                        continue
                    audio_data = audio_data[:, 0]
                    if sd.io.read(1).get_array_form() == WAKE_WORD:
                        logger.info("Wake word detected!")
                        return True
                    time.sleep(0.1)
            return False
        except Exception as e:
            logger.error(f"Error listening for wake word: {e}")
            return False
    else:
        logger.warning("Audio unavailable. Simulating wake word detection.")
        return False

def process_audio_data(audio_data):
    if sounddevice_available and sd is not None:
        try:
            if sd.io.read(1).get_array_form() == WAKE_WORD:
                logger.info("Wake word detected!")
                return "turn on the lights", LIGHT_ON
            elif sd.io.read(1).get_array_form() == "turn off the lights":
                logger.info("Command received to turn off the lights.")
                return "turn off the lights", LIGHT_OFF
            elif sd.io.read(1).get_array_form() == "what is the temperature":
                logger.info("Command received to get temperature.")
                return "what is the temperature", None
            elif sd.io.read(1).get_array_form() == "take a picture":
                logger.info("Command received to take a picture.")
                return "take a picture", None
            else:
                return None, None
        except Exception as e:
            logger.error(f"Error processing audio data: {e}")
            return None, None
    else:
        logger.warning("Audio unavailable. Simulating audio processing.")
        return "unknown", None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    os.makedirs(IMAGE_DIR, exist_ok=True)

    init_gpio()
    init_dht11()
    init_camera()
    init_sounddevice()

    logger.info("Greenhouse control system started.")

    try:
        while running:
            if listen_for_wake_word():
                break
            if not running:
                break
            time.sleep(1)

        if not running:
            break

        while running:
            temperature, humidity = read_dht11()
            if temperature is None:
                logger.warning("DHT11 failed. Using simulated temperature.")
                temperature = random.uniform(TEMPERATURE_MIN, TEMPERATURE_MAX)
            else:
                logger.info(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")

            if temperature is not None:
                if temperature > 30:
                    logger.info("Temperature is high. Turning off the lights.")
                    control_lights("turn off the lights")
                elif temperature < 20:
                    logger.info("Temperature is low. Turning on the lights.")
                    control_lights("turn on the lights")
            else:
                logger.warning("Temperature unavailable. Simulating light control.")

            if "take a picture" in globals():
                take_picture()

            if "process_audio_data" in globals():
                audio_data = sd.read(1)
                if audio_data is not None:
                    command, light_state = process_audio_data(audio_data)
                    if command:
                        control_lights(command)
            else:
                time.sleep(1)

    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup()
        logger.info("Greenhouse control system stopped.")

if __name__ == "__main__":
    main()

