import argparse
import csv
import datetime
import os
import signal
import sys
import time
from gpiozero import Button

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def parse_args():
    p = argparse.ArgumentParser(description="Vibration monitoring with camera")
    p.add_argument("-g", "--gpio", nargs="+", required=True, help="GPIO pins (BCM) for vibration sensors")
    p.add_argument("-l", "--log_file", required=True, help="CSV log file path")
    p.add_argument("-i", "--interval", type=float, default=1.0, help="Sensor sampling interval (seconds)")
    p.add_argument("-c", "--calibrate", type=float, default=5.0, help="Calibration duration (seconds)")
    p.add_argument("-p", "--picture_interval", type=int, default=60, help="Picture capture interval (seconds)")
    return p.parse_args()

def setup_gpio(gpio_pins):
    sensors = []
    for pin in gpio_pins:
        try:
            b = Button(pin, pull_up=False)
            sensors.append(b)
        except Exception as e:
            print(f"Error setting up GPIO pin {pin}: {e}", file=sys.stderr)
            for s in sensors:
                s.close()
            raise
    return sensors

def calibrate_sensors(sensors, duration):
    print("Calibrating sensors...")
    baseline = []
    for s in sensors:
        readings = []
        for _ in range(int(duration * 10)):
            if _running:
                readings.append(1 if s.is_active else 0)
                time.sleep(0.1)
        baseline.append(sum(readings) / len(readings) * 100 if readings else 0)
    print(f"Calibration complete. Baselines: {baseline}")
    return baseline

def capture_image(camera):
    try:
        os.makedirs("images", exist_ok=True)
        ts = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
        fname = f"images/{ts}.jpg"
        camera.capture_file(fname)
        print(f"Image captured: {fname}")
    except Exception as e:
        print(f"Error capturing image: {e}", file=sys.stderr)

def main():
    global _running
    args = parse_args()
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        sensors = setup_gpio(args.gpio)
    except Exception:
        sys.exit(1)

    try:
        baseline = calibrate_sensors(sensors, args.calibrate)
    except Exception as e:
        print(f"Calibration failed: {e}", file=sys.stderr)
        for s in sensors:
            s.close()
        sys.exit(1)

    thresholds = [b + 20 for b in baseline]

    try:
        camera = None
        try:
            from picamera2 import Picamera2
            camera = Picamera2()
            camera.configure(camera.create_still_configuration())
            camera.start()
            print("Camera initialized.")
        except Exception as e:
            print(f"Camera initialization failed: {e}", file=sys.stderr)
            camera = None

        with open(args.log_file, "w", newline="") as f:
            writer = csv.writer(f)
            writer.writerow(["Timestamp", "Sensor1", "Sensor2", "Sensor3"])
            while _running:
                ts = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]
                states = []
                for i, s in enumerate(sensors):
                    try:
                        high_pct = s.is_active and 100 or 0
                        states.append(1 if high_pct > thresholds[i] else 0)
                    except Exception as e:
                        print(f"Error reading sensor {i}: {e}", file=sys.stderr)
                        states.append(0)
                writer.writerow([ts] + states)
                f.flush()
                if camera:
                    capture_image(camera)
                time.sleep(args.interval)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        for s in sensors:
            s.close()
        if camera:
            try:
                camera.stop()
            except Exception:
                pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

