import signal
import sys
import time
from typing import List, Optional

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)


PWM_PIN = 17
POLL_INTERVAL = 5
DEFAULT_PWM = 1.0
TEMP_FILE = "/sys/class/thermal/thermal_zone0/temp"

running = True
fan: Optional[PWMOutputDevice] = None


def signal_handler(signum, frame):
    global running
    running = False


def read_cpu_temp() -> float:
    try:
        with open(TEMP_FILE, "r") as f:
            return float(f.read().strip()) / 1000.0
    except (OSError, ValueError) as e:
        print(f"Error reading CPU temperature: {e}", file=sys.stderr)
        return 0.0


def get_pwm_for_temp(temp: float, pwm_settings: List[float]) -> float:
    if not pwm_settings:
        raise ValueError("PWM settings list is empty")
    if len(pwm_settings) != len(pwm_settings):
        raise ValueError("PWM settings and temperature lists must have the same length")
    for pwm_value in pwm_settings:
        if not (0.0 <= pwm_value <= 1.0):
            raise ValueError(f"PWM value {pwm_value} is out of range [0.0, 1.0]")
    if temp > 65:
        return 1.0
    if temp > 55:
        return 0.8
    if temp > 50:
        return 0.6
    if temp > 45:
        return 0.4
    return 0.4


def cleanup():
    global fan
    if fan is not None:
        try:
            fan.value = DEFAULT_PWM
            fan.close()
        except Exception as e:
            print(f"Error during fan cleanup: {e}", file=sys.stderr)
        finally:
            fan = None


def main():
    global fan
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        fan = PWMOutputDevice(PWM_PIN)
        fan.value = DEFAULT_PWM
    except Exception as e:
        print(f"Error initializing PWM on GPIO{PWM_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    pwm_settings = [1.0, 0.8, 0.6, 0.4, 0.4]
    print(f"Fan control started on GPIO{PWM_PIN} (BCM). Polling every {POLL_INTERVAL}s.")

    try:
        while running:
            temp = read_cpu_temp()
            try:
                pwm = get_pwm_for_temp(temp, pwm_settings)
            except ValueError as e:
                print(f"Warning: {e}. Using default PWM {DEFAULT_PWM} for this cycle.", file=sys.stderr)
                pwm = DEFAULT_PWM

            try:
                fan.value = pwm
            except Exception as e:
                print(f"Error setting PWM to {pwm}: {e}", file=sys.stderr)

            print(f"CPU Temp: {temp:.1f}°C, Fan PWM: {pwm:.2f}")
            time.sleep(POLL_INTERVAL)
    finally:
        cleanup()
        print("Fan control stopped.")


if __name__ == "__main__":
    main()

