import smbus
import time
import datetime
import logging
import argparse
import threading
import queue
import signal
import sys
import os
import RPi.GPIO as GPIO

# Constants
LIGHT_THRESHOLD = 15
SOUND_THRESHOLD = 3
ANOMALY_WINDOW = 30
LIGHT_READINGS_WINDOW = 30
DATA_FILE_SIZE = 500 * 1024  # 500 KB
CSV_FILE = "installation_data.csv"
ANOMALIES_FILE = "anomalies.log"
I2C_BUS = 1
BME280_I2C_ADDR = 0x76

# Global state
running = True
light_readings = []
light_average = 0.0
last_sound_time = 0.0
last_light_time = 0.0
light_anomaly_start = None
sound_anomaly_start = None
data_queue = queue.Queue()
data_lock = threading.Lock()
data_file_size = 0

# BME280 Registers
BME280_REG_ID = 0xD0
BME280_CHIP_ID = 0x60
BME280_REG_CTRL_HUM = 0xF2
BME280_REG_CTRL_MEAS = 0xF4
BME280_REG_CONFIG = 0xF5
BME280_REG_PRESS_MSB = 0xF7
BME280_REG_TEMP_MSB = 0xFA
BME280_REG_HUM_MSB = 0xFD

# Global I2C bus handle
i2c_bus = None

def signal_handler(sig, frame):
    global running
    running = False

def parse_arguments():
    parser = argparse.ArgumentParser(description="Raspberry Pi Multi-Sensor Monitoring System")
    parser.add_argument("--i2c_address", type=lambda x: int(x, 0), default=BME280_I2C_ADDR, help="I2C address of the BME280 sensor (default: 0x76)")
    parser.add_argument("--light_pin", type=int, default=4, help="GPIO pin for the light sensor (BCM, default: 4)")
    parser.add_argument("--sound_pin", type=int, default=18, help="GPIO pin for the sound sensor (BCM, default: 18)")
    parser.add_argument("--log_level", type=str, default="INFO", choices=["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"], help="Logging level (default: INFO)")
    return parser.parse_args()

def initialize_logging(log_level):
    numeric_level = getattr(logging, log_level.upper(), None)
    if not isinstance(numeric_level, int):
        raise ValueError(f"Invalid log level: {log_level}")
    logging.basicConfig(
        filename=ANOMALIES_FILE,
        level=numeric_level,
        format='%(asctime)s - %(levelname)s - %(message)s'
    )

def initialize_gpio(light_pin, sound_pin):
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(light_pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    GPIO.setup(sound_pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)

def initialize_i2c():
    global i2c_bus
    try:
        i2c_bus = smbus.SMBus(I2C_BUS)
        chip_id = i2c_bus.read_byte_data(BME280_I2C_ADDR, BME280_REG_ID)
        if chip_id != BME280_CHIP_ID:
            raise RuntimeError(f"Invalid chip ID: 0x{chip_id:02X}")
        # Reset sensor
        i2c_bus.write_byte_data(BME280_I2C_ADDR, BME280_REG_CTRL_HUM, 0x01)
        time.sleep(0.1)
        return True
    except Exception as e:
        logging.error(f"Failed to initialize I2C or BME280: {e}")
        return False

def read_bme280_data():
    try:
        # Trigger a forced measurement
        i2c_bus.write_byte_data(BME280_I2C_ADDR, BME280_REG_CTRL_MEAS, 0x27)
        time.sleep(0.1)
        # Read 8 bytes of pressure data
        data = i2c_bus.read_i2c_block_data(BME280_I2C_ADDR, BME280_REG_PRESS_MSB, 8)
        raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
        # Read 8 bytes of temperature data
        data = i2c_bus.read_i2c_block_data(BME280_I2C_ADDR, BME280_REG_TEMP_MSB, 8)
        raw_temperature = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
        # Read 8 bytes of humidity data
        data = i2c_bus.read_i2c_block_data(BME280_I2C_ADDR, BME280_REG_HUM_MSB, 8)
        raw_humidity = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
        # Convert to actual values
        pressure = raw_pressure / 100.0
        temperature = raw_temperature / 100.0
        humidity = raw_humidity / 1024.0
        return pressure, temperature, humidity
    except Exception as e:
        logging.error(f"Error reading BME280 data: {e}")
        return None, None, None

def read_light_sensor(light_pin):
    try:
        return GPIO.input(light_pin)
    except Exception as e:
        logging.error(f"Error reading light sensor: {e}")
        return None

def read_sound_sensor(sound_pin):
    try:
        return GPIO.input(sound_pin)
    except Exception as e:
        logging.error(f"Error reading sound sensor: {e}")
        return None

def calculate_light_average(light_readings):
    if not light_readings:
        return 0.0
    return sum(light_readings) / len(light_readings)

def detect_light_anomaly(light_value, light_average):
    if light_value is None:
        return False
    if light_value > 1000:
        light_value = 1000
    if light_value < 0:
        light_value = 0
    deviation = abs(light_value - light_average) / light_average * 100 if light_average > 0 else 0
    return deviation > LIGHT_THRESHOLD

def detect_sound_anomaly(sound_value, sound_threshold):
    if sound_value is None:
        return False
    if sound_value == 1:
        if sound_anomaly_start is None:
            sound_anomaly_start = time.time()
        elif time.time() - sound_anomaly_start >= SOUND_THRESHOLD:
            sound_anomaly_start = None
            return True
    else:
        sound_anomaly_start = None
    return sound_anomaly_start is not None

def log_data(timestamp, temperature, humidity, pressure, light_value, sound_value):
    try:
        with data_lock:
            data_queue.put((timestamp, temperature, humidity, pressure, light_value, sound_value))
    except Exception as e:
        logging.error(f"Error logging data: {e}")

def log_anomaly(anomaly_type, timestamp, light_value, sound_value):
    try:
        with data_lock:
            data_queue.put((timestamp, anomaly_type, light_value, sound_value))
    except Exception as e:
        logging.error(f"Error logging anomaly: {e}")

def data_logging_thread():
    while running:
        try:
            timestamp, temperature, humidity, pressure, light_value, sound_value = data_queue.get(timeout=1)
            if data_file_size >= DATA_FILE_SIZE:
                try:
                    data_file_size = 0
                    with open(CSV_FILE, "a") as f:
                        f.write(f"{timestamp},{temperature},{humidity},{pressure},{light_value},{sound_value}\n")
                except Exception as e:
                    logging.error(f"Error rotating CSV file: {e}")
            else:
                with open(CSV_FILE, "a") as f:
                    f.write(f"{timestamp},{temperature},{humidity},{pressure},{light_value},{sound_value}\n")
            data_file_size += len(f"{timestamp},{temperature},{humidity},{pressure},{light_value},{sound_value}\n")
            data_queue.task_done()
        except queue.Empty:
            pass
        except Exception as e:
            logging.error(f"Error in data logging thread: {e}")

def anomaly_detection_thread():
    global light_anomaly_start, sound_anomaly_start
    while running:
        try:
            timestamp, anomaly_type, light_value, sound_value = data_queue.get(timeout=1)
            if anomaly_type == "CRITICAL":
                logging.critical(f"CRITICAL ANOMALY: Light={light_value}, Sound={sound_value}")
            elif anomaly_type == "LIGHT":
                if light_anomaly_start is None:
                    light_anomaly_start = time.time()
                elif time.time() - light_anomaly_start >= ANOMALY_WINDOW:
                    logging.critical(f"CRITICAL ANOMALY: Light anomaly persisted for {ANOMALY_WINDOW}s")
                    light_anomaly_start = None
            elif anomaly_type == "SOUND":
                if sound_anomaly_start is None:
                    sound_anomaly_start = time.time()
                elif time.time() - sound_anomaly_start >= ANOMALY_WINDOW:
                    sound_anomaly_start = None
                    logging.critical(f"CRITICAL ANOMALY: Sound anomaly persisted for {ANOMALY_WINDOW}s")
            data_queue.task_done()
        except queue.Empty:
            pass
        except Exception as e:
            logging.error(f"Error in anomaly detection thread: {e}")

def main():
    global running
    args = parse_arguments()
    initialize_logging(args.log_level)
    initialize_gpio(args.light_pin, args.sound_pin)
    if not initialize_i2c():
        logging.error("Failed to initialize I2C or BME280. Exiting.")
        GPIO.cleanup()
        return
    try:
        while running:
            timestamp = datetime.datetime.now().isoformat()
            pressure, temperature, humidity = read_bme280_data()
            light_value = read_light_sensor(args.light_pin)
            sound_value = read_sound_sensor(args.sound_pin)
            if pressure is not None and temperature is not None and humidity is not None:
                log_data(timestamp, temperature, humidity, pressure, light_value, sound_value)
                if detect_light_anomaly(light_value, calculate_light_average(light_readings)):
                    log_anomaly("LIGHT", timestamp, light_value, sound_value)
                    logging.warning(f"Light anomaly detected at {timestamp}")
                if detect_sound_anomaly(sound_value, SOUND_THRESHOLD):
                    log_anomaly("SOUND", timestamp, light_value, sound_value)
                    logging.warning(f"Sound anomaly detected at {timestamp}")
                if light_anomaly_start is not None and sound_anomaly_start is not None and (time.time() - light_anomaly_start >= ANOMALY_WINDOW and time.time() - sound_anomaly_start >= ANOMALY_WINDOW):
                    log_anomaly("CRITICAL", timestamp, light_value, sound_value)
                    logging.critical(f"CRITICAL ANOMALY: Light and Sound anomalies within {ANOMALY_WINDOW}s")
            light_readings.append(light_value)
            if len(light_readings) > LIGHT_READINGS_WINDOW:
                light_readings.pop(0)
            time.sleep(0.1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        running = False
        data_queue.join()
        if i2c_bus:
            try:
                i2c_bus.close()
            except Exception:
                pass
        GPIO.cleanup()
        logging.info("Program finished.")

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    main()

