def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for pin in OUTPUT_PINS:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        for pin in INPUT_PINS:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        print(f"Error initializing GPIO: {e}", file=sys.stderr)
        GPIO.cleanup()
        sys.exit(1)

    state24 = False
    try:
        while _running:
            try:
                val4 = GPIO.input(INPUT_PINS[0])
                val5 = GPIO.input(INPUT_PINS[1])
                val6 = GPIO.input(INPUT_PINS[2])

                if val4 == GPIO.LOW:
                    GPIO.output(OUTPUT_PINS[0], GPIO.HIGH)
                elif val5 == GPIO.LOW:
                    GPIO.output(OUTPUT_PINS[0], GPIO.LOW)
                if val6 == GPIO.LOW:
                    state24 = not state24
                    GPIO.output(OUTPUT_PINS[1], GPIO.HIGH if state24 else GPIO.LOW)

            except Exception as e:
                print(f"Error during GPIO read/write: {e}", file=sys.stderr)

            time.sleep(POLL_INTERVAL)
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

