import cv2
import select
import sys
import time
import signal
import os
import numpy as np
import RPi.GPIO as GPIO
from picamera2 import Picamera2
from picamera2.encoders import JpegEncoder
from picamera2.outputs import FileOutput
import vlc

CONFIG = {
    'TRAINING_FILE': 'lock_training.xml',
    'POSITIVE_LABEL': 'person',
    'POSITIVE_THRESHOLD': 5000,
    'CAMERA_INDEX': 0,
    'BUTTON_PIN': 5,
    'LOCK_PIN': 17,
    'AUDIO_FREQUENCY': 48000,
    'AUDIO_SIZE': -16,
    'AUDIO_CHANNELS': 1,
    'AUDIO_BUFFER_SIZE': 1024,
}

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def load_training_data(training_file):
    if not os.path.isfile(training_file):
        print(f"Error: Training file '{training_file}' not found.")
        return None
    try:
        face_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
        if face_cascade.empty():
            print("Error: Failed to load Haar cascade for face detection.")
            return None
        recognizer = cv2.face.LBPHFaceRecognizer_create()
        recognizer.read(training_file)
        return recognizer
    except Exception as e:
        print(f"Error loading training data: {e}")
        return None

def get_camera():
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(main={"size": (640, 480), "format": "RGB888"})
        picam2.configure(config)
        picam2.start()
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_image(camera):
    try:
        image = camera.capture_array()
        if image is None:
            print("Error: Captured image is None.")
            return None
        return image
    except Exception as e:
        print(f"Error capturing image: {e}")
        return None

def detect_single(image):
    try:
        gray = cv2.cvtColor(image, cv2.COLOR_RGB2GRAY)
        faces = face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))
        if len(faces) == 1:
            return faces[0]
        else:
            return None
    except Exception as e:
        print(f"Error detecting face: {e}")
        return None

def crop_and_resize(image, x, y, w, h):
    try:
        cropped = image[y:y + h, x:x + w]
        return cv2.resize(cropped, (100, 100))
    except Exception as e:
        print(f"Error cropping and resizing: {e}")
        return None

def recognize_face(recognizer, cropped_image):
    try:
        label, confidence = recognizer.predict(cropped_image)
        return label == CONFIG['POSITIVE_LABEL'], confidence < CONFIG['POSITIVE_THRESHOLD']
    except Exception as e:
        print(f"Error during face recognition: {e}")
        return False, False

def unlock_door():
    try:
        GPIO.output(CONFIG['LOCK_PIN'], GPIO.LOW)
        print("Door unlocked!")
        vlc_instance.play("welcome.wav")
    except Exception as e:
        print(f"Error unlocking door: {e}")

def lock_door():
    try:
        GPIO.output(CONFIG['LOCK_PIN'], GPIO.HIGH)
        print("Door locked!")
        vlc_instance.play("lock.wav")
    except Exception as e:
        print(f"Error locking door: {e}")

def play_sound(sound_file, channel):
    try:
        sound = vlc.Instance().media_from_file(sound_file)
        sound.play()
    except Exception as e:
        print(f"Error playing sound '{sound_file}': {e}")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setwarnings(False)
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(CONFIG['BUTTON_PIN'], GPIO.IN, pull_up_down=GPIO.PUD_UP)
    GPIO.setup(CONFIG['LOCK_PIN'], GPIO.OUT, initial=GPIO.HIGH)

    recognizer = load_training_data(CONFIG['TRAINING_FILE'])
    if recognizer is None:
        print("Failed to load training data. Exiting.")
        GPIO.cleanup()
        return

    vlc_instance = None
    try:
        vlc_instance = vlc.Instance()
        vlc_instance.set reincarnation(0)
        vlc_instance.add_media(vlc.Media("welcome.wav"))
        vlc_instance.new()
        vlc_instance.get_default().play("welcome.wav")
    except Exception as e:
        print(f"Error initializing audio: {e}")

    camera = get_camera()
    if camera is None:
        print("Failed to initialize camera. Exiting.")
        GPIO.cleanup()
        return

    try:
        while _running:
            try:
                if select.select([sys.stdin], [], [], 0.0)[0]:
                    input_str = sys.stdin.readline()
                    if input_str.strip() == 'l':
                        lock_door()
            except Exception as e:
                print(f"Error reading input: {e}")

            try:
                image = capture_image(camera)
                if image is None:
                    time.sleep(0.1)
                    continue

                result = detect_single(image)
                if result is None:
                    time.sleep(0.1)
                    continue

                x, y, w, h = result
                cropped = crop_and_resize(image, x, y, w, h)
                if cropped is None:
                    time.sleep(0.1)
                    continue

                is_match, confidence = recognize_face(recognizer, cropped)
                if is_match and confidence < CONFIG['POSITIVE_THRESHOLD']:
                    unlock_door()
                else:
                    print(f"Access denied! Confidence: {confidence}")
                    play_sound("deny.wav", 2)
                    play_sound("wait.wav", 1)

            except Exception as e:
                print(f"Error during face recognition loop: {e}")
                time.sleep(0.1)

    finally:
        print("Cleaning up resources...")
        try:
            if vlc_instance:
                vlc_instance.quit()
        except Exception:
            pass
        try:
            camera.stop()
        except Exception:
            pass
        GPIO.cleanup()
        print("Program finished.")

if __name__ == "__main__":
    face_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
    if face_cascade.empty():
        print("Error: Failed to load Haar cascade for face detection.")
        sys.exit(1)
    main()

