            raise IOError(f"Cannot open camera at index {camera_index}")
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        return None

def load_face_detector(classifier_path="haarcascade_frontalface_default.xml"):
    try:
        detector = cv2.CascadeClassifier(classifier_path)
        if detector.empty():
            raise IOError(f"Failed to load face detector from {classifier_path}")
        return detector
    except Exception as e:
        print(f"Error loading face detector: {e}", file=sys.stderr)
        return None

def detect_faces(image, detector):
    try:
        gray_image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        faces = detector.detectMultiScale(gray_image, scaleFactor=1.1, minNeighbors=5)
        return faces
    except Exception as e:
        print(f"Error detecting faces: {e}", file=sys.stderr)
        return []

def draw_face_rectangles(image, faces):
    try:
        for (x, y, w, h) in faces:
            cv2.rectangle(image, (x, y), (x + w, y + h), (255, 0, 0), 2)
    except Exception as e:
        print(f"Error drawing face rectangles: {e}", file=sys.stderr)

def display_preview(image):
    try:
        cv2.imshow("Real-time Face Detection", image)
    except Exception as e:
        print(f"Error displaying preview: {e}", file=sys.stderr)

def process_frame(camera, detector):
    global _running
    try:
        ret, frame = camera.read()
        if not ret:
            print("Failed to capture frame", file=sys.stderr)
            return False

        faces = detect_faces(frame, detector)
        if len(faces) > 0:
            print("Face detected!")

        draw_face_rectangles(frame, faces)
        display_preview(frame)
        return True
    except Exception as e:
        print(f"Error processing frame: {e}", file=sys.stderr)
        return False

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    camera = initialize_camera()
    if camera is None:
        sys.exit(1)

    face_detector = load_face_detector()
    if face_detector is None:
        camera.release()
        sys.exit(1)

    try:
        while _running:
            if not process_frame(camera, face_detector):
                break
            key = cv2.waitKey(1) & 0xFF
            if key == ord('q'):
                break
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        cv2.destroyAllWindows()
        camera.release()
        print("Camera released. Exiting.")

if __name__ == "__main__":
    main()

