import signal
import sys
import time
import logging
import numpy as np
from math import tanh

try:
    from gpiozero import Button
except ImportError:
    print("gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

try:
    from audioop import linear as audio_op_linear
except ImportError:
    audio_op_linear = None

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("gain_control")

BUTTON_PIN = 5
SAMPLE_RATE = 44100
BLOCK_SIZE = 1024
GAIN_MIN = 1.0
GAIN_MAX = 2.0
BOUNCE_TIME = 0.2

_running = True
_button = None
_audio_stream = None


def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False


def _gain(t, g):
    return g * (1.0 + tanh(t * (g - 1.0)))


def _process_block(block, gain):
    if audio_op_linear is None:
        block = np.asarray(block, dtype=np.float32)
    if block.ndim == 1:
        block = np.expand_dims(block, axis=-1)
    block = np.expand_dims(block, axis=-1)
    block = np.repeat(block, 2, axis=2)
    block = np.repeat(block, 2, axis=3)
    block = np.float32(block)
    block = audio_op_linear(block.astype(np.int16))
    if block.ndim == 1:
        block = np.expand_dims(block, axis=-1)
    block = np.expand_dims(block, axis=-1)
    block = np.repeat(block, 2, axis=2)
    block = np.repeat(block, 2, axis=3)
    block = np.float32(block)
    return _gain(block, gain)


def _button_pressed():
    global _audio_stream
    if _audio_stream is None:
        return
    try:
        current_gain = _audio_stream.gain
        new_gain = (GAIN_MIN + GAIN_MAX) / 2.0
        if current_gain < new_gain:
            _audio_stream.gain = new_gain
            log.info("Gain increased to %.4f.", new_gain)
        else:
            _audio_stream.gain = GAIN_MIN
            log.info("Gain decreased to %.4f.", GAIN_MIN)
    except Exception as exc:
        log.error("Failed to update audio gain: %s", exc)


def main():
    global _button, _audio_stream

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _button = Button(BUTTON_PIN, pull_up=True, bounce_time=BOUNCE_TIME, active_state=False)
        _button.when_pressed = _button_pressed
        log.info("Button ready on GPIO%d (pull-up, active-low).", BUTTON_PIN)
    except Exception as exc:
        log.error("Failed to initialize button on GPIO%d: %s", BUTTON_PIN, exc)
        sys.exit(1)

    try:
        from audioop import Stream as _audioop_Stream
        from simpleaudio import Stream as _simpleaudio_Stream
    except ImportError:
        log.warning("audioop/simpleaudio not installed – audio stream callback will be a stub.")
        _simpleaudio_Stream = None
        _audioop_Stream = None

    try:
        if _simpleaudio_Stream is not None:
            _audio_stream = _simpleaudio_Stream(
                SAMPLE_RATE, BLOCK_SIZE, 1, 0.5, _button_pressed, _audioop_Stream
            )
        else:
            _audio_stream = Stream(
                SAMPLE_RATE, BLOCK_SIZE, 1, 0.5, _button_pressed, _audioop_Stream
            )
        log.info("Audio stream started at %d Hz, block size %d.", SAMPLE_RATE, BLOCK_SIZE)
    except Exception as exc:
        log.error("Failed to start audio stream: %s", exc)
        _cleanup()
        sys.exit(1)

    try:
        while _running:
            time.sleep(0.1)
    finally:
        _cleanup()


def _cleanup():
    global _audio_stream, _button
    log.info("Cleaning up resources.")
    if _audio_stream is not None:
        try:
            if hasattr(_audio_stream, "stop"):
                _audio_stream.stop()
            elif hasattr(_audio_stream, "close"):
                _audio_stream.close()
        except Exception as exc:
            log.warning("Error stopping audio stream: %s", exc)
        _audio_stream = None
    if _button is not None:
        try:
            _button.close()
        except Exception as exc:
            log.warning("Error closing button: %s", exc)
        _button = None


if __name__ == "__main__":
    main()

