import asyncio
import signal
import logging
import threading
import time
from typing import Callable, Optional

import cv2
import numpy as np
from PIL import Image
from flask import Flask, Response
from flask_socketio import SocketIO, emit

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)

app = Flask(__name__)
app.config["SOCKETIO"] = {"cors_allowed_origins": ["*"]}
socketio = SocketIO(app)


class CameraStream:
    """Streams camera video to a WebSocket server with motion detection."""

    def __init__(self, detect_motion_function: Callable[[np.ndarray, np.ndarray], bool],
                 resolution: tuple = (640, 480), framerate: int = 10):
        self.detect_motion_function = detect_motion_function
        self.resolution = resolution
        self.framerate = framerate
        self.frame: Optional[np.ndarray] = None
        self.buffer: list = []
        self.lock = threading.Lock()
        self.running = False
        self.camera: Optional[cv2.VideoCapture] = None

    def start(self) -> None:
        try:
            self.camera = cv2.VideoCapture("rtsp://admin:admin1234@127.0.0.1:5000/v4l2/sdp/best", cv2.CAP_V4L2)
            if not self.camera.isOpened():
                raise RuntimeError("Failed to open rtsp://admin:admin1234@127.0.0.1:5000/v4l2/sdp/best")
            self.camera.set(cv2.CAP_PROP_FRAME_WIDTH, self.resolution[0])
            self.camera.set(cv2.CAP_PROP_FRAME_HEIGHT, self.resolution[1])
            self.camera.set(cv2.CAP_PROP_FPS, self.framerate)
            self.running = True
            logger.info("Camera started successfully.")
        except Exception as e:
            logger.error(f"Error starting camera: {e}")
            self.running = False

    def stop(self) -> None:
        self.running = False
        if self.camera is not None:
            self.camera.release()
            self.camera = None
            logger.info("Camera stopped.")

    def _read_frame(self) -> Optional[np.ndarray]:
        if not self.running or self.camera is None:
            return None
        try:
            ret, frame = self.camera.read()
            if not ret or frame is None:
                logger.warning("Failed to read frame from camera.")
                return None
            return frame
        except Exception as e:
            logger.error(f"Error reading frame: {e}")
            return None

    def _convert_jpeg(self, data: bytes) -> Optional[np.ndarray]:
        try:
            if not data:
                return None
            if len(data) < 2:
                return None
            if data[0:2] != b'\xff\xd8':
                return None
            img = Image.open(BytesIO(data))
            return np.asarray(img)
        except Exception as e:
            logger.error(f"Error converting JPEG: {e}")
            return None

    def _process_frame(self, frame: np.ndarray) -> None:
        if frame is None:
            return
        try:
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            if self.frame is not None:
                self.detect_motion_function(self.frame, gray)
            self.frame = frame
            self.buffer.append(frame.tobytes())
        except Exception as e:
            logger.error(f"Error processing frame: {e}")

    async def run(self) -> None:
        if not self.running:
            logger.error("Camera not started. Cannot run.")
            return
        try:
            while self.running:
                frame = self._read_frame()
                if frame is not None:
                    self._process_frame(frame)
                await asyncio.sleep(1 / self.framerate)
        except Exception as e:
            logger.error(f"Error in camera stream: {e}")
        finally:
            self.stop()

    async def generate(self) -> bytes:
        if not self.running or self.camera is None:
            logger.error("Camera not started. Cannot generate frames.")
            return b""
        while self.running:
            try:
                if self.buffer:
                    with self.lock:
                        frame_data = self.buffer.pop(0)
                else:
                    frame_data = b""
                if frame_data:
                    yield (b'--frame\r\n'
                           b'Content-Type: image/jpeg\r\n\r\n' + frame_data + b'\r\n\r\n')
            except Exception as e:
                logger.error(f"Error generating frame: {e}")
                await asyncio.sleep(0.1)
        self.stop()


@socketio.on("connect")
def handle_connect():
    logger.info("Client connected.")


@socketio.on("disconnect")
def handle_disconnect():
    logger.info("Client disconnected.")


@socketio.on("message")
def handle_message(message):
    logger.info(f"Received message: {message}")


@socketio.on("stream")
def handle_stream(stream):
    logger.info(f"Stream request from {stream['user_id']}")
    try:
        if socketio.has_connections():
            data = stream["frame"].tobytes()
            socketio.emit("stream", {"frame": data}, room=stream["user_id"])
        else:
            logger.warning("No clients connected. Skipping broadcast.")
    except Exception as e:
        logger.error(f"Error broadcasting stream: {e}")


def detect_motion_function(prev_frame: np.ndarray, curr_frame: np.ndarray) -> bool:
    diff = cv2.absdiff(prev_frame, curr_frame)
    gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
    _, thresh = cv2.threshold(gray, 25, 255, cv2.THRESH_BINARY)
    contours, _ = cv2.findContours(thresh, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    for contour in contours:
        if cv2.contourArea(contour) > 500:
            return True
    return False


async def websocket_handler():
    while True:
        try:
            if socketio.has_connections():
                data = "Hello from server!"
                await socketio.emit("message", {"data": data})
            await asyncio.sleep(1)
        except Exception as e:
            logger.error(f"Error in websocket handler: {e}")
            await asyncio.sleep(5)


async def main():
    camera = CameraStream(detect_motion_function)
    camera.start()

    try:
        await camera.run()
    finally:
        camera.stop()

    socketio.run(websocket_handler())


if __name__ == "__main__":
    loop = asyncio.get_running_loop()
    stop_event = asyncio.Event()

    def _signal_handler(signum, frame):
        logger.info(f"Signal {signum} received, shutting down.")
        stop_event.set()

    for sig in (signal.SIGINT, signal.SIGTERM):
        loop.add_signal_handler(sig, _signal_handler, sig, None)

    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        pass
    finally:
        stop_event.set()

