import cv2
import numpy as np
import logging
import math
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class BasicMotionDetector:
    """
    Detects motion in a video stream using a running average with weighted accumulation.
    """

    def __init__(self, accumulate_weight=0.5, delta_threshold=5):
        if not 0.0 < accumulate_weight <= 1.0:
            raise ValueError("accumulate_weight must be between 0.0 and 1.0")
        if delta_threshold < 0:
            raise ValueError("delta_threshold must be non-negative")

        self.accumulate_weight = accumulate_weight
        self.delta_threshold = delta_threshold
        self.avg_frame = None
        self._warmup_frames = 10
        self._original_height = None
        self._original_width = None

    def _calculate_dimensions(self, frame):
        h, w = frame.shape[:2]
        if w == 0:
            raise ValueError("Frame has zero width")
        self._original_width = w
        self._original_height = h
        return h, w

    def _resize_frame(self, frame, target_width=320):
        h, w = self._calculate_dimensions(frame)
        if w == target_width:
            return frame
        new_h = int(h * (target_width / float(w)))
        return cv2.resize(frame, (target_width, new_h), interpolation=cv2.INTER_AREA)

    def _convert_to_gray(self, frame):
        return cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)

    def _apply_blur(self, gray_frame):
        return cv2.GaussianBlur(gray_frame, (21, 21), 0)

    def _threshold(self, blurred_frame):
        _, thresh = cv2.threshold(blurred_frame, self.delta_threshold, 255, cv2.THRESH_BINARY)
        return thresh

    def _dilate(self, thresh_frame):
        for _ in range(2):
            thresh_frame = cv2.dilate(thresh_frame, None, iterations=1)
        return thresh_frame

    def _find_contours(self, dilated_frame):
        contours, _ = cv2.findContours(dilated_frame, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        return contours

    def detect_motion(self, frame):
        try:
            h, w = self._calculate_dimensions(frame)
            if w == 0:
                raise ValueError("Frame has zero width")

            resized_frame = self._resize_frame(frame, target_width=320)
            gray_frame = self._convert_to_gray(resized_frame)
            blurred_frame = self._apply_blur(gray_frame)

            if self._original_height is None or self._original_width is None:
                self.avg_frame = blurred_frame.astype("float")
                return []

            self.avg_frame = cv2.accumulateWeighted(blurred_frame, self.avg_frame, self.accumulate_weight)

            if self._warmup_frames > 0:
                if self.avg_frame is None:
                    return []
                self._warmup_frames -= 1
                return []

            frame_delta = cv2.absdiff(blurred_frame, cv2.convertScaleAbs(self.avg_frame))
            thresh_frame = self._threshold(frame_delta)
            dilated_frame = self._dilate(thresh_frame)

            contours = self._find_contours(dilated_frame)

            motion_locations = []
            for contour in contours:
                if cv2.contourArea(contour) > 5000:
                    motion_locations.append(contour)

            return motion_locations

        except Exception as e:
            logger.error(f"Error during motion detection: {e}", exc_info=True)
            return []


def main():
    detector = BasicMotionDetector(accumulate_weight=0.5, delta_threshold=5)

    # Graceful shutdown on SIGINT/SIGTERM
    def signal_handler(signum, frame):
        logger.info(f"Received signal {signum}, shutting down...")
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Simulated video stream (replace with actual camera or file)
    # In a real scenario, you would use cv2.VideoCapture(0) or similar
    stream = [
        np.array([[[255, 255, 255]]], dtype=np.uint8),
        np.array([[[0, 255, 0]]], dtype=np.uint8),
        np.array([[[0, 0, 255]]], dtype=np.uint8),
        np.array([[[255, 255, 255]]], dtype=np.uint8),
        np.array([[[0, 255, 0]]], dtype=np.uint8),
        np.array([[[255, 255, 255]]], dtype=np.uint8),
        np.array([[[0, 0, 255]]], dtype=np.uint8),
        np.array([[[255, 255, 255]]], dtype=np.uint8),
        np.array([[[0, 255, 0]]], dtype=np.uint8),
        np.array([[[255, 255, 255]]], dtype=np.uint8),
    ]

    for frame in stream:
        if frame is None:
            continue
        motion_locations = detector.detect_motion(frame)
        if motion_locations:
            logger.info(f"Motion detected! Locations: {motion_locations}")
        else:
            logger.info("No motion detected.")

    logger.info("Motion detection complete.")


if __name__ == "__main__":
    main()

