import os
import time
import signal
import logging
import subprocess
import threading
import queue
import paho.mqtt.client as mqtt
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("pi_capture")

IMAGE_WIDTH = 256
IMAGE_HEIGHT = 256
CAPTURE_DIR = "captured_images"
IMAGE_TOPIC = "image_topic"
BROKER = "localhost"
BROKER_PORT = 1883
FRAME_INTERVAL = 0.033  # ~30 fps

shutdown_event = threading.Event()
image_queue = queue.Queue(maxsize=10)
capture_lock = threading.Lock()
latest_image = None

mqtt_client = None


def signal_handler(signum, frame):
    log.info("Signal %s received, shutting down...", signum)
    shutdown_event.set()


def ensure_directory(path):
    try:
        os.makedirs(path, exist_ok=True)
    except OSError as exc:
        log.error("Cannot create directory %s: %s", path, exc)
        raise


def capture_images():
    global latest_image
    ensure_directory(CAPTURE_DIR)

    picam2 = Picamera2()
    config = picam2.create_still_configuration(
        main={"size": (IMAGE_WIDTH, IMAGE_HEIGHT), "format": "RGB888"}
    )
    picam2.configure(config)
    picam2.start()

    log.info("Picamera2 started; capturing 256x256 JPEGs at ~30 fps.")

    while not shutdown_event.is_set():
        try:
            frame = picam2.capture_array()
            if frame is None:
                log.warning("capture_array returned None; retrying...")
                time.sleep(0.01)
                continue

            if frame.ndim == 3 and frame.shape[2] == 3:
                frame = frame[:, :, ::-1]
            elif frame.ndim == 2:
                frame = frame[:, :, np.newaxis]

            if frame.shape != (IMAGE_HEIGHT, IMAGE_WIDTH, 3):
                log.warning("Unexpected frame shape %s; expected %s", frame.shape, (IMAGE_HEIGHT, IMAGE_WIDTH, 3))
                continue

            timestamp = int(time.time() * 1000)
            filename = os.path.join(CAPTURE_DIR, f"image_{timestamp}.jpg")

            try:
                with open(filename, "wb") as fh:
                    fh.write(frame.tobytes())
            except OSError as exc:
                log.error("Failed to write %s: %s", filename, exc)
                continue

            latest_image = frame
            log.info("Captured %s", filename)

            try:
                image_queue.put((frame, filename), timeout=1.0)
            except queue.Full:
                try:
                    image_queue.get_nowait()
                except queue.Empty:
                    pass
                image_queue.put((frame, filename), timeout=1.0)

        except subprocess.TimeoutExpired:
            log.error("Image capture subprocess timed out.")
        except Exception as exc:
            log.error("Error during image capture: %s", exc)
            time.sleep(0.1)

    try:
        picam2.stop()
    except Exception:
        pass
    log.info("Picamera2 stopped.")


def capture_worker():
    while not shutdown_event.is_set():
        try:
            frame, filename = image_queue.get(timeout=1.0)
        except queue.Empty:
            continue

        try:
            with open(filename, "rb") as fh:
                image_bytes = fh.read()
        except OSError as exc:
            log.error("Failed to read %s: %s", filename, exc)
            continue

        if mqtt_client is not None and mqtt_client.is_connected():
            try:
                info = mqtt_client.publish(IMAGE_TOPIC, image_bytes)
                if info.rc != mqtt.MQTT_ERR_SUCCESS:
                    log.error("MQTT publish failed with rc=%s", info.rc)
                else:
                    log.info("Published %s (%d bytes) to %s", filename, len(image_bytes), IMAGE_TOPIC)
            except Exception as exc:
                log.error("MQTT publish error: %s", exc)
        else:
            log.warning("MQTT not connected; cannot publish %s", filename)

        try:
            os.remove(filename)
        except OSError as exc:
            log.warning("Could not remove %s: %s", filename, exc)


def main():
    global mqtt_client

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        os.makedirs(CAPTURE_DIR, exist_ok=True)
    except OSError as exc:
        log.error("Cannot create directory %s: %s", CAPTURE_DIR, exc)
        return

    worker = threading.Thread(target=capture_worker, daemon=True)
    worker.start()

    try:
        mqtt_client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
        mqtt_client.on_connect = lambda c, u, i, r, e: log.info("MQTT connect rc=%s, reason_code=%s, properties=%s", c.rc, r, r)
        mqtt_client.on_disconnect = lambda c, u, i, r, e: log.info("MQTT disconnect rc=%s, reason_code=%s, properties=%s", c.rc, r, r)

        mqtt_client.connect(BROKER, BROKER_PORT, keepalive=60)
        mqtt_client.loop_start()

        while not shutdown_event.is_set():
            time.sleep(0.1)
    except Exception as exc:
        log.error("MQTT error: %s", exc)
    finally:
        log.info("Stopping MQTT loop...")
        if mqtt_client is not None:
            try:
                mqtt_client.loop_stop()
            except Exception:
                pass
            try:
                mqtt_client.disconnect()
            except Exception:
                pass
        log.info("Shutdown complete.")


if __name__ == "__main__":
    main()

