I2C_BUS = 1

_running = True

def _handle_sigint(signum, frame):
    global _running
    _running = False

def _read_sensor():
    """Read temperature and humidity from the AHT10/AHT20 sensor.

    Returns (temperature_celsius, humidity_percent) on success, or None on
    error.
    """
    # AHT10 / AHT20 data: 2 bytes of humidity (MSB first) + 1 byte of
    # temperature (MSB first) + 1 byte of status (0x00 = OK).
    data = [0x00, 0x00, 0x00, 0x00]
    try:
        import smbus2
        bus = smbus2.SMBus(I2C_BUS)
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}")
        return None

    try:
        bus.read_i2c_block_data(I2C_ADDRESS, 0x00, 4)
    except OSError as exc:
        print(f"Error reading sensor (I2C bus error): {exc}")
        return None
    except Exception as exc:
        print(f"Error reading sensor: {exc}")
        return None

    humidity = (data[0] << 8) | data[1]
    temperature = (data[2] << 8) | data[3]
    if temperature > 0x8000:
        temperature -= 0x10000
    if humidity > 0x10000:
        humidity -= 0x10000
    return temperature / 10.0, humidity / 10.0

