class CameraStreamBuffer:
    """Thread-safe buffer for streaming camera frames."""

    def __init__(self, frame_rate: int, buffer_size: int) -> None:
        self.frame_rate = frame_rate
        self.buffer_size = buffer_size
        self.frame_count = 0
        self.buffer = bytearray()
        self.lock = threading.Lock()

    def write(self, data: bytes) -> int:
        """Writes data to the buffer and detects new JPEG frames."""
        with self.lock:
            self.buffer.extend(data)
            if self.buffer:
                jpeg_start = self.buffer.find(b'\xff\xd8')
                if jpeg_start != -1:
                    new_buffer = self.buffer[:jpeg_start]
                    self.buffer = self.buffer[jpeg_start:]
                    if new_buffer:
                        self._process_frame(new_buffer)
        return len(data)

    def _process_frame(self, frame: bytes) -> None:
        """Processes a complete JPEG frame."""
        if self.frame_count >= self.buffer_size:
            self._send_frame(self.frame_count)
            self.frame_count = 0
        else:
            self.frame_count += 1

    def _send_frame(self, frame_number: int) -> None:
        """Sends a complete frame over WebSocket if connections are active."""
        if not _is_web_socket_active():
            return
        try:
            self._send_frame_with_frame_number(frame_number, self.buffer)
        except Exception as e:
            logger.error("Error sending frame: %s", e)
        finally:
            self.buffer = bytearray()

    def flush(self) -> None:
        """Flushes the buffer and sends any remaining frame."""
        if self.buffer:
            self._send_frame(self.frame_count)
            self.buffer = bytearray()


