import subprocess
import threading
import time
import logging
import json
import socket
import sys

import paho.mqtt.client as mqtt
from paho.mqtt.client import CallbackAPIVersion

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("pi_camera_mqtt")

IMAGE_DIR = "images"
MQTT_TOPIC = "raspberrypi/camera"
MQTT_CONTROL_TOPIC = "raspberrypi/control"
MQTT_BROKER = os.environ.get("MQTT_BROKER", "localhost")
MQTT_PORT = int(os.environ.get("MQTT_PORT", 1883))
MQTT_KEEPALIVE = 60
IMAGE_WIDTH = 256
IMAGE_HEIGHT = 256
CAPTURE_TIMEOUT = 15
CAPTURE_INTERVAL = 0.5

shutdown_event = threading.Event()


def signal_handler(signum, frame):
    log.info("Signal %s received, shutting down...", signum)
    shutdown_event.set()


def ensure_image_dir():
    try:
        os.makedirs(IMAGE_DIR, exist_ok=True)
    except OSError as exc:
        log.error("Cannot create image directory '%s': %s", IMAGE_DIR, exc)
        raise


def capture_image():
    timestamp = int(time.time() * 1000)
    image_path = os.path.join(IMAGE_DIR, f"image_{timestamp}.jpg")
    try:
        result = subprocess.run(
            ["libcamera-still", "--width", str(IMAGE_WIDTH), "--height", str(IMAGE_HEIGHT), "-o", image_path],
            capture_output=True, text=True, timeout=CAPTURE_TIMEOUT
        )
        if result.returncode != 0:
            log.error("libcamera-still failed (rc=%d): %s", result.returncode, result.stderr.strip())
            return None
        if not os.path.isfile(image_path) or os.path.getsize(image_path) == 0:
            log.error("Capture produced no valid image: %s", image_path)
            return None
        return image_path
    except subprocess.TimeoutExpired:
        log.error("Capture timed out after %d s", CAPTURE_TIMEOUT)
        return None
    except FileNotFoundError:
        log.error("libcamera-still not found; is libcamera installed?")
        return None
    except Exception as exc:
        log.error("Unexpected error during capture: %s", exc)
        return None


def publish_image(client, image_path):
    try:
        with open(image_path, "rb") as fh:
            image_data = fh.read()
        info = client.publish(MQTT_TOPIC, image_data, qos=1)
        info.wait_for_publish(timeout=5)
        if info.rc != mqtt.MQTT_ERR_SUCCESS:
            log.error("Publish failed (rc=%d): %s", info.rc, info.get_last_error())
        else:
            log.info("Published %d bytes to '%s'", len(image_data), MQTT_TOPIC)
    except FileNotFoundError:
        log.error("Image file not found: %s", image_path)
    except Exception as exc:
        log.error("Error publishing image: %s", exc)


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        log.info("Connected to MQTT broker at %s:%d", MQTT_BROKER, MQTT_PORT)
    else:
        log.error("MQTT connect failed, reason_code=%d", reason_code)


def on_disconnect(client, userdata, flags, reason_code, properties):
    if reason_code != 0:
        log.warning("Unexpected MQTT disconnect, reason_code=%d", reason_code)
    else:
        log.info("MQTT disconnected cleanly")


def on_message(client, userdata, msg):
    try:
        payload = msg.payload.decode("utf-8", errors="replace")
        log.info("Received message on '%s': %s", msg.topic, payload)
    except Exception as exc:
        log.error("Error processing message: %s", exc)


def mqtt_client_thread(client, callback):
    client.on_connect = on_connect
    client.on_disconnect = on_disconnect
    client.on_message = callback
    try:
        client.connect(MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE)
        client.loop_start()
    except Exception as exc:
        log.error("MQTT client connection failed: %s", exc)
        return
    try:
        client.subscribe(MQTT_CONTROL_TOPIC, qos=1)
    except Exception as exc:
        log.error("MQTT subscribe failed: %s", exc)
    log.info("MQTT control loop started; waiting for messages...")
    while not shutdown_event.is_set():
        try:
            client.loop(timeout=1.0)
        except Exception as exc:
            log.error("MQTT loop error: %s", exc)
            time.sleep(1)


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ensure_image_dir()

    mqtt_pub = mqtt.Client(CallbackAPIVersion.VERSION2)
    mqtt_ctrl = mqtt.Client(CallbackAPIVersion.VERSION2)

    pub_thread = threading.Thread(target=mqtt_client_thread, args=(mqtt_pub, on_message), daemon=True)
    ctrl_thread = threading.Thread(target=mqtt_client_thread, args=(mqtt_ctrl, on_message), daemon=True)

    pub_thread.start()
    ctrl_thread.start()

    try:
        while not shutdown_event.is_set():
            image_path = capture_image()
            if image_path:
                publish_image(mqtt_pub, image_path)
            shutdown_event.wait(CAPTURE_INTERVAL)
    except Exception as exc:
        log.error("Fatal error in main loop: %s", exc)
    finally:
        log.info("Shutting down...")
        shutdown_event.set()
        pub_thread.join(timeout=5)
        ctrl_thread.join(timeout=5)
        try:
            mqtt_pub.disconnect()
        except Exception:
            pass
        try:
            mqtt_ctrl.disconnect()
        except Exception:
            pass
        log.info("Exited cleanly.")


if __name__ == "__main__":
    main()

