import io
import logging
import numpy as np
from PIL import Image
from typing import Callable, Optional

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Buffer for handling an MJPEG stream from a camera driver."""

    def __init__(self, c: object):
        self.c = c
        self.buf = io.BytesIO()

    def write(self, d: bytes) -> int:
        """Append bytes to the internal buffer and flush when a complete frame is received."""
        try:
            self.buf.write(d)
            if self.buf.tell() >= self.c.fmt.end:
                self.buf.seek(0)
                self.c.fmt.next(self.buf)
                return self.buf.write(d)
            return self.buf.write(d)
        except Exception as e:
            logger.error(f"Error writing to camera stream buffer: {e}")
            return 0


class MotionDetectionBuffer:
    """Buffer for motion detection using a MJPEG stream."""

    def __init__(self, callback: Callable[[Image.Image, Image.Image], None]):
        self.callback = callback
        self.buf = io.BytesIO()
        self._prev: Optional[Image.Image] = None

    def write(self, d: bytes) -> int:
        """Parse JPEG frames, decode them, and run the motion detection callback."""
        try:
            if d.startswith(b'\xff\xd8'):
                self.buf.seek(0)
                self.buf.truncate()
                img = self.c.imdecode(self.buf.getvalue(), 0)
                if img is None:
                    logger.warning("Failed to decode JPEG frame.")
                    return self.buf.write(d)
                self.buf.seek(0)
                self.buf.truncate()

                if self._prev is not None:
                    self.callback(self._prev, img)
                self._prev = img
            return self.buf.write(d)
        except Exception as e:
            logger.error(f"Error writing to motion detection buffer: {e}")
            return 0

