import sys
import time
import signal
import logging
import threading

import numpy as np
import cv2
import pygame.mixer

from config import Config
from face import Face
from sounds import Sound

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("door")

BUTTON_PIN = 17
LOCK_PIN = 18
SAMPLE_RATE = 48000
BUTTON_UP = 1
BUTTON_DOWN = 0

_running = True


def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received, shutting down...", signum)
    _running = False


def _cleanup():
    global _running
    _running = False
    try:
        if pygame.mixer.get_init() is not None:
            pygame.mixer.quit()
    except Exception:
        pass


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = Config()
    config.load_training_file()
    config.load_config()

    try:
        face_recognizer = cv2.face.EigenFaceRecognizer_create()
        face_recognizer.read(config.TRAINING_FILE)
    except Exception as exc:
        log.error("Failed to load face recognizer model: %s", exc)
        sys.exit(1)

    try:
        pygame.mixer.init(frequency=SAMPLE_RATE, size=-16, channels=2, buffer=1024)
    except Exception as exc:
        log.error("Failed to initialize pygame mixer: %s", exc)
        sys.exit(1)

    welcome = Sound("welcome.wav")
    wait = Sound("wait.wav")
    later = Sound("later.wav")

    door = None
    try:
        door = cv2.face.Door(LOCK_PIN, BUTTON_PIN, config.POSITIVE_LABEL,
                             config.POSITIVE_THRESHOLD, config.NEGATIVE_LABEL,
                             config.NEGATIVE_THRESHOLD, config.TRAINING_FILE)
    except Exception as exc:
        log.error("Failed to initialize door controller: %s", exc)
        _cleanup()
        sys.exit(1)

    try:
        while _running:
            try:
                if door.is_button_up():
                    try:
                        face = door.get_face()
                    except Exception as exc:
                        log.warning("Face capture failed: %s", exc)
                        try:
                            later.play()
                        except Exception:
                            pass
                        time.sleep(0.1)
                        continue

                    if face is None:
                        try:
                            later.play()
                        except Exception:
                            pass
                        time.sleep(0.1)
                        continue

                    label, confidence = face_recognizer.predict(face.image)
                    try:
                        if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                            door.unlock()
                            welcome.play()
                        else:
                            wait.play()
                    except Exception as exc:
                        log.warning("Recognition playback failed: %s", exc)
                else:
                    door.lock()
                    try:
                        later.play()
                    except Exception:
                        pass
            except Exception as exc:
                log.warning("Loop iteration error: %s", exc)
            time.sleep(0.1)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

