import time
import signal
import sys
import smbus2

# Constants
OLED_I2C_ADDR = 0x3C  # SSD1306 OLED display address (common for SSD1306-based modules)
TEMP_FILE_PATH = '/sys/class/thermal/thermal_zone0/temp'
I2C_BUS_NUMBER = 1

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False

def initialize_i2c_bus(bus_number):
    """Initializes the I2C bus. Returns the bus object or None on failure."""
    try:
        bus = smbus2.SMBus(bus_number)
        return bus
    except FileNotFoundError:
        print(f"Error: I2C bus {bus_number} not found. Enable I2C with 'sudo raspi-config'.")
        return None
    except PermissionError:
        print(f"Error: Permission denied on I2C bus {bus_number}. Run as root or add user to 'i2c' group.")
        return None
    except Exception as e:
        print(f"Error initializing I2C bus {bus_number}: {e}")
        return None

def read_temperature(temperature_file_path):
    """Reads the temperature from the thermal zone file and returns it in Celsius."""
    try:
        with open(temperature_file_path, 'r') as f:
            millidegrees = f.read().strip()
            return float(millidegrees) / 1000.0
    except FileNotFoundError:
        print(f"Error: Temperature file not found at {temperature_file_path}")
        return None
    except PermissionError:
        print(f"Error: Permission denied reading {temperature_file_path}")
        return None
    except ValueError:
        print(f"Error: Invalid data format in {temperature_file_path}")
        return None
    except Exception as e:
        print(f"Error reading temperature: {e}")
        return None

def main():
    """Main function to read and display temperature."""
    global running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize I2C bus (only for bus initialization checks)
    i2c_bus = initialize_i2c_bus(I2C_BUS_NUMBER)
    if i2c_bus is None:
        print("Exiting due to I2C bus initialization failure.")
        sys.exit(1)

    try:
        while running:
            temperature_celsius = read_temperature(TEMP_FILE_PATH)

            if temperature_celsius is not None:
                print(f"Temperature: {temperature_celsius:.1f}°C")
            else:
                print("Failed to read temperature.")

            # Sleep in small increments to allow signal handler to interrupt promptly
            sleep_end = time.time() + 2
            while running and time.time() < sleep_end:
                time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        # Release the I2C bus resource
        if i2c_bus is not None:
            try:
                i2c_bus.close()
            except Exception:
                pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

