import signal
import sys
import time

try:
    from smbus2 import SMBus
except ImportError:
    from smbus import SMBus

try:
    from adafruit_ssd1306 import SSD1306_I2C
except ImportError:
    print("adafruit-circuitpython-ssd1306 is not installed. Install with: pip install adafruit-circuitpython-ssd1306")
    sys.exit(1)

# Constants
I2C_BUS = 1
BH1750_ADDR = 0x23
OLED_WIDTH = 128
OLED_HEIGHT = 64
BH1750_CONV_MS = 0.12
UPDATE_INTERVAL_S = 1.0

# Global state
running = True
oled = None
bus = None
last_contrast = 0


def signal_handler(signum, frame):
    global running
    running = False


def init_display():
    global oled
    try:
        oled = SSD1306_I2C(OLED_WIDTH, OLED_HEIGHT, bus)
        oled.begin()
        oled.clear()
        return True
    except Exception as e:
        print(f"Warning: failed to initialize OLED display: {e}")
        oled = None
        return False


def read_light_level():
    try:
        bus.write_byte(BH1750_ADDR, 0x10)  # Power on, continuous high-res mode
        time.sleep(BH1750_CONV_MS)
        data = bus.read_i2c_block_data(BH1750_ADDR, 0x00, 2)
        light_level = (data[0] << 8) | data[1]
        return light_level
    except Exception as e:
        print(f"Warning: I2C read error from BH1750: {e}")
        return None


def update_contrast(light_level):
    global last_contrast
    if light_level is None:
        return last_contrast
    try:
        normalized = light_level / 10.0
        contrast = int(min(max(normalized, 0), 255))
        last_contrast = contrast
        return contrast
    except Exception as e:
        print(f"Warning: failed to compute contrast: {e}")
        return last_contrast


def display_contrast(contrast):
    if oled is None:
        return
    try:
        oled.clear()
        oled.fill(contrast)
        oled.show()
    except Exception as e:
        print(f"Warning: failed to update OLED display: {e}")


def cleanup():
    global oled, bus
    if oled is not None:
        try:
            oled.clear()
            oled.show()
        except Exception:
            pass
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass


def main():
    global bus
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        bus = SMBus(I2C_BUS)
    except Exception as e:
        print(f"Error: failed to open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    if not init_display():
        print("Warning: OLED display not available. Exiting.")

    try:
        while running:
            light_level = read_light_level()
            contrast = update_contrast(light_level)
            display_contrast(contrast)
            time.sleep(UPDATE_INTERVAL_S)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

