logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("bme280_oled")

WIDTH = 128
HEIGHT = 64
UPDATE_INTERVAL = 1.0

running = True


def _signal_handler(signum, frame):
    global running
    log.info("Signal %s received – shutting down.", signum)
    running = False


def _init_i2c():
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        log.error("Failed to initialise I2C bus: %s", exc)
        raise


def _init_oled(i2c):
    try:
        return SSD1306_I2C(WIDTH, HEIGHT, i2c)
    except Exception as exc:
        log.error("Failed to initialise SSD1306 OLED: %s", exc)
        raise


def _init_bme280(i2c):
    try:
        return adafruit_bme280.Adafruit_BME280_I2C(i2c, address=0x76)
    except Exception as exc:
        log.error("Failed to initialise BME280: %s", exc)
        raise


def _init_tsl2561(i2c):
    try:
        return adafruit_tsl2561.TSL2561(i2c)
    except Exception as exc:
        log.error("Failed to initialise TSL2561: %s", exc)
        raise


def _read_bme280(bme280):
    try:
        return bme280.temperature, bme280.humidity, bme280.pressure
    except Exception as exc:
        log.warning("BME280 read error: %s", exc)
        return None, None, None


def _read_tsl2561(tsl2561):
    try:
        return tsl2561.lux
    except Exception as exc:
        log.warning("TSL2561 read error: %s", exc)
        return None


def _update_display(oled, temp, hum, press, light):
    oled.fill(0)
    oled.text(f"Temp: {temp} C", 0, 0, 1)
    oled.text(f"Humidity: {hum} %", 0, 16, 1)
    oled.text(f"Pressure: {press} hPa", 0, 32, 1)
    oled.text(f"Light: {light} lux", 0, 48, 1)
    oled.show()


