import os
import time
import logging
import signal
import sys
from typing import List, Optional, Any

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class AnimatedGif:
    """
    Manages loading, preloading, and playing animated GIFs on a display.

    Attributes:
        display (display.Display): The display object to show the GIF on.
        folder (str): Path to the folder containing GIF files.
        width (int): Width of the display.
        height (int): Height of the display.
        files (List[str]): Pathnames of valid GIF files.
        _is_running (bool): Flag to control the animation loop.
    """

    def __init__(self, display: Any, folder: Optional[str] = None, width: int = -1, height: int = -1):
        """
        Initializes the AnimatedGif object.

        Args:
            display: The display object to show the GIF on.
            folder: Path to the folder containing GIF files. If None, uses the display's folder.
            width: Width of the display. If -1, uses the display's width.
            height: Height of the display. If -1, uses the display's height.
        """
        self.display = display
        self.folder = folder if folder else self._get_folder_from_display()
        self.width = width if width > -1 else self._get_width_from_display()
        self.height = height if height > -1 else self._get_height_from_display()
        self.files: List[str] = self._load_files()
        self._is_running = False

    def _get_folder_from_display(self) -> str:
        """Gets the folder path from the display object."""
        try:
            return getattr(self.display, 'folder', '')
        except AttributeError:
            logger.error("Display object has no 'folder' attribute.")
            return ''

    def _get_width_from_display(self) -> int:
        """Gets the width from the display object."""
        try:
            return getattr(self.display, 'width', 0)
        except AttributeError:
            logger.error("Display object has no 'width' attribute.")
            return 0

    def _get_height_from_display(self) -> int:
        """Gets the height from the display object."""
        try:
            return getattr(self.display, 'height', 0)
        except AttributeError:
            logger.error("Display object has no 'height' attribute.")
            return 0

    def _load_files(self) -> List[str]:
        """Loads GIF file paths from the specified folder."""
        try:
            if not os.path.isdir(self.folder):
                raise FileNotFoundError(f"Folder not found: {self.folder}")

            valid_extensions = ('.gif', '.jpg', '.jpeg', '.png')
            gif_files = [f for f in os.listdir(self.folder) if f.lower().endswith(valid_extensions)]
            return [os.path.join(self.folder, f) for f in gif_files if os.path.isfile(os.path.join(self.folder, f))]
        except FileNotFoundError as e:
            logger.error(f"FileNotFoundError: {e}")
            return []
        except PermissionError as e:
            logger.error(f"PermissionError: {e}")
            return []
        except OSError as e:
            logger.error(f"OSError: {e}")
            return []

    def preload(self) -> None:
        """Preloads GIF frames from the specified files."""
        self._is_running = True
        self.files = self._load_files()
        if not self.files:
            raise FileNotFoundError("No valid GIF files found in the specified folder.")

        frames: List[Any] = []
        for path in self.files:
            try:
                with open(path, 'rb') as f:
                    f.seek(0)
                    img = self.display.load(f)
                    frames.append(img)
            except FileNotFoundError:
                logger.warning(f"File not found: {path}")
            except PermissionError as e:
                logger.warning(f"PermissionError reading {path}: {e}")
            except OSError as e:
                logger.warning(f"OSError reading {path}: {e}")
            except Exception as e:
                logger.error(f"Unexpected error reading {path}: {e}")

        self.frames = frames

    def play(self) -> bool:
        """Plays the preloaded GIF."""
        if not self._is_running:
            return False

        try:
            for i, frame in enumerate(self.frames):
                if not self._should_play_frame(i):
                    break

                start_time = time.monotonic()
                self.display.display(frame)
                duration = self._get_duration_from_frame(frame)
                elapsed_time = time.monotonic() - start_time
                sleep_time = max(0, (duration / 1000) - elapsed_time)
                time.sleep(sleep_time)

                if i < len(self.frames) - 1 and self._should_loop(frame):
                    continue
                else:
                    self._is_running = False
                    return True
            return True
        except Exception as e:
            logger.error(f"Error playing GIF: {e}")
            self._is_running = False
            return False

    def _should_play_frame(self, index: int) -> bool:
        """Checks if the current frame should be played."""
        if index < 0 or index >= len(self.frames):
            return False
        loop = getattr(self.frames[index], 'loop', 0)
        if loop == 0:
            return True
        return i < loop - 1

    def _get_duration_from_frame(self, frame: Any) -> int:
        """Gets the duration of a frame in milliseconds."""
        return getattr(frame, 'duration', 100)

    def run(self) -> None:
        """Runs the animation loop."""
        self._is_running = True
        while self._is_running:
            self.play()

    def stop(self) -> None:
        """Stops the animation loop."""
        self._is_running = False

    def cleanup(self) -> None:
        """Closes any open image file handles."""
        for path in getattr(self, 'frames', []):
            try:
                path.close()
            except Exception:
                pass


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    logger.info(f"Received signal {signum}, shutting down...")
    sys.exit(0)


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)

