    """Calculates the angle between the line connecting (x1,y1)-(x2,y2) and the line connecting (x2,y2)-(x3,y3)."""
    try:
        angle1 = (180 / 3.14159) * ((2 * 3.14159 - 2 * ((3.14159 - 2 * 3.14159 * x1 / 180) + 3.14159 * y1 / 180)) / 2)
