import signal
import sys
import time

try:
    import smbus2 as smbus
except ImportError:
    import smbus

I2C_BUS = 1
PCF8574_ADDR = 0x67
PINS = [0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80]
POLL_INTERVAL = 0.1
RETRY_DELAY = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_sensor(bus, pin):
    try:
        return bus.read_byte_data(PCF8574_ADDR, pin) & 0x01
    except OSError as exc:
        print(f"Error reading sensor {pin}: {exc}", file=sys.stderr)
        return None


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Failed to open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            for i, pin in enumerate(PINS):
                val = read_sensor(bus, pin)
                if val is None:
                    print(f"Sensor {i} unavailable; retrying in {RETRY_DELAY}s...")
                    time.sleep(RETRY_DELAY)
                    continue
                if val == 0:
                    print(f"Obstacle detected by sensor {i}")
            time.sleep(POLL_INTERVAL)
    finally:
        bus.close()
        print("I2C bus closed. Exiting.")


if __name__ == "__main__":
    main()

