import json
import random
import signal
import sys
import time
from typing import Optional

import paho.mqtt.client as mqtt

BROKER = "test.mosquitto.org"
PORT = 1883
KEEPALIVE = 60
TOPIC = "classroom/temperature"
MIN_TEMP = 19.00
MAX_TEMP = 26.00
NUM_READINGS = 5
RETRY_DELAY = 2
MAX_RETRIES = 3
PUBLISH_INTERVAL = 1.0

shutdown_event = asyncio.Event()


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to MQTT broker")
        userdata["connected"] = True
    else:
        print(f"Connection failed with reason code: {reason_code}")
        userdata["connected"] = False


def on_publish(client, userdata, mid, reason_code, properties):
    if reason_code == 0:
        print(f"Message {mid} published successfully")
    else:
        print(f"Publish failed for message {mid} with reason code: {reason_code}")


def generate_temperature_reading() -> float:
    return round(random.uniform(MIN_TEMP, MAX_TEMP), 2)


def on_disconnect(client, userdata, flags, reason_code, properties):
    print(f"Disconnected from MQTT broker (reason code: {reason_code})")


def main() -> int:
    client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
    client.user_data_set({"connected": False})
    client.on_connect = on_connect
    client.on_publish = on_publish
    client.on_disconnect = on_disconnect

    connected = False
    try:
        for attempt in range(1, MAX_RETRIES + 1):
            try:
                client.connect(BROKER, PORT, KEEPALIVE)
                client.loop_start()
                connected = True
                break
            except Exception as e:
                print(f"Attempt {attempt}/{MAX_RETRIES} failed: {e}")
                if attempt < MAX_RETRIES:
                    time.sleep(RETRY_DELAY)
        if not connected:
            print("Failed to connect to MQTT broker after multiple retries.")
            return 1

        messages_sent = 0
        for i in range(NUM_READINGS):
            if shutdown_event.is_set():
                break

            temperature = generate_temperature_reading()
            payload = json.dumps({"temperature": temperature, "index": i})

            result = client.publish(TOPIC, payload, qos=0)
            if result.rc == mqtt.MQTT_ERR_SUCCESS:
                messages_sent += 1
                print(f"Published: {payload} (index: {i})")
            else:
                print(f"Publish failed for reading {i} with error code: {result.rc}")

            if i < NUM_READINGS - 1 and not shutdown_event.is_set():
                shutdown_event.wait(timeout=PUBLISH_INTERVAL)

        if shutdown_event.is_set():
            print("Shutdown requested before all readings were sent.")
        else:
            print(f"Successfully sent {messages_sent} readings.")

        return 0 if messages_sent == NUM_READINGS else 1

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return 1
    finally:
        if connected:
            client.loop_stop()
            client.disconnect()
        print("Disconnected from MQTT broker.")


if __name__ == "__main__":
    sys.exit(main())

