DHT20_STATUS_REG = 0x00
DHT20_DATA_REG = 0x01
POWER_STABILIZATION_DELAY = 0.5
STATUS_OK_MASK = 0x7F
STATUS_OK_VALUE = 0x7F
READ_TIMEOUT = 0.1
RETRY_DELAY = 2.0
MAX_RETRIES = 5


class DHT20:
    def __init__(self, bus_num=1):
        self._bus = None
        try:
            self._bus = smbus2.SMBus(bus_num)
        except Exception as e:
            logging.error(f"Failed to open I2C bus {bus_num}: {e}")
            raise
        self._last_error = None

    def _crc8(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _read_raw(self):
        try:
            data = self._bus.read_i2c_block_data(DHT20_I2C_ADDR, DHT20_DATA_REG, 7)
        except Exception as e:
