import RPi.GPIO as GPIO
import time
import logging
import signal
import sys
import board
import adafruit_dht

# Constants
VENT_PIN = 17
LIMIT_SWITCH_PIN = 5
DHT22_PINS = [4, 23]
MAX_TEMP = 30
MIN_HUMIDITY = 60
HYSTERESIS = 2
ACTUATION_DURATION = 5
POLL_INTERVAL = 60
TIMEOUT = 10

# Global state
last_temp1 = None
last_humidity1 = None
last_temp2 = None
last_humidity2 = None
running = True

# Configure logging
logging.basicConfig(
    filename='greenhouse.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

def signal_handler(signum, frame):
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False

def setup_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(VENT_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(LIMIT_SWITCH_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        for pin in DHT22_PINS:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        logging.info("GPIO setup complete.")
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")
        raise

def read_dht22(pin):
    global last_temp1, last_humidity1, last_temp2, last_humidity2
    try:
        dht_device = None
        if pin == DHT22_PINS[0]:
            dht_device = adafruit_dht.DHT22(board.D4)
        elif pin == DHT22_PINS[1]:
            dht_device = adafruit_dht.DHT22(board.D23)
        else:
            logging.error(f"Invalid DHT22 pin: {pin}")
            return None, None
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is not None and humidity is not None:
            last_temp1 = temperature
            last_humidity1 = humidity
            logging.info(f"DHT22 on pin {pin}: Temp={temperature:.1f}C, Humidity={humidity:.1f}%")
        else:
            logging.warning(f"DHT22 on pin {pin} returned None.")
        return temperature, humidity
    except RuntimeError as e:
        logging.warning(f"DHT22 on pin {pin} read error: {e}")
        return None, None
    except Exception as e:
        logging.error(f"DHT22 on pin {pin} unexpected error: {e}")
        return None, None
    finally:
        if dht_device:
            try:
                dht_device.exit()
            except Exception:
                pass

def read_limit_switch():
    try:
        return GPIO.input(LIMIT_SWITCH_PIN) == GPIO.HIGH
    except Exception as e:
        logging.error(f"Limit switch read error: {e}")
        return None

def open_vent():
    try:
        logging.info("Opening vent...")
        GPIO.output(VENT_PIN, GPIO.HIGH)
        time.sleep(ACTUATION_DURATION)
        GPIO.output(VENT_PIN, GPIO.LOW)
        logging.info("Vent closed.")
        return True
    except Exception as e:
        logging.error(f"Vent actuation error: {e}")
        return False

def check_limit_switch():
    try:
        return read_limit_switch() == GPIO.HIGH
    except Exception as e:
        logging.error(f"Limit switch check error: {e}")
        return None

def check_timeout(start_time):
    try:
        return time.time() - start_time > TIMEOUT
    except Exception as e:
        logging.error(f"Timeout check error: {e}")
        return None

def cleanup():
    try:
        GPIO.output(VENT_PIN, GPIO.LOW)
        GPIO.cleanup()
        logging.info("GPIO cleanup complete.")
    except Exception as e:
        logging.error(f"GPIO cleanup error: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        setup_gpio()
        logging.info("Greenhouse control system started.")
        while running:
            start_time = time.time()
            temp1, humidity1 = read_dht22(DHT22_PINS[0])
            temp2, humidity2 = read_dht22(DHT22_PINS[1])
            if temp1 is not None and temp2 is not None:
                avg_temp = (temp1 + temp2) / 2
            else:
                avg_temp = None
            if humidity1 is not None and humidity2 is not None:
                avg_humidity = (humidity1 + humidity2) / 2
            else:
                avg_humidity = None
            if avg_temp is not None and avg_humidity is not None:
                if avg_temp > MAX_TEMP + HYSTERESIS or avg_humidity < MIN_HUMIDITY - HYSTERESIS:
                    if check_limit_switch() == GPIO.HIGH:
                        logging.info("Vent fully open, aborting actuation.")
                        time.sleep(POLL_INTERVAL)
                        continue
                    if check_timeout(start_time) == True:
                        logging.error("Vent actuation timeout.")
                        GPIO.output(VENT_PIN, GPIO.LOW)
                        time.sleep(POLL_INTERVAL)
                        continue
                    if open_vent() == True:
                        logging.info("Vent actuation successful.")
                    else:
                        logging.error("Vent actuation failed.")
                else:
                    logging.info("Conditions within acceptable range.")
            time.sleep(POLL_INTERVAL)
    except Exception as e:
        logging.error(f"Main loop error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

