import time
import logging
import sqlite3
import random
import sys
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a compatible environment.")
    sys.exit(1)

# Configuration
CONFIG_FILE = "config.txt"
TEMP_MIN = 25.0
TEMP_MAX = 30.0
MOTOR_FORWARD_PIN = 17
MOTOR_BACKWARD_PIN = 18
MOTOR_ENABLE_PIN = 27
LOG_FILE = "greenhouse_vent.log"
DATABASE_FILE = "greenhouse_data.db"

# Logging setup
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.DEBUG,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

def load_config():
    """Loads configuration from config.txt. Returns dict with defaults if missing."""
    config = {
        "TEMP_MIN": TEMP_MIN,
        "TEMP_MAX": TEMP_MAX
    }
    try:
        with open(CONFIG_FILE, "r") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    logging.warning(f"Skipping malformed line: {line}")
                    continue
                key, value = line.split("=", 1)
                key = key.strip()
                value = value.strip()
                if key in config:
                    try:
                        if key == "TEMP_MIN" and value == "25":
                            config[key] = 25.0
                        elif key == "TEMP_MAX" and value == "30":
                            config[key] = 30.0
                        else:
                            config[key] = float(value)
                    except ValueError:
                        logging.warning(f"Invalid value for {key}: {value}. Using current value.")
        logging.info("Configuration loaded successfully.")
    except FileNotFoundError:
        logging.warning("Configuration file not found. Using default values.")
    except Exception as e:
        logging.error(f"Error loading configuration: {e}. Using default values.")
    return config

def get_temperature():
    """Simulates reading temperature data."""
    return random.uniform(20.0, 35.0)

def get_vent_position(temperature, config):
    """Determines desired vent position based on temperature."""
    temp_min = config.get("TEMP_MIN", TEMP_MIN)
    temp_max = config.get("TEMP_MAX", TEMP_MAX)
    if temperature < temp_min:
        return 0.0
    elif temperature > temp_max:
        return 100.0
    else:
        return (temperature - temp_min) / (temp_max - temp_min) * 100.0

def log_data(timestamp, temperature, vent_position):
    """Logs data to the database."""
    try:
        conn = sqlite3.connect(DATABASE_FILE)
        cursor = conn.cursor()
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS greenhouse_data (
                timestamp TEXT,
                temperature REAL,
                vent_position REAL
            )
        """)
        cursor.execute("INSERT INTO greenhouse_data (timestamp, temperature, vent_position) VALUES (?, ?, ?)",
                       (timestamp, temperature, vent_position))
        conn.commit()
        conn.close()
        logging.debug(f"Data logged: Timestamp={timestamp}, Temperature={temperature:.2f}, Vent Position={vent_position:.2f}")
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")
    except Exception as e:
        logging.error(f"Unexpected error logging data: {e}")

def cleanup_gpio():
    """Cleans up GPIO resources."""
    try:
        GPIO.cleanup()
        logging.info("GPIO cleaned up successfully.")
    except Exception as e:
        logging.error(f"Error cleaning up GPIO: {e}")

def main():
    """Main function to run the greenhouse vent control system."""
    config = load_config()
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(MOTOR_FORWARD_PIN, GPIO.OUT)
    GPIO.setup(MOTOR_BACKWARD_PIN, GPIO.OUT)
    GPIO.setup(MOTOR_ENABLE_PIN, GPIO.OUT)
    GPIO.output(MOTOR_ENABLE_PIN, GPIO.HIGH)
    motor_forward = False
    motor_backward = False

    try:
        while True:
            temperature = get_temperature()
            vent_position = get_vent_position(temperature, config)
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

            if temperature < 0 or temperature > 50:
                logging.warning(f"Temperature {temperature:.2f}°C is outside the valid range (0-50°C).")
                log_data(timestamp, temperature, vent_position)
            else:
                if abs(vent_position - GPIO.input(MOTOR_FORWARD_PIN)) > 1:
                    if vent_position > GPIO.input(MOTOR_FORWARD_PIN):
                        motor_forward = True
                        motor_backward = False
                        GPIO.output(MOTOR_FORWARD_PIN, GPIO.HIGH)
                        GPIO.output(MOTOR_BACKWARD_PIN, GPIO.LOW)
                        logging.info(f"Motor moving forward to vent position {vent_position:.2f}%")
                    else:
                        motor_forward = False
                        motor_backward = True
                        GPIO.output(MOTOR_FORWARD_PIN, GPIO.LOW)
                        GPIO.output(MOTOR_BACKWARD_PIN, GPIO.HIGH)
                        logging.info(f"Motor moving backward to vent position {vent_position:.2f}%")
                else:
                    if motor_forward and vent_position < GPIO.input(MOTOR_FORWARD_PIN):
                        GPIO.output(MOTOR_FORWARD_PIN, GPIO.LOW)
                        motor_forward = False
                        logging.info("Motor stopped (forward)")
                    elif motor_backward and vent_position > GPIO.input(MOTOR_BACKWARD_PIN):
                        GPIO.output(MOTOR_BACKWARD_PIN, GPIO.LOW)
                        motor_backward = False
                        logging.info("Motor stopped (backward)")
                    else:
                        logging.info("Motor stays at current position")

                log_data(timestamp, temperature, vent_position)

            time.sleep(60)

    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

