import sys
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
I2C_SCLK = board.SCL   # GPIO3 (BCM)  – TCA9548A SCL
I2C_SDA = board.SDA   # GPIO2 (BCM)  – TCA9548A SDA
READ_INTERVAL_S = 2.0
BME280_I2C_ADDR = 0x76  # BME280 default when ADDR pin tied to GND
TSL2591_I2C_ADDR = 0x29  # TSL2591 default when ADDR pin tied to GND

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_i2c_bus = None
_multiplexer = None
_bme280 = None
_tsl2591 = None
_running = True


def _cleanup():
    """Release hardware resources on exit."""
    global _i2c_bus, _multiplexer, _bme280, _tsl2591
    if _bme280 is not None:
        try:
            _bme280.exit()
        except Exception:
            pass
        _bme280 = None
    if _tsl2591 is not None:
        try:
            _tsl2591.exit()
        except Exception:
            pass
        _tsl2591 = None
    if _multiplexer is not None:
        try:
            _multiplexer.deinit()
        except Exception:
            pass
        _multiplexer = None
    if _i2c_bus is not None:
        try:
            _i2c_bus.deinit()
        except Exception:
            pass
        _i2c_bus = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _init_i2c():
    """Initialise the I2C bus; return the bus object or None on failure."""
    try:
        return busio.I2C(I2C_SCLK, I2C_SDA)
    except Exception as exc:
        print(f"[ERROR] Failed to initialise I2C bus: {exc}", file=sys.stderr)
        return None


def _init_multiplexer(i2c_bus):
    """Initialise the TCA9548A multiplexer; return the object or None."""
    try:
        return adafruit_tca9548a.TCA9548A(i2c_bus)
    except Exception as exc:
        print(f"[ERROR] Failed to initialise TCA9548A multiplexer: {exc}",
              file=sys.stderr)
        return None


def _init_sensors(multiplexer):
    """Initialise BME280 and TSL2591; return (bme280, tsl2591) or (None, None)."""
    bme = None
    tsl = None
    try:
        bme = adafruit_bme280.Adafruit_BME280_I2C(
            multiplexer[0], address=BME280_I2C_ADDR
        )
    except Exception as exc:
        print(f"[WARN] BME280 not found at 0x{BME280_I2C_ADDR:02X}: {exc}",
              file=sys.stderr)
    try:
        tsl = adafruit_tsl2591.TSL2591(multiplexer[1])
    except Exception as exc:
        print(f"[WARN] TSL2591 not found at 0x{TSL2591_I2C_ADDR:02X}: {exc}",
              file=sys.stderr)
    return bme, tsl


def _read_bme280(bme):
    """Return (temperature, humidity) or (None, None) on error."""
    if bme is None:
        return None, None
    try:
        return bme.temperature, bme.humidity
    except Exception as exc:
        print(f"[ERROR] BME280 read failed: {exc}", file=sys.stderr)
        return None, None


def _read_tsl2591(tsl):
    """Return (light_intensity) or None on error."""
    if tsl is None:
        return None
    try:
        return tsl.lux
    except Exception as exc:
        print(f"[ERROR] TSL2591 read failed: {exc}", file=sys.stderr)
        return None


def main():
    global _i2c_bus, _multiplexer, _bme280, _tsl2591

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _i2c_bus = _init_i2c()
    if _i2c_bus is None:
        print("[FATAL] Cannot continue without I2C bus.", file=sys.stderr)
        sys.exit(1)

    _multiplexer = _init_multiplexer(_i2c_bus)
    if _multiplexer is None:
        print("[FATAL] Cannot continue without multiplexer.", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    _bme280, _tsl2591 = _init_sensors(_multiplexer)
    if _bme280 is None and _tsl2591 is None:
        print("[FATAL] No sensors detected. Check wiring and multiplexer address.",
              file=sys.stderr)
        _cleanup()
        sys.exit(1)

    print("Sensors initialised. Reading every 2 s (Ctrl+C to stop).")

    while _running:
        temp, hum = _read_bme280(_bme280)
        light = _read_tsl2591(_tsl2591)

        if temp is not None and hum is not None and light is not None:
            print(f"Temp: {temp:.2f} C  Humidity: {hum:.2f} %  Light: {light:.2f} lux")
        else:
            print("[WARN] One or more sensor reads failed this cycle.")

        # Sleep in small increments so signals are caught promptly
        slept = 0.0
        while _running and slept < READ_INTERVAL_S:
            time.sleep(0.1)
            slept += 0.1

    print("\nShutting down cleanly.")


if __name__ == "__main__":
    main()
    _cleanup()

