import time
import logging
import signal
import sys
from typing import List, Optional

import board
import busio
import adafruit_bmp280

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
I2C_BUS = 1
SEALEVEL_PRESSURE_HPA = 1013.25
SAMPLE_COUNT = 100
DISCARD_PERCENTAGE = 0.25
SAMPLE_INTERVAL_S = 1.0

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_sensor: Optional["adafruit_bmp280.Adafruit_BMP280"] = None


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    logger.info("Signal %s received – shutting down.", signum)
    _running = False


def initialize_sensor() -> Optional["adafruit_bmp280.Adafruit_BMP280"]:
    """Initialize the BMP280 on I2C bus 1; return None on failure."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        logger.error("Failed to initialize I2C bus: %s", exc)
        return None

    try:
        sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c, address=0x76)
    except ValueError as exc:
        logger.error("BMP280 not found on I2C bus %d (address 0x76): %s", I2C_BUS, exc)
        return None
    except OSError as exc:
        logger.error("I2C bus error while initializing BMP280: %s", exc)
        return None
    except Exception as exc:
        logger.error("Unexpected error initializing BMP280: %s", exc)
        return None

    try:
        sensor.sea_level_pressure = SEALEVEL_PRESSURE_HPA
    except Exception as exc:
        logger.warning("Could not set sea_level_pressure; keeping default: %s", exc)

    return sensor


def calibrate_sensor(sensor: "adafruit_bmp280.Adafruit_BMP280", sample_count: int) -> Optional[float]:
    """Collect *sample_count* samples, discard top/bottom 25 %, return trimmed mean."""
    logger.info("Collecting %d pressure samples for calibration...", sample_count)
    pressures: List[float] = []
    for i in range(sample_count):
        try:
            pressures.append(sensor.pressure)
        except OSError as exc:
            logger.warning("I2C read error during calibration sample %d: %s", i, exc)
        except Exception as exc:
            logger.warning("Unexpected error reading pressure during calibration sample %d: %s", i, exc)
        if i < sample_count - 1:
            time.sleep(0.1)

    if not pressures:
        logger.error("No valid pressure samples collected during calibration.")
        return None

    logger.info("Calibration complete. Samples: %d, Discarded (top/bottom): %.1f%%", len(pressures), DISCARD_PERCENTAGE * 100)
    pressures.sort()
    discard_count = int(len(pressures) * DISCARD_PERCENTAGE)
    if discard_count > 0:
        logger.info("Discarding top %d and bottom %d samples.", discard_count, discard_count)
    else:
        logger.info("No samples discarded (discard percentage <= 0).")

    valid = pressures[discard_count : len(pressures) - discard_count]
    if not valid:
        logger.error("No valid pressure samples remaining after trimming.")
        return None

    return sum(valid) / len(valid)


def get_altitude(sensor: "adafruit_bmp280.Adafruit_BMP280") -> Optional[float]:
    """Read altitude; return None on error."""
    try:
        return sensor.altitude
    except OSError as exc:
        logger.error("I2C bus error while reading altitude: %s", exc)
        return None
    except Exception as exc:
        logger.error("Unexpected error reading altitude: %s", exc)
        return None


def main() -> int:
    global _sensor

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    _sensor = initialize_sensor()
    if _sensor is None:
        logger.error("Sensor initialization failed. Exiting.")
        return 1

    baseline = calibrate_sensor(_sensor, SAMPLE_COUNT)
    if baseline is None:
        logger.warning("Baseline calibration failed. Using default sea-level pressure for altitude calculation.")
        try:
            _sensor.sea_level_pressure = SEALEVEL_PRESSURE_HPA
        except Exception as exc:
            logger.warning("Could not set sea_level_pressure; keeping default: %s", exc)
    else:
        logger.info("Baseline altitude: %.2f meters", baseline)

    try:
        while _running:
            altitude = get_altitude(_sensor)
            if altitude is not None:
                logger.info("Altitude: %.2f meters", altitude)
            else:
                logger.error("Failed to read altitude.")
            time.sleep(SAMPLE_INTERVAL_S)
    except Exception as exc:
        logger.exception("Unexpected error in main loop: %s", exc)
        return 1
    finally:
        if _sensor is not None:
            try:
                _sensor.sea_level_pressure = None
            except Exception:
                pass
            try:
                _sensor = None
            except Exception:
                pass
        logger.info("Resources released. Exiting.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

