import signal
import sys
import os
import configparser
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a valid GPIO library.")
    sys.exit(1)

CONFIG_FILE = "config.ini"
DEFAULT_CONFIG = {
    "GPIO": {
        "DHT22_PIN": "4",
        "LED_PIN": "17"
    },
    "Logging": {
        "interval": "5",
        "log_level": "INFO"
    }
}

running = True

def signal_handler(signum, frame):
    global running
    running = False

def load_config(config_file):
    config = configparser.ConfigParser()
    config.read(config_file)
    gpio_pins = config.get("GPIO", "DHT22_PIN", fallback=DEFAULT_CONFIG["GPIO"]["DHT22_PIN"])
    led_pin = config.get("GPIO", "LED_PIN", fallback=DEFAULT_CONFIG["GPIO"]["LED_PIN"])
    interval = config.getint("Logging", "interval", fallback=DEFAULT_CONFIG["Logging"]["interval"])
    log_level = config.get("Logging", "log_level", fallback=DEFAULT_CONFIG["Logging"]["log_level"])
