import csv
import os
import signal
import sys
import time
from datetime import datetime

import serial

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1.0
LOG_FILE = 'temperature_log.csv'

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _write_csv_row(writer, timestamp, celsius, fahrenheit):
    writer.writerow([timestamp, celsius, fahrenheit])


def _open_csv():
    file_exists = os.path.isfile(LOG_FILE)
    try:
        with open(LOG_FILE, 'a', newline='') as f:
            return csv.writer(f)
    except IOError as e:
        print(f"Error opening CSV file '{LOG_FILE}': {e}", file=sys.stderr)
        sys.exit(1)


def _read_temperature(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    if not raw:
        return None
    try:
        text = raw.decode('ascii', errors='replace').strip()
    except Exception as e:
        print(f"Decode error: {e}", file=sys.stderr)
        return None
    if not text:
        return None
    try:
        celsius = float(text)
    except ValueError:
        print(f"Malformed temperature data: '{text}'", file=sys.stderr)
        return None
    return celsius


def _convert_to_fahrenheit(celsius):
    return celsius * 9.0 / 5.0 + 32.0


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = None
    try:
        try:
            ser = serial.Serial(
                port=SERIAL_PORT,
                baudrate=BAUD_RATE,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=TIMEOUT,
            )
        except serial.SerialException as e:
            print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
            sys.exit(1)

        csv_writer = _open_csv()
        csv_writer.writerow(['Timestamp', 'Celsius', 'Fahrenheit'])
        csv_writer.flush()

        while _running:
            celsius = _read_temperature(ser)
            if celsius is not None:
                fahrenheit = _convert_to_fahrenheit(celsius)
                timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                _write_csv_row(csv_writer, timestamp, celsius, fahrenheit)
                csv_writer.flush()
            time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if ser is not None and ser.is_open:
            try:
                ser.close()
            except Exception:
                pass
        print("Program terminated gracefully.")


if __name__ == '__main__':
    main()

