import config
import signal
import sys
import time
import logging
import paho.mqtt.client as mqtt
import adafruit_dht
import board

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DEGREE_CELSIUS = '\u00B0C'
HOMIE_VERSION = '4.0'
DHT_PIN = getattr(board, f"D{config.dhtegpiopin}", None)

client = None
dht_device = None
running = True


def signal_handler(signum, frame):
    global running
    logger.info(f"Signal {signum} received, shutting down...")
    running = False


def publish_message(client, topic, payload):
    try:
        full_topic = f"homie/{config.homieclientid}/{topic}"
        info = client.publish(full_topic, str(payload), retain=config.mqttretainmessage, qos=config.mqttqos)
        info.wait_for_publish(timeout=5)
        logger.debug(f"Published to {full_topic}: {payload}")
    except Exception as e:
        logger.error(f"Failed to publish to {full_topic}: {e}")


def publish_homie_discovery(client):
    publish_message(client, "$state", "init")
    publish_message(client, "$homie", HOMIE_VERSION)
    publish_message(client, "$name", config.homieclientname)
    publish_message(client, "$nodes", config.homienodes)

    publish_message(client, f"{config.homienodes}/$name", "DHT22 Sensor")
    publish_message(client, f"{config.homienodes}/$properties", "temperature,humidity")

    publish_message(client, f"{config.homienodes}/temperature/$name", "Temperature")
    publish_message(client, f"{config.homienodes}/temperature/$unit", DEGREE_CELSIUS)
    publish_message(client, f"{config.homienodes}/temperature/$datatype", "float")
    publish_message(client, f"{config.homienodes}/temperature/$settable", "false")

    publish_message(client, f"{config.homienodes}/humidity/$name", "Humidity")
    publish_message(client, f"{config.homienodes}/humidity/$unit", "%")
    publish_message(client, f"{config.homienodes}/humidity/$datatype", "float")
    publish_message(client, f"{config.homienodes}/humidity/$settable", "false")

    publish_message(client, "$state", "ready")


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logger.info("Connected to MQTT broker")
        publish_homie_discovery(client)
    else:
        logger.error(f"Failed to connect to MQTT broker, reason code: {reason_code}")


def on_disconnect(client, userdata, flags, reason_code, properties):
    logger.warning(f"Disconnected from MQTT broker, reason code: {reason_code}")


def on_publish(client, userdata, mid, reason_code, properties):
    logger.debug(f"Message {mid} published")


def connect_mqtt():
    global client
    try:
        client = mqtt.Client(
            mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
            protocol=mqtt.MQTTv311
        )
        if config.mqttusername and config.mqttpassword:
            client.username_pw_set(config.mqttusername, config.mqttpassword)

        client.on_connect = on_connect
        client.on_disconnect = on_disconnect
        client.on_publish = on_publish

        client.will_set(f"homie/{config.homieclientid}/$state", "lost", retain=True, qos=config.mqttqos)
        client.connect(config.mqttbroker, port=config.mqttport, keepalive=60)
        client.loop_start()
        return True
    except Exception as e:
        logger.error(f"MQTT connection failed: {e}")
        return False


def read_dht22():
    global dht_device
    if dht_device is None:
        dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)

    for attempt in range(3):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                logger.info(f"Temperature = {temperature:.1f} {DEGREE_CELSIUS}")
                logger.info(f"Humidity = {humidity:.1f} %")
                return temperature, humidity
            else:
                logger.warning(f"Attempt {attempt + 1}: DHT22 returned None")
        except RuntimeError as e:
            logger.warning(f"Attempt {attempt + 1}: DHT22 read error: {e}")
        except Exception as e:
            logger.error(f"Attempt {attempt + 1}: Unexpected DHT22 error: {e}")
        time.sleep(2)
    logger.error("DHT22 read failed after 3 attempts")
    return None, None


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not connect_mqtt():
        sys.exit(1)

    try:
        while running:
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                publish_message(client, f"{config.homienodes}/temperature", f"{temperature:.1f}")
                publish_message(client, f"{config.homienodes}/humidity", f"{humidity:.1f}")
            else:
                logger.warning("Skipping publish due to read failure")

            if not running:
                break

            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)
    finally:
        if dht_device is not None:
            try:
                dht_device.exit()
            except Exception:
                pass
        if client is not None:
            try:
                client.loop_stop()
                client.disconnect()
            except Exception:
                pass
        logger.info("Cleanup complete")


if __name__ == "__main__":
    main()

