import time
import signal
import sys
import logging
import datetime
import json
import RPi.GPIO as GPIO

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
LED_PIN = 17
PWM_FREQ = 100          # Hz
MAX_BRIGHTNESS = 90     # percent
RAMP_DURATION = 600     # seconds
HOLD_DURATION = 10      # seconds
SENSOR_INTERVAL = 5     # seconds
SENSOR_RETRY_LIMIT = 3  # retries before giving up

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("led_cycle")

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_pwm = None


def _timestamp() -> str:
    return datetime.datetime.now().isoformat(timespec="seconds")


def _safe_float(value: str) -> float:
    try:
        return float(value)
    except (ValueError, TypeError):
        return 0.0


def _safe_int(value: str) -> int:
    try:
        return int(value)
    except (ValueError, TypeError):
        return 0


def _read_sensor(sensor_pin: int) -> tuple[float, float]:
    """Read temperature (C) and humidity (%) from a DHT22-like sensor.

    Returns (temp, hum) or (None, None) on failure.
    """
    for attempt in range(1, SENSOR_RETRY_LIMIT + 1):
        try:
            temp = _safe_float(sensor_data[0])
            hum = _safe_float(sensor_data[1])
            if temp is not None and hum is not None:
                return temp, hum
        except Exception as exc:
            log.warning("Sensor read attempt %d/%d failed: %s", attempt, SENSOR_RETRY_LIMIT, exc)
            time.sleep(0.5)
    return None, None


def _set_brightness(brightness: float) -> None:
    """Set LED brightness, clamped to [0, MAX_BRIGHTNESS]."""
    global _pwm
    if _pwm is None:
        return
    duty = max(0.0, min(brightness, MAX_BRIGHTNESS))
    _pwm.ChangeDutyCycle(duty)
    log.info("LED brightness set to %.1f%%", duty)


def _shutdown(signum=None, frame=None) -> None:
    """Emergency shutdown: turn LED off, stop PWM, release GPIO."""
    global _running, _pwm
    _running = False
    log.info("Shutdown requested (signal %s).", signum)
    if _pwm is not None:
        try:
            _pwm.ChangeDutyCycle(0)
        except Exception:
            pass
        try:
            _pwm.stop()
        except Exception:
            pass
    try:
        GPIO.cleanup()
    except Exception:
        pass
    sys.exit(0)


def main() -> None:
    global _pwm, _running

    # --- GPIO setup ----------------------------------------------------------
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)

    # --- PWM setup -----------------------------------------------------------
    try:
        _pwm = GPIO.PWM(LED_PIN, PWM_FREQ)
        _pwm.start(0)
    except Exception as exc:
        log.error("Failed to initialise PWM on BCM %d: %s", LED_PIN, exc)
        GPIO.cleanup()
        sys.exit(1)

    # --- Signal handlers -----------------------------------------------------
    signal.signal(signal.SIGINT, _shutdown)
    signal.signal(signal.SIGTERM, _shutdown)

    log.info("LED cycle started (pin %d, %d Hz).", LED_PIN, PWM_FREQ)

    # --- Main loop -----------------------------------------------------------
    while _running:
        # Sunrise ramp: 0 -> MAX_BRIGHTNESS
        log.info("Starting sunrise ramp (%d%% max).", MAX_BRIGHTNESS)
        for brightness in range(0, MAX_BRIGHTNESS + 1, 10):
            if not _running:
                break
            _set_brightness(brightness)
            time.sleep(min(RAMP_DURATION / 100, 1.0))
        if _running:
            _set_brightness(MAX_BRIGHTNESS)
            time.sleep(HOLD_DURATION)

        # Hold at maximum brightness
        if _running:
            log.info("Holding at %d%% for %d seconds.", MAX_BRIGHTNESS, HOLD_DURATION)
            for _ in range(HOLD_DURATION * 10):
                if not _running:
                    break
                time.sleep(0.1)

        # Sunset ramp: MAX_BRIGHTNESS -> 0
        log.info("Starting sunset ramp (%d%% max).", MAX_BRIGHTNESS)
        for brightness in range(MAX_BRIGHTNESS, -1, -10):
            if not _running:
                break
            _set_brightness(brightness)
            time.sleep(min(RAMP_DURATION / 100, 1.0))
        if _running:
            _set_brightness(0)
            time.sleep(HOLD_DURATION)

        # Hold at 0
        if _running:
            log.info("Holding at 0%% for %d seconds.", HOLD_DURATION)
            for _ in range(HOLD_DURATION * 10):
                if not _running:
                    break
                time.sleep(0.1)

    # --- Cleanup -------------------------------------------------------------
    _shutdown()


if __name__ == "__main__":
    main()

