import time
import logging
import signal
import sys
import smbus2
from ina219 import INA219, DeviceRangeError

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

I2C_BUS = 1
SUPPLY_INA219_ADDRESS = 0x12
BATTERY_INA219_ADDRESS = 0x13
LOOP_INTERVAL = 2.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def initialize_ina219(shunt_resistor, busnum, address, label):
    try:
        ina = INA219(shunt_resistor, busnum=busnum, address=address)
        ina.configure()
        logging.info(f"Initialized {label} INA219 at 0x{address:02X}")
        return ina
    except Exception as e:
        logging.error(f"Failed to initialize {label} INA219 at 0x{address:02X}: {e}")
        return None

def read_and_print_ina219_data(ina, label):
    if ina is None:
        logging.warning(f"Skipping {label} data (INA219 not initialized)")
        return
    try:
        voltage = ina.voltage()
        current = ina.current()
        power = ina.power()
        if current > 0:
            state = "Charging"
        elif current < 0:
            state = "Discharging"
        else:
            state = "Idle"
        print(f"{label}: {voltage:.3f}V, {current:.3f}mA, {power:.3f}mW, {state}")
    except DeviceRangeError:
        logging.warning(f"Skipping {label} data (out of device range)")
    except Exception as e:
        logging.error(f"Error reading {label} data: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    supply_ina = initialize_ina219(0.00725, I2C_BUS, SUPPLY_INA219_ADDRESS, "Supply")
    battery_ina = initialize_ina219(0.005, I2C_BUS, BATTERY_INA219_ADDRESS, "Battery")

    if supply_ina is None and battery_ina is None:
        logging.error("No INA219 sensors initialized. Exiting.")
        sys.exit(1)

    try:
        while running:
            read_and_print_ina219_data(supply_ina, "Supply")
