import time
import board
import busio
import adafruit_ahtx0

# Constants
READ_INTERVAL_SECONDS = 5
TEMP_MIN_C = -40
TEMP_MAX_C = 85
HUM_MIN_PCT = 0
HUM_MAX_PCT = 100


def initialize_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_sensor(i2c_bus):
    """Initialize the AHT20 sensor on the given I2C bus."""
    try:
        sensor = adafruit_ahtx0.AHTx0(i2c_bus)
        return sensor
    except ValueError as e:
        print(f"AHT20 not detected on I2C bus: {e}")
        return None
    except Exception as e:
        print(f"Error initializing AHT20 sensor: {e}")
        return None


def read_sensor_data(sensor):
    """Read temperature and humidity from the sensor. Returns (temp, hum) or (None, None)."""
    try:
        temperature = sensor.temperature
        humidity = sensor.relative_humidity
        return temperature, humidity
    except OSError as e:
        print(f"I2C bus error reading sensor data: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected error reading sensor data: {e}")
        return None, None


def validate_data(temperature, humidity):
    """Validate that temperature and humidity readings are within expected ranges."""
    if temperature is None or humidity is None:
        return False
    if not (TEMP_MIN_C <= temperature <= TEMP_MAX_C):
        print(f"Temperature out of range: {temperature} C")
        return False
    if not (HUM_MIN_PCT <= humidity <= HUM_MAX_PCT):
        print(f"Humidity out of range: {humidity} %")
        return False
    return True


def display_data(temperature, humidity):
    """Print the temperature and humidity data with a timestamp."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    print(f"{timestamp} - Temperature: {temperature:.1f} C Humidity: {humidity:.1f} %")


def main():
    """Main loop: initialize sensor, read data, validate, display, and handle errors."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        i2c_bus.deinit()
        return

    try:
        while True:
            temperature, humidity = read_sensor_data(sensor)

            if temperature is not None and humidity is not None:
                if validate_data(temperature, humidity):
                    display_data(temperature, humidity)
                else:
                    print("Invalid sensor data. Skipping this reading.")
            else:
                print("Failed to read valid data from the sensor.")

            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    finally:
        try:
            i2c_bus.deinit()
        except Exception:
            pass


if __name__ == "__main__":
    main()

