import signal
import sys
import time
import logging
import paho.mqtt.client as mqtt
from gpiozero import DHT22
from gpiozero.exc import GPIOZeroError

import config
import helpers.mqtt_helpers as mqtt_helper
import helpers.dht22 as dht22_helper

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DEGREE_CELSIUS = '\u00B0C'

running = True
dht22_sensor = None
mqtt_client = None


def signal_handler(signum, frame):
    global running
    logger.info(f"Signal {signum} received, shutting down...")
    running = False


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logger.info("Connected to MQTT broker")
    else:
        logger.error(f"Failed to connect to MQTT broker, reason code: {reason_code}")


def on_disconnect(client, userdata, flags, reason_code, properties):
    logger.warning(f"Disconnected from MQTT broker, reason code: {reason_code}")


def on_publish(client, userdata, mid, reason_code, properties):
    logger.debug(f"Message {mid} published")


def on_subscribe(client, userdata, mid, n, properties):
    logger.debug(f"Subscribed to {mid}")


def on_unsubscribe(client, userdata, mid, properties):
    logger.debug(f"Unsubscribed from {mid}")


def on_connect_callback(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        result, mid = client.subscribe(config.mqttsubscribetopic)
        if result == mqtt.MQTT_ERR_SUCCESS:
            logger.info(f"Subscribed to {mid}")
        else:
            logger.error(f"Failed to subscribe to {mid}, reason code: {result}")
    else:
        logger.error(f"Failed to connect to MQTT broker, reason code: {reason_code}")


def on_disconnect_callback(client, userdata, flags, reason_code, properties):
    logger.warning(f"Disconnected from MQTT broker, reason code: {reason_code}")


def on_publish_callback(client, userdata, mid, reason_code, properties):
    logger.debug(f"Message {mid} published")


def main():
    global dht22_sensor, mqtt_client

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        dht22_sensor = DHT22(config.dhtgpiopin)
        logger.info(f"DHT22 sensor initialized on GPIO {config.dhtgpiopin}")
    except GPIOZeroError as e:
        logger.error(f"Failed to initialize DHT22 sensor on GPIO {config.dhtgpiopin}: {e}")
        sys.exit(1)

    mqtt_client = mqtt.Client(
        callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
        client_id=config.mqttclientid
    )
    mqtt_client.on_connect = on_connect_callback
    mqtt_client.on_disconnect = on_disconnect_callback
    mqtt_client.on_publish = on_publish_callback

    if config.mqttusername:
        mqtt_client.username_pw_set(config.mqttusername, config.mqttpassword)

    mqtt_client.will_set(
        config.mqttsubscribetopic,
        payload="lost connection",
        qos=config.mqttqos,
        retain=config.mqttretainmessage
    )

    mqtt_client.connect(config.mqttbroker, port=config.mqttport, keepalive=60)
    mqtt_client.loop_start()

    try:
        while running:
            try:
                temperature, humidity = dht22_helper.read_dht22(dht22_sensor)
                if temperature is not None and humidity is not None:
                    temperature = round(temperature, 1)
                    humidity = round(humidity, 1)
                    logger.info(f"Temperature = {temperature}{DEGREE_CELSIUS}")
                    logger.info(f"Humidity = {humidity}%")

                    mqtt_helper.publish_mqtt(
                        config.mqttbroker,
                        config.mqttport,
                        config.mqttclientid,
                        config.homieclientid,
                        config.homienodes,
                        "temperature",
                        temperature,
                        config.mqttqos,
                        config.mqttretainmessage
                    )
                    mqtt_helper.publish_mqtt(
                        config.mqttbroker,
                        config.mqttport,
                        config.mqttclientid,
                        config.homieclientid,
                        config.homienodes,
                        "humidity",
                        humidity,
                        config.mqttqos,
                        config.mqttretainmessage
                    )
                else:
                    logger.warning("Failed to read DHT22 sensor data")
            except RuntimeError as e:
                logger.warning(f"Failed to read DHT22 sensor data: {e}")
            except Exception as e:
                logger.error(f"An unexpected error occurred: {e}")

            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        if mqtt_client:
            try:
                mqtt_client.loop_stop()
                mqtt_client.disconnect()
                logger.info("MQTT client disconnected")
            except Exception as e:
                logger.error(f"Error disconnecting MQTT client: {e}")
        if dht22_sensor:
            try:
                dht22_sensor.close()
                logger.info("DHT22 sensor closed")
            except Exception as e:
                logger.error(f"Error closing DHT22 sensor: {e}")
        logger.info("Program finished")


if __name__ == '__main__':
    main()

