import signal
import sys
import time
from datetime import datetime

import board
import adafruit_dht

# --- Configuration -----------------------------------------------------------
DHT_PIN = board.D17          # BCM GPIO17 (physical pin 11)
READ_INTERVAL_S = 2.0        # DHT22 requires at least 2 s between reads
MAX_RETRIES = 3              # retry count for transient RuntimeError

# --- Globals for cleanup -----------------------------------------------------
_sensor = None
_running = True


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _init_sensor():
    """Initialise the DHT22; raise on failure so caller can decide."""
    return adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)


def _read_sensor(sensor):
    """Return (temperature, humidity) or (None, None) after retries."""
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            temp = sensor.temperature
            hum = sensor.humidity
            if temp is None or hum is None:
                raise RuntimeError("Sensor returned None")
            return temp, hum
        except RuntimeError as exc:
            # DHT22 single-wire protocol is flaky; retry a few times.
            if attempt < MAX_RETRIES:
                time.sleep(0.5)
            else:
                raise
        except Exception as exc:
            # Unexpected error — log and stop retrying.
            raise
    return None, None


def main():
    global _sensor

    # Install signal handlers for clean shutdown.
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        _sensor = _init_sensor()
    except Exception as exc:
        print(f"Failed to initialise DHT22 on GPIO17: {exc}", file=sys.stderr)
        sys.exit(1)

    print("DHT22 sensor initialised. Reading every 2 s. Press Ctrl+C to stop.")

    while _running:
        timestamp = datetime.now().isoformat(timespec="seconds")
        try:
            temp, hum = _read_sensor(_sensor)
            print(f"{timestamp} Temp: {temp:.1f}C Humidity: {hum:.1f}%")
        except RuntimeError as exc:
            # Transient read failure — report and continue.
            print(f"{timestamp} Read error: {exc}", file=sys.stderr)
        except Exception as exc:
            # Unexpected error — log and stop.
            print(f"{timestamp} Unexpected error: {exc}", file=sys.stderr)
            break

        # Sleep in small increments so signals are caught promptly.
        slept = 0.0
        while _running and slept < READ_INTERVAL_S:
            time.sleep(0.1)
            slept += 0.1

    # Clean resource release on every exit path.
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
    print("\nSensor released. Exiting.")


if __name__ == "__main__":
    main()

