import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)

PWM_FREQ = 100          # Hz
DUTY_CYCLE_STEPS = 10   # percent
CHECK_INTERVAL = 5      # seconds
TEMP_CHECK_INTERVAL = 5  # seconds

_running = True


def _handle_signal(signum, frame):
    global _running
    logger.info("Received signal %s, shutting down...", signum)
    _running = False


def get_system_temperature():
    """Return the CPU temperature in degrees Celsius, or None on error."""
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            timeout=5,
            check=True,
        )
        return float(result.stdout.split("=")[1].split("'")[0])
    except (subprocess.CalledProcessError, IndexError, ValueError, subprocess.TimeoutExpired) as exc:
        logger.error("Failed to read temperature: %s", exc)
        return None


def get_duty_cycle(temperature):
    """Map temperature to a stepped duty cycle (0–100 %)."""
    if temperature is None:
        return 0
    return int(round(100.0 - (temperature / 70.0) * 100.0))


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    if GPIO is None:
        logger.warning("RPi.GPIO not available; running in degraded mode (no hardware PWM).")
        return

    fan_pin = 14
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(fan_pin, GPIO.OUT, initial=GPIO.LOW)
    except Exception as exc:
        logger.warning("Failed to initialize GPIO%d: %s. Running in degraded mode.", fan_pin, exc)
        return

    pwm = None
    try:
        try:
            pwm = GPIO.PWM(fan_pin, PWM_FREQ)
            pwm.start(0)
        except Exception as exc:
            logger.warning("Failed to start PWM on GPIO%d: %s. Running in degraded mode.", fan_pin, exc)
            return

        last_duty = 0
        logger.info("PWM fan control started on GPIO%d @ %d Hz.", fan_pin, PWM_FREQ)

        while _running:
            temp = get_system_temperature()
            duty = get_duty_cycle(temp)

            if temp is not None:
                logger.info("Temp: %.1f°C  Fan duty: %d%%", temp, duty)
            else:
                logger.warning("Temp unavailable; keeping last duty cycle %d%%", last_duty)

            if duty != last_duty:
                try:
                    pwm.ChangeDutyCycle(duty)
                    last_duty = duty
                except Exception as exc:
                    logger.warning("Failed to update PWM duty cycle: %s", exc)

            # Sleep in small increments so signals are caught promptly
            slept = 0.0
            while _running and slept < CHECK_INTERVAL:
                time.sleep(0.2)
                slept += 0.2

    finally:
        if pwm is not None:
            try:
                pwm.stop()
            except Exception:
                pass
        try:
            GPIO.output(fan_pin, GPIO.LOW)
        except Exception:
            pass
        GPIO.cleanup()
        logger.info("GPIO cleaned up. Exiting.")


if __name__ == "__main__":
    main()

