import RPi.GPIO as GPIO
import time
import sys

LED_PIN = 17
led_state = False

def cleanup_gpio():
    """Drive the LED low and release the GPIO pin."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()

try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
except Exception as e:
    print(f"Error setting up GPIO: {e}")
    sys.exit(1)

try:
    while True:
        try:
            user_input = input("Enter 'on' or 'off' (or 'q' to quit): ")
        except EOFError:
            print("\nExiting program.")
            break

        if user_input.lower() == 'q':
            print("\nExiting program.")
            break

        if user_input.lower() == 'on':
            led_state = True
            GPIO.output(LED_PIN, GPIO.HIGH)
        elif user_input.lower() == 'off':
            led_state = False
            GPIO.output(LED_PIN, GPIO.LOW)
        else:
            print("Invalid input")

        print(f"LED state: {led_state}")

        time.sleep(0.1)

except KeyboardInterrupt:
    print("\nExiting program.")
finally:
    cleanup_gpio()

