# soil_moisture_monitor.py
# Raspberry Pi 4, Bookworm, I2C soil moisture sensor, pump control

import signal
import sys
import time
import board
import busio
import adafruit_seesaw.seesaw
from gpiozero import OutputDevice

# --- Configuration -----------------------------------------------------------
I2C_SCL_PIN = board.SCL   # GPIO3 (BCM)
I2C_SDA_PIN = board.SDA   # GPIO2 (BCM)
I2C_BUS = 1               # /dev/i2c-1 on Raspberry Pi 4
PUMP_PIN = 17             # BCM GPIO17
MOISTURE_THRESHOLD = 300
READ_INTERVAL = 10         # seconds between readings

# --- Globals for cleanup -----------------------------------------------------
pump = None
i2c = None
sensor = None
running = True


def cleanup():
    """Turn the pump off and release hardware resources."""
    global pump, i2c, sensor
    if pump is not None:
        try:
            pump.off()
            pump.close()
        except Exception:
            pass
        pump = None
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass
        i2c = None
    if sensor is not None:
        try:
            sensor.deinit()
        except Exception:
            pass
        sensor = None


def handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global running
    running = False


def read_moisture():
    """Return the current soil moisture reading, or None on error."""
    if sensor is None:
        return None
    try:
        return sensor.moisture_read()
    except (OSError, ValueError) as exc:
        print(f"Sensor read error: {exc}")
        return None
    except Exception as exc:
        print(f"Unexpected sensor error: {exc}")
        return None


def control_pump(moisture):
    """Drive the pump and print a message each state change."""
    if moisture < MOISTURE_THRESHOLD:
        pump.on()
        print("Water Pump ON: Soil too dry")
    else:
        pump.off()
        print("Water Pump OFF: Soil moisture sufficient")


def main():
    global pump, i2c, sensor

    # --- Signal handlers -----------------------------------------------------
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    # --- Hardware initialization --------------------------------------------
    try:
        i2c = busio.I2C(I2C_SCL_PIN, I2C_SDA_PIN)
    except Exception as exc:
        print(f"Failed to initialize I2C bus: {exc}")
        sys.exit(1)

    try:
        sensor = adafruit_seesaw.seesaw.Seesaw(i2c, addr=0x5A)
    except Exception as exc:
        print(f"Failed to initialize soil moisture sensor (0x5A): {exc}")
        sys.exit(1)

    # --- Pump initialization -----------------------------------------------
    try:
        pump = OutputDevice(PUMP_PIN, active_high=True, initial_value=False)
    except Exception as exc:
        print(f"Failed to initialize pump on GPIO{PUMP_PIN}: {exc}")
        cleanup()
        sys.exit(1)

    print("Soil moisture monitor started. Press Ctrl+C to exit.")

    # --- Main loop ----------------------------------------------------------
    try:
        while running:
            moisture = read_moisture()
            if moisture is not None:
                print(f"Soil Moisture: {moisture}")
                control_pump(moisture)
            else:
                print("Skipping pump control due to sensor read failure.")

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while slept < READ_INTERVAL and running:
                time.sleep(0.5)
                slept += 0.5
    finally:
        cleanup()
        print("Program terminated cleanly.")


if __name__ == "__main__":
    main()

