import signal
import sys
import time
import logging

import RPi.GPIO as GPIO

SENSOR_PINS = [17, 27, 22]
POLL_INTERVAL = 1.0

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("sensor_poll")

_running = True


def _handle_signal(signum, frame):
    global _running
    log.info("Received signal %s — shutting down …", signum)
    _running = False


def setup_gpio(pins):
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in pins:
        GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)


def read_sensor(pin):
    try:
        return GPIO.input(pin)
    except Exception as exc:
        log.error("Error reading GPIO %d: %s", pin, exc)
        return None


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        setup_gpio(SENSOR_PINS)
    except Exception as exc:
        log.error("GPIO initialization failed: %s", exc)
        GPIO.cleanup()
        sys.exit(1)

    log.info("Monitoring pins %s every %.1f s", SENSOR_PINS, POLL_INTERVAL)

    try:
        while _running:
            for pin in SENSOR_PINS:
                val = read_sensor(pin)
                if val is not None:
                    label = f"Response for sensor {SENSOR_PINS.index(pin) + 1}"
                    if val:
                        log.info("%s: HIGH", label)
                    else:
                        log.info("%s: LOW", label)
            time.sleep(POLL_INTERVAL)
    except Exception as exc:
        log.error("Unexpected error in main loop: %s", exc)
    finally:
        GPIO.cleanup()
        log.info("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

