import signal
import sys
import time
import requests
import json
import RPi.GPIO as GPIO

SENSOR_PIN = 4
SERVER_URL = 'http://localhost:5000/sensor'
USERNAME = 'user'
PASSWORD = 'pass'
POLL_INTERVAL = 5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def init_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_OFF)

def read_sensor():
    try:
        return GPIO.input(SENSOR_PIN)
    except Exception as e:
        print(f"Error reading sensor: {e}")
        return None

def send_data(sensor_value):
    payload = {'sensor': 'digital_input', 'value': sensor_value}
    headers = {'Authorization': f'Basic {USERNAME}:{PASSWORD}', 'Content-Type': 'application/json'}
    try:
        response = requests.post(SERVER_URL, data=json.dumps(payload), headers=headers, timeout=10)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        print(f"Error sending data: {e}")

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)
    try:
        init_gpio()
        while _running:
            sensor_value = read_sensor()
            if sensor_value is not None:
                send_data(sensor_value)
            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        GPIO.cleanup()
        print("GPIO cleaned up. Exiting.")

if __name__ == '__main__':
    main()

