            print(f"Error sending data: {e}", file=sys.stderr)
    elif args and args[0] == "write":
        data = " ".join(args[1:])
        try:
            with open(LOG_FILE_NAME, "a", encoding="utf-8") as f:
                f.write(data + "\n")
            print(f"Wrote to log: {data}")
        except OSError as e:
            print(f"Error writing to log file: {e}", file=sys.stderr)
    elif args and args[0] == "exit":
        api_call_active = False
        if receive_thread and receive_thread.is_alive():
            receive_thread.join(timeout=2.0)
        print("Exiting program.")
        sys.exit(0)
    else:
        print("Invalid command. Try 'help'.")


def signal_handler(signum, frame):
    """Handle SIGINT and SIGTERM for clean shutdown."""
    print(f"\nReceived signal {signum}. Shutting down...")
    api_call_active = False
    if receive_thread and receive_thread.is_alive():
        receive_thread.join(timeout=2.0)
    sys.exit(0)


def main() -> None:
    """Main function to run the DOG command-line interface."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        dog.start()
    except Exception as e:
        print(f"Error initializing DOG library: {e}", file=sys.stderr)
        sys.exit(1)

    print("DOG CLI ready. Type 'help' for commands.")
    while True:
        try:
            command = input("DOG> ").strip()
            if command:
                handle_command(command)
        except EOFError:
            print("\nEOF received. Exiting.")
            break
        except KeyboardInterrupt:
            print("\nKeyboard interrupt received. Exiting.")
            break


if __name__ == "__main__":
    main()

