import asyncio
import json
import logging
import os
import signal
import sys
import time
from collections import deque

import numpy as np
import sounddevice as sd
import tflite_runtime.interpreter as tflite

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "sampling_rate": 16000,
    "sensitivity": 0.5,
    "thresholds": {
        "positive": 0.7,
        "negative": -0.7
    },
    "keywords": ["hello", "how are you", "goodbye", "see you later"],
    "led_pin": 17,
    "cloud_endpoint": None,
    "heartbeat_interval": 60,
    "update_interval": 300,
    "log_level": "INFO",
    "model_path": "model.tflite"
}

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s"
)

shutdown_event = asyncio.Event()


def load_config(config_file):
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        logging.info("Configuration loaded from %s", config_file)
        return config
    except FileNotFoundError:
        logging.warning("Configuration file not found. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error("Error decoding JSON from %s: %s. Using defaults.", config_file, e)
        return DEFAULT_CONFIG.copy()


def check_config(config, config_file):
    if config.get("sampling_rate") is None:
        config["sampling_rate"] = DEFAULT_CONFIG["sampling_rate"]
    if config.get("sensitivity") is None:
        config["sensitivity"] = DEFAULT_CONFIG["sensitivity"]
    if config.get("thresholds") is None:
        config["thresholds"] = DEFAULT_CONFIG["thresholds"]
    if config.get("keywords") is None:
        config["keywords"] = DEFAULT_CONFIG["keywords"]
    if config.get("led_pin") is None:
        config["led_pin"] = DEFAULT_CONFIG["led_pin"]
    if config.get("cloud_endpoint") is None:
        config["cloud_endpoint"] = DEFAULT_CONFIG["cloud_endpoint"]
    if config.get("heartbeat_interval") is None:
        config["heartbeat_interval"] = DEFAULT_CONFIG["heartbeat_interval"]
    if config.get("update_interval") is None:
        config["update_interval"] = DEFAULT_CONFIG["update_interval"]
    if config.get("log_level") is None:
        config["log_level"] = DEFAULT_CONFIG["log_level"]
    if config.get("model_path") is None:
        config["model_path"] = DEFAULT_CONFIG["model_path"]
    return config


def signal_handler(sig, frame):
    logging.info("Shutdown signal received.")
    shutdown_event.set()


def heartbeat_task(config):
    while not shutdown_event.is_set():
        logging.info("Heartbeat sent.")
        try:
            asyncio.create_task(send_heartbeat(config))
        except Exception as e:
            logging.error("Error sending heartbeat: %s", e)
        shutdown_event.wait(config["heartbeat_interval"])


def send_heartbeat(config):
    try:
        import requests
        response = requests.get(config["cloud_endpoint"], timeout=5)
        response.raise_for_status()
        logging.info("Heartbeat sent successfully.")
    except requests.exceptions.RequestException as e:
        logging.error("Error sending heartbeat: %s", e)


def update_config_task(config):
    while not shutdown_event.is_set():
        try:
            if os.path.exists(CONFIG_FILE):
                with open(CONFIG_FILE, "r") as f:
                    user_config = json.load(f)
                merged = {**config, **user_config}
                with open(CONFIG_FILE, "w") as f:
                    json.dump(merged, f, indent=4)
                logging.info("Configuration updated successfully.")
            else:
                logging.info("No configuration file found. Creating one.")
                with open(CONFIG_FILE, "w") as f:
                    json.dump(config, f, indent=4)
        except Exception as e:
            logging.error("Error updating configuration: %s", e)
        shutdown_event.wait(config["update_interval"])


def log_resource_usage_task(config):
    while not shutdown_event.is_set():
        try:
            import psutil
            cpu_percent = psutil.cpu_percent(interval=None)
            memory_percent = psutil.virtual_memory().percent
            logging.info("CPU: %s%%, Memory: %s%%", cpu_percent, memory_percent)
        except Exception as e:
            logging.error("Error logging resource usage: %s", e)
        shutdown_event.wait(60)


def voice_detection_task(config):
    try:
        with sd.InputStream(samplerate=config["sampling_rate"], channels=1, dtype='float32') as stream:
            while not shutdown_event.is_set():
                audio_data = stream.read(config["sampling_rate"], blocking=True)
                if audio_data is None:
                    logging.warning("No audio data received.")
                    continue
                if len(audio_data) == 0:
                    continue
                voice_detection_loop(config, audio_data)
    except sd.PortAudioError as e:
        logging.error("Audio device error: %s", e)
    except Exception as e:
        logging.error("Error in voice detection task: %s", e)


def voice_detection_loop(config, audio_data):
    try:
        import speech_recognition as sr
        recognizer = sr.Recognizer()
        try:
            audio = sr.AudioData(audio_data, sr=None)
            try:
                text = recognizer.recognize_google(audio)
                logging.info("Recognized: %s", text)
                process_text(config, text)
            except sr.UnknownValueError:
                logging.warning("Could not understand audio")
            except sr.RequestError as e:
                logging.error("Could not request results from Google Web Speech API; %(e)s", {"e": e})
        except Exception as e:
            logging.error("Error during speech recognition: %s", e)
    except Exception as e:
        logging.error("Error in voice detection loop: %s", e)


def process_text(config, text):
    try:
        words = text.lower().split()
        for word in words:
            if word in config["keywords"]:
                logging.info("Keyword detected: %s", word)
                trigger_alert(config, word)
    except Exception as e:
        logging.error("Error processing text: %s", e)


def trigger_alert(config, keyword):
    try:
        import gpiozero
        led = gpiozero.LED(config["led_pin"])
        led.on()
        logging.info("Alert triggered for keyword: %s", keyword)
        time.sleep(2)
        led.off()
    except Exception as e:
        logging.error("Error triggering alert: %s", e)


def sentiment_analysis_task(config):
    try:
        interpreter = tflite.Interpreter(model_path=config["model_path"])
        interpreter.allocate_tensors()
        input_details = interpreter.get_input_details()
        output_details = interpreter.get_output_details()
        logging.info("TensorFlow Lite model loaded successfully.")
    except Exception as e:
        logging.error("Error loading TensorFlow Lite model: %s", e)
        return

    try:
        while not shutdown_event.is_set():
            audio_data = sd.read(config["sampling_rate"], blocking=True)
            if audio_data is None:
                continue
            if len(audio_data) == 0:
                continue
            try:
                audio_np = np.frombuffer(audio_data, dtype=np.int16)
                audio_np = audio_np.astype(np.float32)
                audio_np = audio_np / 32768.0
                input_data = np.expand_dims(audio_np, axis=0)
                interpreter.set_tensor(input_details[0]["index"], input_data)
                interpreter.invoke()
                output_data = interpreter.get_tensor(output_details[0]["index"])
                sentiment = float(output_data[0][0])
                logging.info("Sentiment: %.2f", sentiment)
                if sentiment > config["thresholds"]["positive"]:
                    logging.warning("Positive sentiment detected!")
                    trigger_alert(config, "positive")
                elif sentiment < config["thresholds"]["negative"]:
                    logging.warning("Negative sentiment detected!")
                    trigger_alert(config, "negative")
            except Exception as e:
                logging.error("Error during sentiment analysis: %s", e)
    except Exception as e:
        logging.error("Error in sentiment analysis task: %s", e)


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    config = check_config(config, CONFIG_FILE)

    logging.info("Starting voice-controlled assistant...")
    logging.info("Config: %s", config)

    tasks = [
        asyncio.create_task(heartbeat_task(config)),
        asyncio.create_task(update_config_task(config)),
        asyncio.create_task(log_resource_usage_task(config)),
        asyncio.create_task(voice_detection_task(config)),
        asyncio.create_task(sentiment_analysis_task(config))
    ]

    try:
        while not shutdown_event.is_set():
            for task in tasks:
                if not task.done():
                    task.get()
    except asyncio.CancelledError:
        pass
    finally:
        logging.info("Shutting down...")
        for task in tasks:
            task.cancel()
        shutdown_event.set()
        for task in tasks:
            try:
                task.result()
            except asyncio.CancelledError:
                pass
        logging.info("Voice-controlled assistant stopped.")


if __name__ == "__main__":
    main()

