                logging.warning("Could not understand audio")
            except sr.RequestError as e:
                logging.error("Could not request results from Google Web Speech API; %(e)s", {"e": e})
        except Exception as e:
            logging.error("Error during speech recognition: %s", e)
    except Exception as e:
        logging.error("Error in voice detection loop: %s", e)


def process_text(config, text):
    try:
        words = text.lower().split()
        for word in words:
            if word in config["keywords"]:
                logging.info("Keyword detected: %s", word)
                trigger_alert(config, word)
    except Exception as e:
        logging.error("Error processing text: %s", e)


def trigger_alert(config, keyword):
    try:
        import gpiozero
        led = gpiozero.LED(config["led_pin"])
        led.on()
        logging.info("Alert triggered for keyword: %s", keyword)
        time.sleep(2)
        led.off()
    except Exception as e:
        logging.error("Error triggering alert: %s", e)


def sentiment_analysis_task(config):
    try:
        interpreter = tflite.Interpreter(model_path=config["model_path"])
        interpreter.allocate_tensors()
        input_details = interpreter.get_input_details()
        output_details = interpreter.get_output_details()
        logging.info("TensorFlow Lite model loaded successfully.")
    except Exception as e:
        logging.error("Error loading TensorFlow Lite model: %s", e)
        return

    try:
        while not shutdown_event.is_set():
            audio_data = sd.read(config["sampling_rate"], blocking=True)
            if audio_data is None:
                continue
            if len(audio_data) == 0:
                continue
            try:
                audio_np = np.frombuffer(audio_data, dtype=np.int16)
                audio_np = audio_np.astype(np.float32)
                audio_np = audio_np / 32768.0
                input_data = np.expand_dims(audio_np, axis=0)
                interpreter.set_tensor(input_details[0]["index"], input_data)
                interpreter.invoke()
                output_data = interpreter.get_tensor(output_details[0]["index"])
                sentiment = float(output_data[0][0])
                logging.info("Sentiment: %.2f", sentiment)
                if sentiment > config["thresholds"]["positive"]:
                    logging.warning("Positive sentiment detected!")
                    trigger_alert(config, "positive")
                elif sentiment < config["thresholds"]["negative"]:
                    logging.warning("Negative sentiment detected!")
                    trigger_alert(config, "negative")
            except Exception as e:
                logging.error("Error during sentiment analysis: %s", e)
    except Exception as e:
        logging.error("Error in sentiment analysis task: %s", e)


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    config = check_config(config, CONFIG_FILE)

    logging.info("Starting voice-controlled assistant...")
    logging.info("Config: %s", config)

    tasks = [
        asyncio.create_task(heartbeat_task(config)),
        asyncio.create_task(update_config_task(config)),
        asyncio.create_task(log_resource_usage_task(config)),
        asyncio.create_task(voice_detection_task(config)),
        asyncio.create_task(sentiment_analysis_task(config))
    ]

    try:
        while not shutdown_event.is_set():
            for task in tasks:
                if not task.done():
                    task.get()
    except asyncio.CancelledError:
        pass
    finally:
        logging.info("Shutting down...")
        for task in tasks:
            task.cancel()
        shutdown_event.set()
        for task in tasks:
            try:
                task.result()
            except asyncio.CancelledError:
                pass
        logging.info("Voice-controlled assistant stopped.")


if __name__ == "__main__":
    main()

