            self.end_headers()
            self.wfile.write(body.encode())
        else:
            self.send_response(404)
            self.end_headers()

    def log_message(self, format, *args):
        logger.debug(f"{self.client_address[0]} - {format % args}")


def main():
    global server
    try:
