        logger.error(f"Could not bind to {HOST_NAME}:{PORT_NUMBER}: {e}")
    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup()


if __name__ == '__main__':
    main()

