import signal
import threading
import logging
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
logger = logging.getLogger(__name__)


class OutputPin:
    """Generic output pin with validation and shutdown support."""

    def __init__(self, name, pin_num, initial_value=0):
        if not isinstance(name, str) or not name:
            raise ValueError("name must be a non-empty string")
        if not isinstance(pin_num, int) or not (0 <= pin_num <= 27):
            raise ValueError("pin_num must be an integer in 0..27")
        if initial_value not in (0, 1):
            raise ValueError("initial_value must be 0 or 1")

        self.name = name
        self.pin_num = pin_num
        self._value = initial_value
        self._lock = threading.Lock()

        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(self.pin_num, GPIO.OUT, initial=GPIO.LOW)

        logger.info("OutputPin '%s' (BCM %d) initialised to %d", name, pin_num, initial_value)

    def set_value(self, value):
        if value not in (0, 1):
            raise ValueError("value must be 0 or 1")
        with self._lock:
            self._value = value
            GPIO.output(self.pin_num, value)
            logger.debug("OutputPin '%s' set to %d", self.name, value)

    def get_value(self):
        with self._lock:
            return self._value

    def shutdown(self):
        try:
            GPIO.setup(self.pin_num, GPIO.IN)
            logger.info("OutputPin '%s' (BCM %d) shutdown, set to input", self.name, self.pin_num)
        except Exception as exc:
            logger.error("Error during shutdown of '%s' (BCM %d): %s", self.name, self.pin_num, exc)


class TriggerPin(OutputPin):
    """OutputPin that generates a 100 µs high pulse on trigger."""

    def __init__(self, name, pin_num, pulse_us=100):
        super().__init__(name, pin_num, initial_value=0)
        self._pulse_us = pulse_us
        self._lock = threading.Lock()

    def trigger(self):
        with self._lock:
            GPIO.output(self.pin_num, 1)
            time.sleep(self._pulse_us / 1_000_000.0)
            GPIO.output(self.pin_num, 0)

    def shutdown(self):
        super().shutdown()


# ---------------------------------------------------------------------------
# Signal handling for clean shutdown on Ctrl-C / SIGTERM
# ---------------------------------------------------------------------------
_pins = []


def _signal_handler(signum, frame):
    logger.info("Received signal %d, shutting down pins", signum)
    for pin in _pins:
        try:
            pin.shutdown()
        except Exception as exc:
            logger.error("Error shutting down '%s': %s", pin.name, exc)
    raise SystemExit(0)


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


if __name__ == "__main__":
    try:
        example_output = OutputPin("ExampleOutput", 21, initial_value=0)
        example_trigger = TriggerPin("ExampleTrigger", 20, pulse_us=100)
        _pins.extend([example_output, example_trigger])
        logger.info("Pins initialised: %s, %s", example_output.name, example_trigger.name)
        # Example trigger pulse (uncomment to run)
        # example_trigger.trigger()
    except Exception as exc:
        logger.error("Initialisation failed: %s", exc)
    finally:
        for pin in _pins:
            try:
                pin.shutdown()
            except Exception as exc:
                logger.error("Error during final shutdown of '%s': %s", pin.name, exc)

