# Initialize I2C bus
i2c = None
try:
    i2c = busio.I2C(board.SCL, board.SDA)
except Exception as e:
    print(f"Fatal: Failed to initialize I2C bus: {e}")
    raise SystemExit(1)

# Initialize fingerprint sensor
sensor = None
try:
    sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c)
except ValueError as e:
    print(f"Fatal: I2C bus is locked or sensor not found: {e}")
    i2c.deinit()
    raise SystemExit(1)
except Exception as e:
    print(f"Fatal: Failed to initialize fingerprint sensor: {e}")
    i2c.deinit()
    raise SystemExit(1)

try:
    while True:
        try:
            # Wait for a finger to be placed on the sensor
            while True:
                try:
                    if sensor.get_image() == adafruit_fingerprint.OK:
                        break
                except RuntimeError as e:
                    print(f"Sensor error during get_image(): {e}")
                    time.sleep(RETRY_DELAY)
                    continue
                except Exception as e:
                    print(f"Unexpected error during get_image(): {e}")
                    time.sleep(RETRY_DELAY)
                    continue

            # Wait for a valid image to be acquired
            while True:
                try:
                    if sensor.image_2_tz(1) == adafruit_fingerprint.OK:
                        break
                except RuntimeError as e:
                    print(f"Sensor error during image_2_tz(): {e}")
