                if sensor.finger_search() == adafruit_fingerprint.OK:
                    print("Access Granted")
                    print(f"ID: {sensor.finger_id}, Confidence: {sensor.confidence}")
                else:
                    print("Access Denied")
            except RuntimeError as e:
                print(f"Sensor error during finger_search(): {e}")
            except Exception as e:
                print(f"Unexpected error during search: {e}")

        except ValueError as e:
            print(f"I2C bus error: {e}. Retrying in {I2C_RETRY_DELAY} seconds...")
            time.sleep(I2C_RETRY_DELAY)
        except KeyboardInterrupt:
            print("\nExiting program.")
            break
        except Exception as e:
            print(f"Unexpected error: {e}. Retrying in {RETRY_DELAY} seconds...")
            time.sleep(RETRY_DELAY)

finally:
    # Clean up resources on all exit paths
    if sensor is not None:
        try:
            sensor.finger_close()
        except Exception:
            pass
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass
    print("Program finished.")

