import signal
import sys
import time
import logging
from threading import Event

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    logging.error("RPi.GPIO requires root privileges or is not supported on this platform.")
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

DATA_OUT = 5
TIMER_OUT = 6
DATA_IN = 20
TIMER_IN = 21
START_BYTE = b"\x01"
END_BYTE = b"\x00"
BIT_DELAY = 0.0001
DEFAULT_TIMEOUT = 5.0

stop_event = Event()


def _signal_handler(signum, frame):
    logger.info(f"Signal {signum} received; initiating graceful shutdown.")
    stop_event.set()


def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(DATA_OUT, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(TIMER_OUT, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(DATA_IN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    GPIO.setup(TIMER_IN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    logger.info("GPIO setup complete.")


def cleanup_gpio():
    try:
        GPIO.cleanup()
        logger.info("GPIO cleanup complete.")
    except Exception as e:
        logger.error(f"Error during GPIO cleanup: {e}")


def send_data(data):
    if not isinstance(data, str):
        raise TypeError("Input must be a string.")
    payload = START_BYTE + data.encode("utf-8") + END_BYTE
    logger.info(f"Sending data: {payload.hex()}")
    try:
        GPIO.output(TIMER_OUT, GPIO.LOW)
        for bit in payload:
            GPIO.output(DATA_OUT, GPIO.HIGH if bit & 0x80 else GPIO.LOW)
            GPIO.output(TIMER_OUT, GPIO.HIGH)
            time.sleep(BIT_DELAY)
            GPIO.output(TIMER_OUT, GPIO.LOW)
            time.sleep(BIT_DELAY)
            GPIO.output(DATA_OUT, GPIO.LOW)
        GPIO.output(TIMER_OUT, GPIO.LOW)
        logger.info("Transmission complete.")
    except Exception as e:
        logger.error(f"Error during data transmission: {e}")
        raise


def receive_data(timeout=DEFAULT_TIMEOUT):
    if not isinstance(timeout, (int, float)):
        raise TypeError("Timeout must be a number.")
    if timeout <= 0:
        raise ValueError("Timeout must be positive.")
    start_time = time.time()
    received_data = b""
    data_buffer = []
    timer_state = 0
    logger.info("Waiting for start byte...")
    while not stop_event.is_set():
        if time.time() - start_time > timeout:
            logger.warning(f"Timeout ({timeout}s) reached; aborting reception.")
            return ""
        try:
            if GPIO.input(TIMER_IN) == GPIO.HIGH:
                if timer_state == 0:
                    if GPIO.input(DATA_IN) == GPIO.HIGH:
                        received_data += bytes([0])
                    else:
                        received_data += bytes([1])
                    timer_state = 1
                else:
                    timer_state = 0
        except Exception as e:
            logger.error(f"Error during GPIO read: {e}")
            return ""
    if stop_event.is_set():
        return ""
    logger.info("Start byte received.")
    while not stop_event.is_set():
        if time.time() - start_time > timeout:
            logger.warning(f"Timeout ({timeout}s) reached; aborting reception.")
            return ""
        try:
            if GPIO.input(TIMER_IN) == GPIO.HIGH:
                if timer_state == 0:
                    if GPIO.input(DATA_IN) == GPIO.HIGH:
                        received_data += bytes([0])
                    else:
                        received_data += bytes([1])
                    timer_state = 1
                else:
                    timer_state = 0
        except Exception as e:
            logger.error(f"Error during GPIO read: {e}")
            return ""
    if stop_event.is_set():
        return ""
    logger.info("End byte not received; aborting reception.")
    return ""


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        setup_gpio()
        send_data("Hello")
        received = receive_data(timeout=DEFAULT_TIMEOUT)
        logger.info(f"Received data: {received}")
    except Exception as e:
        logger.error(f"An error occurred: {e}")
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

