def _handle_sigint(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        reed = Button(DOOR_PIN, pull_up=False, bounce_time=0.05)
        siren = LED(SIREN_PIN)
    except (BadPinFactory, DeviceClosed) as exc:
        print(f"GPIO initialization error: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error during GPIO setup: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        print("Home security demo started. Door is armed.")
        for i in range(SAMPLE_COUNT):
            if not _running:
                print("Demo aborted by user.")
                break

            try:
                if reed.is_active:
                    siren.on()
                    print(f"Alarm triggered at sample {i}: Door is open!")
                else:
                    siren.off()
            except DeviceClosed:
                print("Device closed unexpectedly.", file=sys.stderr)
                break
            except Exception as exc:
                print(f"Error reading sensor: {exc}", file=sys.stderr)
                break

            if i < SAMPLE_COUNT - 1 and _running:
                time.sleep(SAMPLE_INTERVAL)

        if _running:
            print("Demo completed successfully.")
    finally:
        try:
            siren.close()
        except Exception:
            pass
        try:
            reed.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

