import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("RPi.GPIO is not installed. Install with: sudo apt install python3-rpi.gpio", file=sys.stderr)
    sys.exit(1)

PWM_PIN = 12
PWM_FREQ = 25000

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _cleanup(pwm=None):
    if pwm is not None:
        try:
            pwm.stop()
        except Exception:
            pass
    try:
        GPIO.cleanup()
    except Exception:
        pass

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(PWM_PIN, GPIO.OUT, initial=GPIO.LOW)

    pwm = None
    try:
        pwm = GPIO.PWM(PWM_PIN, PWM_FREQ)
        pwm.start(0)
    except Exception as e:
        print(f"Failed to initialize hardware PWM on GPIO{PWM_PIN}: {e}", file=sys.stderr)
        print("Falling back to software PWM.", file=sys.stderr)
        pwm = None

    try:
        while _running:
            try:
                raw = input("Enter fan speed (0-100, or 'q' to quit): ").strip()
            except EOFError:
                break

            if raw.lower() == 'q':
                break

            if not raw:
                continue

            speed = float(raw)
            if not (0 <= speed <= 100):
                print("Invalid speed. Please enter a value between 0 and 100.")
                continue

            if pwm is not None:
                try:
                    pwm.ChangeDutyCycle(speed)
                except Exception as e:
                    print(f"Error setting duty cycle: {e}", file=sys.stderr)
            else:
                try:
                    GPIO.output(PWM_PIN, GPIO.HIGH if speed > 0 else GPIO.LOW)
                except Exception as e:
                    print(f"Error setting output pin: {e}", file=sys.stderr)

            print(f"Fan speed set to {speed:.1f}%")
    finally:
        _cleanup(pwm)

if __name__ == "__main__":
    main()

