import signal
import threading
import time
import logging

import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("rotary_encoder")

CLK_PIN = 17
DT_PIN = 18
DEBOUNCE_S = 0.005


class RotaryEncoder:
    """A class to handle a KY-040 rotary encoder on a Raspberry Pi."""

    def __init__(self, clk_pin, dt_pin, callback=None, initial_value=0):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.value = initial_value
        self._lock = threading.Lock()
        self._last_clk_state = GPIO.HIGH
        self._last_dt_state = GPIO.HIGH
        self._encoder_thread = None
        self._running = False

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.clk_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            GPIO.setup(self.dt_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        except Exception as exc:
            log.error("Failed to initialize GPIO pins %d/%d: %s", clk_pin, dt_pin, exc)
            raise

        if self.callback is not None and not callable(self.callback):
            raise TypeError("callback must be callable")

        self._encoder_thread = threading.Thread(target=self._encoder_loop, daemon=True)
        self._running = True
        self._encoder_thread.start()

    def _encoder_loop(self):
        while self._running:
            try:
                clk_state = GPIO.input(self.clk_pin)
                dt_state = GPIO.input(self.dt_pin)

                if clk_state != self._last_clk_state:
                    if dt_state != clk_state:
                        self.value += 1
                    else:
                        self.value -= 1

                    with self._lock:
                        if self.callback is not None:
                            try:
                                self.callback(self.value)
                            except Exception as exc:
                                log.error("callback raised an exception: %s", exc)
                    self._last_clk_state = clk_state
            except Exception as exc:
                log.error("Error reading encoder pins: %s", exc)
