    "water": "open_valve",
    "stop": "close_valve",
    "status": "report",
}

# Simulated audio frames: each frame is a dict with 'energy' (0-9) and 'index'
AUDIO_FRAMES = [
    {"energy": random.randint(0, 9), "index": i} for i in range(6)
]

# Simulated transcriptions for each frame
TRANSCRIPTIONS = [
    "water",
    "stop",
    "status",
    "water",
    "stop",
    "status",
]

def process_audio_frame(frame_index, audio_energy):
    """Return the transcribed keyword for the given audio frame."""
    # In a real system, audio_energy would be analyzed by a recognizer.
    # Here we simulate by choosing a keyword based on energy level.
    # For simplicity, we map energy 0-3 to "water", 4-6 to "stop", 7-9 to "status".
    if audio_energy < 4:
        return "water"
    elif audio_energy < 7:
        return "stop"
    else:
        return "status"

def main():
    """Run the simulated voice recognition loop."""
    if GPIO is not None:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
        except Exception:
            pass  # GPIO not available on this platform

    try:
        for i, frame in enumerate(AUDIO_FRAMES):
            audio_energy = frame["energy"]
            keyword = process_audio_frame(i, audio_energy)
            action = KEYWORD_TO_ACTION.get(keyword, "unknown")
            print(f"Frame {i}: Energy={audio_energy}, Keyword={keyword}, Action={action}")
    except Exception as e:
        print(f"Error during processing: {e}", file=sys.stderr)
    finally:
        if GPIO is not None:
            try:
                GPIO.cleanup()
            except Exception:
                pass
        # Write the list of chosen actions to a JSON file
