import time
import logging
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    logging.error("RPi.GPIO requires root privileges or is not supported on this platform.")
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)


class MotionMonitor:
    """Monitors an HC-SR501 PIR motion sensor on a Raspberry Pi."""

    def __init__(self, sensor_pin: int, debounce_time: float = 0.2, timeout: float = 30.0):
        self.sensor_pin = sensor_pin
        self.debounce_time = debounce_time
        self.timeout = timeout
        self.last_motion_time = 0.0
        self._running = True
        self._initialized = False

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.sensor_pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            self._initialized = True
            logger.info("MotionMonitor initialized on GPIO%d (BCM).", self.sensor_pin)
        except Exception as exc:
            logger.error("Failed to initialize GPIO: %s", exc)
            self._initialized = False

    def _read_sensor(self) -> bool:
        """Return True if the PIR sensor currently reports motion."""
        if not self._initialized:
            return False
        try:
            return GPIO.input(self.sensor_pin) == GPIO.HIGH
        except Exception as exc:
            logger.error("Error reading GPIO%d: %s", self.sensor_pin, exc)
            return False

    def detect_motion(self) -> bool:
        """Return True only after debouncing and confirming motion persists."""
        current_time = time.monotonic()
        if current_time - self.last_motion_time < self.debounce_time:
            return False
        if not self._running:
            return False
        if not self._read_sensor():
            return False
        self.last_motion_time = current_time
        return True

    def cleanup(self) -> None:
        """Release GPIO resources."""
        if self._initialized:
            try:
                GPIO.cleanup(self.sensor_pin)
                logger.info("GPIO%d cleaned up.", self.sensor_pin)
            except Exception as exc:
                logger.error("Error during GPIO cleanup: %s", exc)
            finally:
                self._initialized = False

    def stop(self) -> None:
        """Signal the main loop to exit."""
        self._running = False


def tally_visitor(monitor: MotionMonitor, visitor_count: int) -> int:
    """Print the current visitor count and return the updated tally."""
    logger.info("Visitor count: %d", visitor_count)
    return visitor_count + 1


def main() -> None:
    monitor = MotionMonitor(sensor_pin=23, debounce_time=0.2, timeout=30.0)

    def _signal_handler(signum, frame):
        logger.info("Received signal %d, shutting down.", signum)
        monitor.stop()

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    visitor_count = 0
    start_time = time.monotonic()

    try:
        while monitor._running and (time.monotonic() - start_time) < 60.0:
            if monitor.detect_motion():
                visitor_count = tally_visitor(monitor, visitor_count)
            time.sleep(0.1)
    except Exception as exc:
        logger.error("Unexpected error in main loop: %s", exc)
    finally:
        logger.info("Monitoring complete. Final visitor count: %d", visitor_count)
        monitor.cleanup()


if __name__ == "__main__":
    main()

