import argparse
import json
import signal
import socket
import struct
import sys
import time

try:
    import smbus2 as smbus
except ImportError:
    import smbus

# LSM303DLHC register addresses
LSM303DLHC_ADDR = 0x1E
LSM303DLHC_ACCEL_XOUT_H = 0x22
LSM303DLHC_ACCEL_YOUT_H = 0x24
LSM303DLHC_ACCEL_ZOUT_H = 0x26
LSM303DLHC_MAG_XOUT_H = 0x28
LSM303DLHC_MAG_YOUT_H = 0x2A
LSM303DLHC_MAG_ZOUT_H = 0x2C
LSM303DLHC_STATUS = 0x06

# Sensitivity scales for +/-2g and +/-1.3ga range
ACCEL_SCALE_2G = 0.061
ACCEL_SCALE_8G = 0.002
MAG_SCALE_1GA = 0.110

# Global state
running = True
bus = None
sock = None
args = None


def signal_handler(signum, frame):
    global running
    running = False


def twos_complement(val, bits):
    if val & (1 << (bits - 1)):
        val -= (1 << bits)
    return val


def read_raw_data(bus, addr, reg_h, bits):
    """Read two bytes from reg_h and reg_h+1, return signed 16-bit value."""
    data = bus.read_i2c_block_data(LSM303DLHC_ADDR, addr, 2)
    val = (data[0] << 8) | data[1]
    return twos_complement(val, bits)


def read_accel(bus):
    ax = read_raw_data(bus, LSM303DLHC_ACCEL_XOUT_H, 16)
    ay = read_raw_data(bus, LSM303DLHC_ACCEL_YOUT_H, 16)
    az = read_raw_data(bus, LSM303DLHC_ACCEL_ZOUT_H, 16)
    return ax, ay, az


def read_mag(bus):
    mx = read_raw_data(bus, LSM303DLHC_MAG_XOUT_H, 16)
    my = read_raw_data(bus, LSM303DLHC_MAG_YOUT_H, 16)
    mz = read_raw_data(bus, LSM303DLHC_MAG_ZOUT_H, 16)
    return mx, my, mz


def apply_calibration(ax, ay, az, mag_offs, accel_offs):
    ax = ax - accel_offs[0]
    ay = ay - accel_offs[1]
    az = az - accel_offs[2]
    mx = mx - mag_offs[0]
    my = my - mag_offs[1]
    mz = mz - mag_offs[2]
    return ax, ay, az, mx, my, mz


def validate_data(ax, ay, az, mx, my, mz):
    if not (-256 <= ax <= 256):
        raise ValueError(f"Accel X out of range: {ax}")
    if not (-256 <= ay <= 256):
        raise ValueError(f"Accel Y out of range: {ay}")
    if not (-256 <= az <= 256):
        raise ValueError(f"Accel Z out of range: {az}")
    if not (-65536 <= mx <= 65535):
        raise ValueError(f"Mag X out of range: {mx}")
    if not (-65536 <= my <= 65535):
        raise ValueError(f"Mag Y out of range: {my}")
    if not (-65536 <= mz <= 65535):
        raise ValueError(f"Mag Z out of range: {mz}")


def main():
    global bus, sock, args

    parser = argparse.ArgumentParser(
        description="Raspberry Pi LSM303DLHC accelerometer/magnetometer data streamer"
    )
    parser.add_argument("--port", type=int, default=5000, help="TCP port (default: 5000)")
    parser.add_argument("--rate", type=float, default=100.0, help="Data rate in Hz (default: 100)")
    parser.add_argument("--accel-offset-x", type=float, default=0.0, help="X-axis accelerometer offset")
    parser.add_argument("--accel-offset-y", type=float, default=0.0, help="Y-axis accelerometer offset")
    parser.add_argument("--accel-offset-z", type=float, default=0.0, help="Z-axis accelerometer offset")
    parser.add_argument("--mag-offset-x", type=float, default=0.0, help="X-axis magnetometer offset")
    parser.add_argument("--mag-offset-y", type=float, default=0.0, help="Y-axis magnetometer offset")
    parser.add_argument("--mag-offset-z", type=float, default=0.0, help="Z-axis magnetometer offset")
    args = parser.parse_args()

    if args.rate <= 0:
        print("Error: --rate must be positive.", file=sys.stderr)
        sys.exit(1)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Open I2C bus 1
    try:
        bus = smbus.SMBus(1)
    except FileNotFoundError:
        print("Error: I2C bus 1 not found. Enable I2C with 'sudo raspi-config'.", file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print("Error: Permission denied on I2C bus. Run as root or add user to 'i2c' group.", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error opening I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    # Verify sensor presence
    try:
        status = bus.read_byte_data(LSM303DLHC_ADDR, LSM303DLHC_STATUS)
    except OSError as e:
        print(f"Error: LSM303DLHC not found at address 0x{LSM303DLHC_ADDR:02X} on bus 1: {e}", file=sys.stderr)
        bus.close()
        sys.exit(1)

    # Configure magnetometer for continuous conversion (default)
    try:
        bus.write_byte_data(LSM303DLHC_ADDR, LSM303DLHC_STATUS, 0x00)
    except OSError as e:
        print(f"Warning: could not configure magnetometer: {e}", file=sys.stderr)

    # Configure accelerometer for continuous conversion (default)
    try:
        bus.write_byte_data(LSM303DLHC_ADDR, LSM303DLHC_STATUS, 0x00)
    except OSError as e:
        print(f"Warning: could not configure accelerometer: {e}", file=sys.stderr)

    # Set magnetometer gain to +/-1.3ga (default)
    try:
        bus.write_byte_data(LSM303DLHC_ADDR, LSM303DLHC_STATUS, 0x00)
    except OSError as e:
        print(f"Warning: could not configure magnetometer gain: {e}", file=sys.stderr)

