LSM303DLHC_ACCEL_XOUT_H = 0x22
LSM303DLHC_ACCEL_YOUT_H = 0x24
LSM303DLHC_ACCEL_ZOUT_H = 0x26
LSM303DLHC_MAG_XOUT_H = 0x28
LSM303DLHC_MAG_YOUT_H = 0x2A
LSM303DLHC_MAG_ZOUT_H = 0x2C
LSM303DLHC_STATUS = 0x06

# Sensitivity scales for +/-2g and +/-1.3ga range
ACCEL_SCALE_2G = 0.061
ACCEL_SCALE_8G = 0.002
MAG_SCALE_1GA = 0.110

# Global state
running = True
bus = None
sock = None
args = None


def signal_handler(signum, frame):
    global running
    running = False


def twos_complement(val, bits):
    if val & (1 << (bits - 1)):
        val -= (1 << bits)
    return val


def read_raw_data(bus, addr, reg_h, bits):
    """Read two bytes from reg_h and reg_h+1, return signed 16-bit value."""
    data = bus.read_i2c_block_data(LSM303DLHC_ADDR, addr, 2)
    val = (data[0] << 8) | data[1]
    return twos_complement(val, bits)


def read_accel(bus):
    ax = read_raw_data(bus, LSM303DLHC_ACCEL_XOUT_H, 16)
    ay = read_raw_data(bus, LSM303DLHC_ACCEL_YOUT_H, 16)
    az = read_raw_data(bus, LSM303DLHC_ACCEL_ZOUT_H, 16)
    return ax, ay, az


def read_mag(bus):
    mx = read_raw_data(bus, LSM303DLHC_MAG_XOUT_H, 16)
    my = read_raw_data(bus, LSM303DLHC_MAG_YOUT_H, 16)
    mz = read_raw_data(bus, LSM303DLHC_MAG_ZOUT_H, 16)
    return mx, my, mz


def apply_calibration(ax, ay, az, mag_offs, accel_offs):
    ax = ax - accel_offs[0]
    ay = ay - accel_offs[1]
    az = az - accel_offs[2]
    mx = mx - mag_offs[0]
    my = my - mag_offs[1]
    mz = mz - mag_offs[2]
    return ax, ay, az, mx, my, mz


def validate_data(ax, ay, az, mx, my, mz):
    if not (-256 <= ax <= 256):
        raise ValueError(f"Accel X out of range: {ax}")
    if not (-256 <= ay <= 256):
        raise ValueError(f"Accel Y out of range: {ay}")
    if not (-256 <= az <= 256):
        raise ValueError(f"Accel Z out of range: {az}")
    if not (-65536 <= mx <= 65535):
        raise ValueError(f"Mag X out of range: {mx}")
    if not (-65536 <= my <= 65535):
        raise ValueError(f"Mag Y out of range: {my}")
