import random
import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a valid GPIO backend.", file=sys.stderr)
    sys.exit(1)

PUMP_PIN = 18
SENSOR_PIN = 17
LOW_THRESHOLD = 20
HIGH_THRESHOLD = 80
NUM_READINGS = 5
DELAY_SECONDS = 2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_water_level():
    return random.randint(0, 100)

def control_pump(level):
    if level < LOW_THRESHOLD:
        GPIO.output(PUMP_PIN, GPIO.HIGH)
        return "ON"
    elif level > HIGH_THRESHOLD:
        GPIO.output(PUMP_PIN, GPIO.LOW)
        return "OFF"
    else:
        return GPIO.input(PUMP_PIN)

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(PUMP_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

    try:
        for i in range(NUM_READINGS):
            if not _running:
                break
            level = read_water_level()
            pump_state = control_pump(level)
            sensor_state = GPIO.input(SENSOR_PIN)
            print(f"Reading {i + 1}/{NUM_READINGS} - Water Level: {level:3d}%, Pump: {pump_state}, Sensor: {sensor_state}")
            if i < NUM_READINGS - 1 and _running:
                time.sleep(DELAY_SECONDS)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

