import random
import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("RPi.GPIO library not found. Please install it via 'pip install RPi.GPIO'.")
    sys.exit(1)

# Configuration
LED_PIN = 18
NUM_READINGS = 5
DELAY_SECONDS = 2
SENSOR_FAILURE_PROBABILITY = 0.1

# Global flag for clean shutdown
_running = True

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False

def setup_gpio():
    """Initialize GPIO settings. Returns True on success, False on failure."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        return True
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        return False

def read_water_quality():
    """Simulate reading water quality data. Returns percentage (0-100) or None on failure."""
    if random.random() < SENSOR_FAILURE_PROBABILITY:
        print("Sensor read failure detected. Retrying...")
        time.sleep(0.5)
        return read_water_quality()  # Recursive retry
    return random.randint(0, 100)

def control_led(quality):
    """Control the LED based on water quality. Returns True if LED is on, False if off."""
    if quality < 50:
        GPIO.output(LED_PIN, GPIO.HIGH)
        print(f"Water quality: {quality}% - LED ON")
        return True
    else:
        GPIO.output(LED_PIN, GPIO.LOW)
        print(f"Water quality: {quality}% - LED OFF")
        return False

def cleanup_gpio():
    """Safely release GPIO resources."""
    try:
        GPIO.cleanup()
        print("GPIO cleanup completed.")
    except Exception as e:
        print(f"GPIO cleanup error: {e}")

def main():
    """Main function to simulate water quality monitoring."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not setup_gpio():
        print("Exiting due to GPIO setup failure.")
        return

    try:
        for i in range(NUM_READINGS):
            if not _running:
                break

            quality = read_water_quality()
            if quality is None:
                print("Failed to read water quality after retry.")
                continue

            control_led(quality)

            # Wait between readings, but allow early exit on signal
            if i < NUM_READINGS - 1 and _running:
                time.sleep(DELAY_SECONDS)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

