import time
import signal
import sys
import logging
import numpy as np
import cv2
import board
import busio
import adafruit_tcs34725

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("color")

_running = True

def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False

def init_i2c():
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        log.error("I2C bus initialization failed: %s", exc)
        return None

def init_color_sensor(i2c_bus):
    try:
        sensor = adafruit_tcs34725.TCS34725(i2c_bus)
        sensor.integration_time = 0.05
        sensor.gain = 4
        return sensor
    except Exception as exc:
        log.error("TCS34725 initialization failed: %s", exc)
        return None

def read_color_data(sensor):
    try:
        red, green, blue, clear = sensor.color_rgb_bytes
        return red, green, blue, clear
    except Exception as exc:
        log.error("Error reading color data: %s", exc)
        return 0, 0, 0, 0

def open_image(filename):
    try:
        img = cv2.imread(filename)
        if img is None:
            raise FileNotFoundError(f"Image file not found or unreadable: {filename}")
        return img
    except Exception as exc:
        log.error("Error opening image '%s': %s", filename, exc)
        return None

def resize_image(img, size=(100, 100)):
    try:
        return cv2.resize(img, size)
    except Exception as exc:
        log.error("Error resizing image: %s", exc)
        return None

def most_frequent_color(img):
    try:
        if img is None:
            return (0, 0, 0)
        if img.ndim == 3 and img.shape[2] == 4:
            img = img[:, :, :3]
        if img.ndim == 2:
            img = cv2.cvtColor(img, cv2.COLOR_GRAY2BGR)
        if img.ndim == 3 and img.shape[2] == 3:
            img = cv2.cvtColor(img, cv2.COLOR_RGB2BGR)
        resized = resize_image(img)
        if resized is None:
            return (0, 0, 0)
        if resized.ndim == 3 and resized.shape[2] == 3:
            arr = np.ascontiguousarray(resized)
        else:
            arr = np.ascontiguousarray(resized[:, :, :3])
        if arr.size == 0:
            return (0, 0, 0)
        unique = np.unique(arr.reshape(-1, 3), axis=0)
        counts = np.bincount(unique[:, 0], unique[:, 1], unique[:, 2])
        idx = int(np.argmax(counts))
        return tuple(unique[idx, :])
    except Exception as exc:
        log.error("Error determining dominant color: %s", exc)
        return (0, 0, 0)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = init_i2c()
    if i2c_bus is None:
        sys.exit(1)

    color_sensor = init_color_sensor(i2c_bus)
    if color_sensor is None:
        i2c_bus.deinit()
        sys.exit(1)

    try:
        while _running:
            red, green, blue, clear = read_color_data(color_sensor)
            log.info("Raw Color Data: R=%d, G=%d, B=%d, Clear=%d",
                     red, green, blue, clear)

            image = open_image("image.jpg")
            if image is None:
                log.warning("Skipping dominant color calculation due to image error.")
            else:
                dominant = most_frequent_color(image)
                log.info("Dominant Color: %s", dominant)

            time.sleep(1)
    except Exception as exc:
        log.error("Unexpected error in main loop: %s", exc)
    finally:
        try:
            color_sensor.deinit()
        except Exception:
            pass
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        log.info("Resources released. Exiting.")

if __name__ == "__main__":
    main()

