    _running = False

def setup_gpio():
    """Initialize GPIO pins and mode."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(SOIL_MOISTURE_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

def cleanup_gpio():
    """Clean up GPIO resources."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
        GPIO.cleanup()
    except Exception as e:
        print(f"GPIO cleanup warning: {e}")

def read_soil_moisture():
    """Read soil moisture level from sensor."""
    try:
        moisture_level = GPIO.input(SOIL_MOISTURE_PIN)
        return moisture_level
    except Exception as e:
        print(f"Error reading soil moisture sensor: {e}")
        return None

def control_led(moisture_level):
    """Control LED based on moisture level."""
    try:
        if moisture_level == GPIO.HIGH:
            GPIO.output(LED_PIN, GPIO.HIGH)
            print("Soil is dry. LED ON")
        elif moisture_level == GPIO.LOW:
            GPIO.output(LED_PIN, GPIO.LOW)
            print("Soil is wet. LED OFF")
        else:
