import time
import signal
import sys
import smbus2
from gpiozero import LED, Buzzer

# Constants
I2C_BUS = 1
LIS3DH_ADDRESS = 0x19
LED_PIN = 21
BUZZER_PIN = 20
ACCEL_X_OFFSET = 0x21
ACCEL_X_LSB = 0x22
ACCEL_X_MSB = 0x23
ACCEL_X_FULL = (ACCEL_X_MSB << 8) | ACCEL_X_LSB
ACCEL_X_G = 0.061       # LSB/g for ±2 g range
THRESHOLD_1G = 0.3
THRESHOLD_2G = 0.7
SAMPLE_INTERVAL = 0.1
LOOP_INTERVAL = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _cleanup(led, buzzer, bus):
    try:
        if led is not None:
            led.off()
            led.close()
    except Exception:
        pass
    try:
        if buzzer is not None:
            buzzer.off()
            buzzer.close()
    except Exception:
        pass
    try:
        if bus is not None:
            bus.close()
    except Exception:
        pass

def _verify_device(bus, addr):
    try:
        who = bus.read_byte_data(addr, 0x0F)
    except OSError:
        return False
    return who == 0x33

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    led = None
    buzzer = None
    bus = None

    try:
        try:
            led = LED(LED_PIN)
            buzzer = Buzzer(BUZZER_PIN)
        except Exception as e:
            print(f"Error initializing GPIO pins: {e}", file=sys.stderr)
            return 1

        try:
            bus = smbus2.SMBus(I2C_BUS)
        except Exception as e:
            print(f"Error initializing I2C bus {I2C_BUS}: {e}", file=sys.stderr)
            _cleanup(led, buzzer, None)
            return 1

        if not _verify_device(bus, LIS3DH_ADDRESS):
            print(f"Error: LIS3DH not found at address 0x{LIS3DH_ADDRESS:02X} on bus {I2C_BUS}.", file=sys.stderr)
            _cleanup(led, buzzer, bus)
            return 1

        print("LIS3DH initialized. Reading X-axis acceleration (g). Press Ctrl+C to exit.")

        while _running:
            try:
                data = bus.read_i2c_block_data(LIS3DH_ADDRESS, ACCEL_X_FULL, 2)
                x_raw = (data[0] << 8) | data[1]
                x_g = x_raw * ACCEL_X_G
            except OSError as e:
                print(f"I2C read error: {e}", file=sys.stderr)
                try:
                    led.off()
                    buzzer.off()
                except Exception:
                    pass
                time.sleep(LOOP_INTERVAL)
                continue

            x_g = x_g / 1000.0

            if abs(x_g) > THRESHOLD_1G:
                if not led.is_lit:
                    led.on()
                if not buzzer.is_active:
                    buzzer.on()
                time.sleep(0.01)
            else:
                if led.is_lit:
                    led.off()
                if buzzer.is_active:
                    buzzer.off()
                time.sleep(0.01)

            if abs(x_g) > THRESHOLD_2G:
                print(f"X-Acceleration: {x_g:.2f} g  (Buzzer ON)")
            else:
                print(f"X-Acceleration: {x_g:.2f} g  (Buzzer OFF)")

            time.sleep(SAMPLE_INTERVAL)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        return 1
    finally:
        _cleanup(led, buzzer, bus)
        print("Exiting program.")

    return 0

if __name__ == "__main__":
    sys.exit(main())

