import signal
import sys
import time
import math
import logging
from smbus2 import SMBus

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("quality")

I2C_BUS = 1
MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B
ACCEL_CONFIG = 0x1C
ACCEL_RANGE_2G = 0x00
SAMPLE_COUNT = 8
SAMPLE_DELAY_S = 0.01
THRESHOLD_MAG = 2.5
THRESHOLD_VARIANCE = 0.4

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False
    log.info("Signal %s received, shutting down...", signum)


def _read_word(bus, addr, reg):
    high = bus.read_byte_data(addr, reg)
    low = bus.read_byte_data(addr, reg + 1)
    return (high << 8) | low


def _read_accel(bus):
    data = _read_word(bus, MPU6050_ADDR, ACCEL_XOUT_H)
    return data / 16384.0


def _read_accel_config(bus):
    return _read_word(bus, MPU6050_ADDR, ACCEL_CONFIG)


def _write_power_mgmt(bus):
    bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0)


def _init_sensor(bus):
    _write_power_mgmt(bus)
    cfg = _read_accel_config(bus)
    if cfg != ACCEL_CONFIG:
        log.warning("MPU6050 config mismatch: got 0x%02X, expected 0x%02X", cfg, ACCEL_CONFIG)
    log.info("MPU6050 initialized on bus %d", I2C_BUS)


def _sample(bus):
    x = _read_accel(bus)
    y = _read_accel(bus)
    z = _read_accel(bus)
    return math.sqrt(x * x + y * y + z * z)


def _compute_features(bus):
    magnitudes = []
    for _ in range(SAMPLE_COUNT):
        if not _running:
            return None, None
        mag = _sample(bus)
        magnitudes.append(mag)
        time.sleep(SAMPLE_DELAY_S)
    if not magnitudes:
        return None, None
    return math.sqrt(sum(m * m for m in magnitudes) / len(magnitudes)), (
        sum(m * m for m in magnitudes) / len(magnitudes)
    ) - (sum(magnitudes) / len(magnitudes)) ** 2


def _detect_defect(mag, variance):
    return mag > THRESHOLD_MAG or variance > THRESHOLD_VARIANCE


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    bus = None
    try:
        bus = SMBus(I2C_BUS)
        _init_sensor(bus)
        mag, variance = _compute_features(bus)
        if mag is None or variance is None:
            log.error("Failed to collect features after %d samples", SAMPLE_COUNT)
            return
        log.info("Magnitude: %.4f g, Variance: %.4f", mag, variance)
        is_defect = _detect_defect(mag, variance)
        if is_defect:
            log.warning("DEFECTIVE part detected")
        else:
            log.info("PASS")
    except OSError as e:
        log.error("I2C error: %s", e)
    except Exception as e:
        log.error("Unexpected error: %s", e)
    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

