def is_feeding_time(now):
    """Return True if now is within the 24-hour feeding window."""
    start = datetime.time(FEEDING_START_HOUR, 0, 0)
    end = datetime.time(FEEDING_END_HOUR, 0, 0)
    return start <= now <= end

def setup_gpio():
    """Initialize GPIO with BCM numbering and configure PIR pin as input with pull-down."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

def cleanup_gpio():
    """Safely release GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception:
        pass

def main():
    setup_gpio()
    last_feed_time = None
    print("PIR motion sensor monitoring started. Press Ctrl+C to exit.")
    try:
        while True:
            try:
                motion_detected = GPIO.input(PIR_PIN)
            except Exception as e:
                print(f"Error reading PIR sensor: {e}")
                time.sleep(LOG_INTERVAL_SECONDS)
                continue

            now = datetime.datetime.now()
            current_hour = now.hour

            if motion_detected:
                if is_feeding_time(now):
                    if last_feed_time is None or (now - last_feed_time).total_seconds() >= 60:
