import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERVO_PIN = 17
PWM_FREQUENCY = 50
HOLD_TIME = 1.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def angle_to_duty_cycle(angle):
    if angle < 0 or angle > 180:
        raise ValueError(f"Angle must be between 0 and 180, got {angle}")
    return (angle / 180.0) * 100.0

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        pwm = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1, write_timeout=1)
    except serial.SerialException as e:
        print(f"Error opening PWM serial port: {e}", file=sys.stderr)
        ser.close()
        sys.exit(1)

    try:
        while running:
            try:
                raw = ser.readline()
                if not raw:
                    continue
                angle_str = raw.decode('ascii', errors='replace').strip()
                if not angle_str:
                    continue
                angle = int(angle_str)
                duty = angle_to_duty_cycle(angle)
                print(f"Received angle: {angle} degrees")
                pwm.write(f'{duty:.2f}\n'.encode())
                time.sleep(HOLD_TIME)
                pwm.write(b'\n')
            except ValueError as e:
                print(f"Invalid angle received: {e}", file=sys.stderr)
            except serial.SerialException as e:
                print(f"Serial communication error: {e}", file=sys.stderr)
                break
            except Exception as e:
                print(f"Unexpected error: {e}", file=sys.stderr)
                break
    finally:
        try:
            pwm.close()
        except Exception:
            pass
        try:
            ser.close()
        except Exception:
            pass
        print("Resources released.")

if __name__ == '__main__':
    main()

