import signal
import sys
import logging
import time
from typing import Dict, Any, Optional

try:
    import serial
except ImportError:
    serial = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class ServoMotorController:
    """
    A class to encapsulate Modbus RTU communication with a servo motor controller
    via UART on a Raspberry Pi.
    """

    def __init__(self, port: str = '/dev/serial0', baudrate: int = 115200) -> None:
        self.port = port
        self.baudrate = baudrate
        self.registers: Dict[int, Dict[str, Any]] = {}
        self.uart: Optional[serial.Serial] = None
        self._running = True

        if serial is None:
            logger.error("pyserial is not installed. Install with: pip install pyserial")
            raise RuntimeError("pyserial is required")

        try:
            self.uart = serial.Serial(
                port=port,
                baudrate=baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0
            )
            logger.info(f"Serial port {port} opened at {baudrate} baud.")
        except serial.SerialException as e:
            logger.error(f"Failed to open serial port {port}: {e}")
            raise

        self._install_signal_handlers()

    def _install_signal_handlers(self) -> None:
        for sig in (signal.SIGINT, signal.SIGTERM):
            signal.signal(sig, self._signal_handler)

    def _signal_handler(self, signum: int, frame: Any) -> None:
        logger.info(f"Signal {signum} received. Shutting down gracefully...")
        self._running = False
        self.close()
        sys.exit(0)

    def add_register(self, register_address: int, register_type: str, functioncode: int, data: Optional[list] = None) -> None:
        self.registers[register_address] = {
            'address': register_address,
            'type': register_type,
            'functioncode': functioncode,
            'data': data if data is not None else []
        }

    def read_register(self, register_address: int, count: int = 1) -> Optional[list]:
        if register_address not in self.registers:
            logger.warning(f"Register {register_address} not found in register map.")
            return None

        reg = self.registers[register_address]
        if reg['type'] != 'H':
            logger.warning(f"Register {register_address} is not holding (type='{reg['type']}', skipping read.")
            return None

        if reg['functioncode'] != 3:
            logger.warning(f"Register {register_address} does not support reading (FC={reg['functioncode']}, skipping read.")
            return None

        if self.uart is None:
            logger.warning("UART not initialized. Cannot read registers.")
            return None

        try:
