import time
import logging
import signal
import sys
import atexit

try:
    import smbus2
except ImportError:
    smbus2 = None

try:
    from automationhat import reed, relay
except ImportError:
    logging.error("automationhat package not installed. Install with: pip install automationhat")
    sys.exit(0)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


class GarageDoor:
    """Manage a garage door via a Pimoroni Automation HAT reed switch and relay."""

    def __init__(self, state_pin=1, relay_name="relay.one", open_duration=0.5):
        self.state_pin = state_pin
        self.relay_name = relay_name
        self.open_duration = open_duration
        self._closed = None
        self._open = None
        self._closed_lock = None
        self._open_lock = None
        self._bus = None
        self._bus_ok = False
        self._bus_ok = False
        self._bus_ok = False

        try:
            if smbus2 is not None:
                self._bus = smbus2.SMBus(1)
                self._bus_ok = True
            else:
                logger.warning("smbus2 not available; using mock bus for testing.")
        except Exception as e:
            logger.warning(f"Failed to open bus 1 for Automation HAT: {e}")

        try:
            reed.read(self.state_pin)
        except Exception as e:
            logger.error(f"Failed to read reed switch on input {self.state_pin}: {e}")
            self._bus_ok = False
            raise

        try:
            self._closed_lock = relay.lock(self.relay_name)
            self._open_lock = relay.lock(self.relay_name)
        except Exception as e:
            logger.error(f"Failed to lock relay {self.relay_name}: {e}")
            self._closed_lock = None
            self._open_lock = None
            raise

        try:
            if self._bus_ok and smbus2 is not None:
                self._bus.write_byte_data(0x06, 0x00, 0x00)
            else:
                logger.warning("Mock bus write not performed; Automation HAT driver not detected.")
        except Exception as e:
            logger.warning(f"Failed to initialize Automation HAT driver: {e}")

        self._closed = False
        self._open = False
        logger.info(
            f"GarageDoor initialized: state_pin={self.state_pin}, "
            f"relay={self.relay_name}, open_duration={self.open_duration}s"
        )

    def _read_reed(self):
        if not self._bus_ok and smbus2 is not None:
            return None
        try:
            if smbus2 is not None:
                return self._bus.read_byte_data(0x06, self.state_pin)
            return reed.read(self.state_pin)
        except Exception as e:
            logger.error(f"Error reading reed switch on input {self.state_pin}: {e}")
            return None

    def _set_relay(self, state):
        try:
            if state:
                relay.on(self.relay_name)
            else:
                relay.off(self.relay_name)
        except Exception as e:
            logger.error(f"Error setting relay {self.relay_name}: {e}")

    def close_door(self):
        if self._closed_lock is None:
            return
        try:
            self._closed_lock.lock()
        except Exception as e:
            logger.error(f"Failed to lock closed state: {e}")
            return
        try:
            self._closed = True
            self._open = False
            self._set_relay(True)
            logger.info("Door closed.")
        except Exception as e:
            logger.error(f"Failed to close door: {e}")
        finally:
            self._closed_lock.unlock()

    def open_door(self):
        if self._open_lock is None:
            return
        try:
            self._open_lock.lock()
        except Exception as e:
            logger.error(f"Failed to lock open state: {e}")
            return
        try:
            self._open = True
            self._closed = False
            self._set_relay(False)
            logger.info("Door opened.")
        except Exception as e:
            logger.error(f"Failed to open door: {e}")
        finally:
            self._open_lock.unlock()

    def is_closed(self):
        return self._closed

    def is_open(self):
        return self._open

    def cleanup(self):
        try:
            if self._closed_lock is not None:
                self._closed_lock.unlock()
        except Exception:
            pass
        try:
            if self._open_lock is not None:
                self._open_lock.unlock()
        except Exception:
            pass
        try:
            if self._bus_ok and smbus2 is not None:
                self._bus.close()
        except Exception:
            pass


def _signal_handler(signum, frame):
    logger.info(f"Signal {signum} received; shutting down.")
    sys.exit(0)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    atexit.register(GarageDoor.cleanup)

    try:
        My_Garage = GarageDoor(state_pin=1, relay_name="relay.one", open_duration=0.5)
    except Exception as e:
        logger.error(f"Failed to initialize GarageDoor: {e}")
        sys.exit(0)

    try:
        while True:
            reed_state = My_Garage._read_reed()
            if reed_state is None:
                logger.warning("Failed to read reed switch; retrying...")
                time.sleep(0.5)
                continue

            if reed_state == 1:
                if not My_Garage._open:
                    My_Garage.close_door()
            else:
                if not My_Garage._closed:
                    My_Garage.open_door()

            time.sleep(0.1)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        My_Garage.cleanup()


if __name__ == "__main__":
    main()

