import time
import signal
import sys
import curses
import fcntl
import termios
from functools import partial
from typing import Optional

try:
    from adafruit_pca9685 import PCA9685
    from adafruit_extended_bus import ExtendedI2C as I2C
except ImportError:
    print("Error: Required libraries not found. Install with:")
    print("  pip install adafruit-circuitpython-pca9685 adafruit-circuitpython-extended-bus")
    sys.exit(1)

PWM_CHANNEL_ESC = 0
PWM_CHANNEL_STEERING = 1
THROTTLE_STOP = 400
THROTTLE_MIN = 200
THROTTLE_MAX = 600
STEERING_CENTER = 500
STEERING_MIN = 380
STEERING_MAX = 620
I2C_BUS = 1
PCA9685_FREQ = 60
STEP_DELAY = 0.1
RAMP_INCREMENT = 20

running = True
esc_value = THROTTLE_STOP
steering_value = STEERING_CENTER
esc_initialized = False
steering_initialized = False
terminal_state = None


def cleanup() -> None:
    global esc_value, steering_value, esc_initialized, steering_initialized, terminal_state, running
    running = False
    if esc_initialized:
        try:
            if esc_initialized:
                print("Resetting ESC to stop value...")
                write_pwm(PWM_CHANNEL_ESC, THROTTLE_STOP)
                esc_value = THROTTLE_STOP
            time.sleep(0.5)
        except Exception as e:
            print(f"Error resetting ESC: {e}")
        finally:
            try:
                deinit_pwm(PWM_CHANNEL_ESC)
            except Exception:
                pass
            esc_initialized = False
    if steering_initialized:
        try:
            if steering_initialized:
                print("Resetting steering servo to center...")
                write_pwm(PWM_CHANNEL_STEERING, STEERING_CENTER)
                steering_value = STEERING_CENTER
            time.sleep(0.5)
        except Exception as e:
            print(f"Error resetting steering: {e}")
        finally:
            try:
                deinit_pwm(PWM_CHANNEL_STEERING)
            except Exception:
                pass
            steering_initialized = False
    if terminal_state is not None:
        try:
            termios.tcsetattr(termial_state, termios.TCSADRAIN, terminal_state)
        except Exception:
            pass
        terminal_state = None
    try:
        I2C.deinit()
    except Exception:
        pass


def signal_handler(signum, frame) -> None:
    cleanup()
    sys.exit(0)


def write_pwm(channel: int, value: int) -> None:
    global esc_initialized, steering_initialized
    if not esc_initialized:
        raise RuntimeError("PCA9685 not initialized")
    if not steering_initialized:
        raise RuntimeError("PCA9685 not initialized")
    try:
        pca.channels[channel].duty_cycle = value
    except Exception as e:
        raise RuntimeError(f"Failed to write PWM channel {channel}: {e}")


def deinit_pwm(channel: int) -> None:
    global esc_initialized, steering_initialized
    if not esc_initialized:
        return
    try:
        pca.channels[channel].duty_cycle = 0
    except Exception:
        pass
    if channel == PWM_CHANNEL_ESC:
        esc_initialized = False
    else:
        steering_initialized = False


def init_pca9685() -> PCA9685:
    global pca, esc_initialized, steering_initialized
    try:
        pca = PCA9685(I2C(bus=I2C_BUS, address=0x40))
        pca.frequency = PCA9685_FREQ
        pca.channels[PWM_CHANNEL_ESC].duty_cycle = 0
        pca.channels[PWM_CHANNEL_STEERING].duty_cycle = 0
        esc_initialized = True
        steering_initialized = True
    except Exception as e:
        raise RuntimeError(f"Failed to initialize PCA9685 on bus {I2C_BUS}: {e}")
    return pca


def get_terminal_state() -> Optional[termios._termios_t]:
    fd = sys.stdin.fileno()
    try:
        return fcntl.ioctl(fd, termios.TIOCSWINSZ, b'')
    except OSError:
        return None


def restore_terminal_state(terminal_state) -> None:
    global terminal_state
    if terminal_state is not None:
        try:
            termios.tcsetattr(terminal_state, termios.TCSADRAIN, terminal_state)
        except Exception:
            pass
        terminal_state = None


def main() -> None:
    global esc_value, steering_value, terminal_state, running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    terminal_state = get_terminal_state()
    if terminal_state is None:
        print("Terminal not found. Exiting cleanly.")
        sys.exit(0)

    try:
        pca = init_pca9685()
    except RuntimeError as e:
        print(f"Initialization failed: {e}")
        restore_terminal_state(terminal_state)
        sys.exit(0)

    try:
        print("Calibrating ESC...")
        for value in range(THROTTLE_MIN, THROTTLE_MAX + 1, RAMP_INCREMENT):
            write_pwm(PWM_CHANNEL_ESC, value)
            time.sleep(STEP_DELAY)
        for value in range(THROTTLE_MAX, THROTTLE_MIN - 1, -RAMP_INCREMENT):
            write_pwm(PWM_CHANNEL_ESC, value)
            time.sleep(STEP_DELAY)
        write_pwm(PWM_CHANNEL_ESC, THROTTLE_STOP)
        esc_value = THROTTLE_STOP
        print("ESC calibrated. Throttle set to stop.")
    except Exception as e:
        print(f"Calibration failed: {e}")
        cleanup()
        sys.exit(0)

    try:
        while running:
            terminal = curses.initscr()
            curses.noecho()
            curses.cbreak()
            terminal.keypad(True)
            terminal.nodelay(True)
            try:
                ch = terminal.getch()
            except Exception:
                ch = -1
            finally:
                curses.endwin()

            if ch == -1:
                continue

            if ch == ord('q'):
                esc_value = THROTTLE_STOP
                steering_value = STEERING_CENTER
                print("Resetting to default values.")
            elif ch == ord('x'):
                break
            elif ch == curses.KEY_UP and esc_value < THROTTLE_MAX:
                esc_value = min(esc_value + 1, THROTTLE_MAX)
            elif ch == curses.KEY_DOWN and esc_value > THROTTLE_MIN:
                esc_value = max(esc_value - 1, THROTTLE_MIN)
            elif ch == curses.KEY_LEFT and steering_value < STEERING_MAX:
                steering_value = min(steering_value + 1, STEERING_MAX)
            elif ch == curses.KEY_RIGHT and steering_value > STEERING_MIN:
                steering_value = max(steering_value - 1, STEERING_MIN)

            try:
                write_pwm(PWM_CHANNEL_ESC, esc_value)
                write_pwm(PWM_CHANNEL_STEERING, steering_value)
            except Exception as e:
                print(f"Error writing to PWM: {e}")

            print(f"ESC: {esc_value}, Steering: {steering_value}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

