import signal
import sys
import json
import logging
from http.server import BaseHTTPRequestHandler, HTTPServer

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("RPi.GPIO is not installed. Install with: pip install RPi.GPIO", file=sys.stderr)
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("relay_server")

RELAY_PIN = 23
PORT = 5000

_running = True


def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received, shutting down...", signum)
    _running = False


def _cleanup():
    try:
        GPIO.cleanup()
        log.info("GPIO cleanup completed.")
    except Exception as exc:
        log.warning("Error during GPIO cleanup: %s", exc)


class RelayHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        if self.path != "/relay":
            self.send_error(404, "Not found")
            return

        try:
            content_length = int(self.headers.get("Content-Length", 0))
        except ValueError:
            self.send_error(400, "Invalid request")
            return

        if content_length <= 0:
            self.send_error(400, "Empty request body")
            return

        try:
            raw = self.rfile.read(content_length)
        except (OSError, EOFError):
            self.send_error(400, "Incomplete request body")
            return

        try:
            payload = json.loads(raw.decode("utf-8"))
        except (json.JSONDecodeError, UnicodeDecodeError):
            self.send_error(400, "Invalid JSON payload")
            return

        if "state" not in payload:
            self.send_error(400, "Missing 'state' key")
            return

        state = payload["state"]
        if state not in ("on", "off"):
            self.send_error(400, "Invalid 'state' value. Must be 'on' or 'off'.")
            return

        try:
            GPIO.output(RELAY_PIN, GPIO.HIGH if state == "on" else GPIO.LOW)
        except Exception as exc:
            log.error("Failed to write GPIO %d: %s", RELAY_PIN, exc)
            self.send_error(500, "Internal server error")
            return

        body = json.dumps({"status": "Relay state changed"})
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body.encode("utf-8"))

    def log_message(self, fmt, *args):
        log.info("%s - %s", self.address_string(), fmt % args)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as exc:
        log.error("Failed to initialize GPIO: %s", exc)
        _cleanup()
        sys.exit(1)

    try:
        server = HTTPServer(("0.0.0.0", PORT), RelayHandler)
    except OSError as exc:
        log.error("Cannot bind port %d: %s", PORT, exc)
        _cleanup()
        sys.exit(1)

    log.info("Server started on 0.0.0.0:%d", PORT)

    try:
        while _running:
            server.handle_request()
    except Exception as exc:
        log.error("Server error: %s", exc)
    finally:
        _cleanup()
        server.server_close()
        log.info("Server stopped.")


if __name__ == "__main__":
    main()

