import serial
import time
import logging
import signal
import sys

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1
RELAY_ON = "RELAY1 ON"
RELAY_OFF = "RELAY1 OFF"
DELAY_SECONDS = 5

_running = True


def _signal_handler(signum, frame):
    global _running
    logger.info("Signal %s received, shutting down...", signum)
    _running = False


def _write_command(ser, command):
    try:
        payload = command.encode("ascii")
        written = ser.write(payload)
        if written != len(payload):
            logger.warning("Short write: %d of %d bytes sent for '%s'.", written, len(payload), command)
        else:
            ser.flush()
            logger.info("Sent command: %s", command)
    except serial.SerialException as e:
        logger.error("Serial write error for '%s': %s", command, e)
    except OSError as e:
        logger.error("OS error while writing '%s': %s", command, e)


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = None
    try:
        try:
            ser = serial.Serial(
                port=SERIAL_PORT,
                baudrate=BAUD_RATE,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=TIMEOUT,
            )
        except serial.SerialException as e:
            logger.error("Failed to open %s: %s", SERIAL_PORT, e)
            sys.exit(1)
        except OSError as e:
            logger.error("OS error opening %s: %s", SERIAL_PORT, e)
            sys.exit(1)

        logger.info("Serial port %s opened at %d baud.", SERIAL_PORT, BAUD_RATE)

        try:
            while _running:
                _write_command(ser, RELAY_ON)
                if not _running:
                    break
                time.sleep(DELAY_SECONDS)

                if not _running:
                    break

                _write_command(ser, RELAY_OFF)
                if not _running:
                    break
                time.sleep(DELAY_SECONDS)
        except Exception as e:
            logger.error("Unexpected error in main loop: %s", e)
        finally:
            if ser is not None and ser.is_open:
                try:
                    ser.close()
                    logger.info("Serial port %s closed.", SERIAL_PORT)
                except Exception as e:
                    logger.error("Error closing serial port: %s", e)
    except Exception as e:
        logger.error("Fatal error: %s", e)
        sys.exit(1)


if __name__ == "__main__":
    main()

