import time
import signal
import sys

try:
    from adafruit_servokit import ServoKit
except ImportError:
    print("Error: adafruit-circuitpython-servokit is not installed.")
    print("Install with: pip install adafruit-circuitpython-servokit")
    sys.exit(1)

# Constants
I2C_BUS = 1
I2C_ADDRESS = 0x40
NUM_CHANNELS = 16
SERVO_STEP_DELAY = 0.04
SERVO_STEP_DEGREES = 5

# Global handle so signal handler can release resources
_kit = None


def _cleanup(signum=None, frame=None):
    """Release resources on exit or signal."""
    global _kit
    if _kit is not None:
        try:
            # De-energize all channels to save power
            for ch in range(NUM_CHANNELS):
                _kit.servo[ch].angle = None
        except Exception:
            pass
        _kit = None
    if signum is not None:
        sys.exit(0)


def _validate_channel(channel):
    """Validate that channel is within the ServoKit's channel range."""
    if not isinstance(channel, int) or not (0 <= channel < NUM_CHANNELS):
        raise ValueError(
            f"Invalid channel {channel}. Must be an integer between 0 and {NUM_CHANNELS - 1}."
        )


def _validate_angle(angle):
    """Validate that angle is within the valid servo range."""
    if not isinstance(angle, (int, float)) or not (0 <= angle <= 180):
        raise ValueError(
            f"Invalid angle {angle}. Must be a number between 0 and 180 degrees."
        )


def _move_servo(kit, channel, target_angle):
    """Moves a servo to the target angle in 5-degree steps with a 0.04s delay."""
    _validate_channel(channel)
    _validate_angle(target_angle)

    try:
        current_angle = kit.servo[channel].angle
        if current_angle is None:
            current_angle = 0

        current_angle = int(current_angle)
        target_angle = int(target_angle)

        if target_angle > current_angle:
            step = SERVO_STEP_DEGREES
        else:
            step = -SERVO_STEP_DEGREES

        angle = current_angle
        while angle != target_angle:
            angle += step
            if angle < 0:
                angle = 0
            elif angle > 180:
                angle = 180
            kit.servo[channel].angle = angle
            time.sleep(SERVO_STEP_DELAY)

        kit.servo[channel].angle = target_angle
    except OSError as e:
        print(f"I2C OSError moving servo on channel {channel}: {e}")
    except ValueError as e:
        print(f"ValueError moving servo on channel {channel}: {e}")
    except Exception as e:
        print(f"Unexpected error moving servo on channel {channel}: {e}")


def grab_object(kit, channel=0):
    """Moves the specified servo to grab position (90 degrees)."""
    _move_servo(kit, channel, 90)


def release_object(kit, channel=0):
    """Moves the specified servo to release position (150 degrees)."""
    _move_servo(kit, channel, 150)


def main():
    """Main function to demonstrate servo control."""
    global _kit

    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    try:
        _kit = ServoKit(channels=NUM_CHANNELS, i2c=None, address=I2C_ADDRESS)
    except OSError as e:
        print(f"Failed to initialize ServoKit on I2C bus {I2C_BUS} at address 0x{I2C_ADDRESS:02X}: {e}")
        print("Check wiring and I2C address. Run with sudo if needed.")
        sys.exit(1)
    except ValueError as e:
        print(f"Invalid ServoKit configuration: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing ServoKit: {e}")
        sys.exit(1)

    try:
        print("Grabbing object...")
        grab_object(_kit, 0)
        time.sleep(1)

        print("Releasing object...")
        release_object(_kit, 0)
        time.sleep(1)

        print("Sequence complete.")
    except Exception as e:
        print(f"Error during servo sequence: {e}")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

