import logging
import signal
import sys

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

PUMP_PIN = 20
LIGHT_PIN = 21
PHRASES = [
    "turn the pump on",
    "switch the light",
    "turn pump off",
    "unknown command",
]

PUMP_ON = "pump_on"
PUMP_OFF = "pump_off"
LIGHT_TOGGLE = "light_toggle"


class ActuatorDriver:
    """Thin wrapper around a generic driver library that exposes close()."""

    def __init__(self, pump_pin, light_pin):
        self.pump_pin = pump_pin
        self.light_pin = light_pin
        self._initialized = False

    def initialize(self):
        if not self._initialized:
            logging.info("Initializing actuator driver (BCM %d pump, BCM %d light).",
                         self.pump_pin, self.light_pin)
            self._initialized = True
        return True

    def pump_on(self):
        logging.info("Pump turned ON")
        return True

    def pump_off(self):
        logging.info("Pump turned OFF")
        return True

    def light_toggle(self):
        logging.info("Light toggled")
        return True

    def close(self):
        if self._initialized:
            logging.info("Shutting down actuator driver.")
            self._initialized = False


def parse_intent(phrase):
    """Return the intent string matching a case-insensitive keyword, or None."""
    intent_map = {
        PUMP_ON: "pump on",
        PUMP_OFF: "pump off",
        LIGHT_TOGGLE: "light toggle",
    }
    for key, value in intent_map.items():
        if value in phrase.lower():
            return key
    return None


def apply_intent(driver, intent):
    """Apply the parsed intent to the actuator driver, logging warnings for unknown intents."""
    if intent == PUMP_ON:
        return driver.pump_on()
    if intent == PUMP_OFF:
        return driver.pump_off()
    if intent == LIGHT_TOGGLE:
        return driver.light_toggle()
    logging.warning("Unknown intent: %s", intent)
    return None


def main():
    driver = ActuatorDriver(PUMP_PIN, LIGHT_PIN)
    if not driver.initialize():
        logging.error("Failed to initialize actuator driver.")
        sys.exit(1)

    # Graceful shutdown on SIGTERM (e.g. systemd stop) and SIGINT (Ctrl-C)
    def _signal_handler(signum, frame):
        logging.info("Received signal %d, shutting down.", signum)
        driver.close()
        sys.exit(0)

    signal.signal(signal.SIGTERM, _signal_handler)
    signal.signal(signal.SIGINT, _signal_handler)

    for phrase in PHRASES:
        intent = parse_intent(phrase)
        if intent is not None:
            apply_intent(driver, intent)
        else:
            logging.info("Phrase '%s' has no matching intent.", phrase)

    driver.close()


if __name__ == "__main__":
    main()

