import time
import os
import logging
from threading import Event

import paho.mqtt.client as mqtt

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("mqtt_buzzer")

BUZZER_PIN = 26
TOPIC = "FaceReko/failure"
HOST = "a2ju1kllkt1ijl.iot.us-east-1.amazonaws.com"
PORT = 8883
ROOT_CA = "rootca.pem"
PRIVATE_KEY = "private.pem.key"
CERTIFICATE = "certificate.pem.crt"

ON_TIME = 0.5
OFF_TIME = 0.5
PATTERN_REPEATS = 5

running = True
buzzer = None
client = None


def _validate_tls_files():
    missing = [f for f in (ROOT_CA, PRIVATE_KEY, CERTIFICATE) if not os.path.isfile(f)]
    if missing:
        log.warning("Missing TLS files: %s. Continuing without TLS.", ", ".join(missing))


def _buzzer_on():
    global buzzer
    if buzzer is not None:
        try:
            buzzer.on()
        except Exception as exc:
            log.error("Failed to turn buzzer on: %s", exc)


def _buzzer_off():
    global buzzer
    if buzzer is not None:
        try:
            buzzer.off()
        except Exception as exc:
            log.error("Failed to turn buzzer off: %s", exc)


def _buzzer_pattern():
    global buzzer
    if buzzer is None:
        return
    for _ in range(PATTERN_REPEATS):
        _buzzer_on()
        time.sleep(ON_TIME)
        _buzzer_off()
        time.sleep(OFF_TIME)


def _on_message(client, userdata, message):
    global running
    try:
        payload = message.payload.decode("utf-8", errors="replace")
        log.info("Received message on %s: %s", message.topic, payload)
        _buzzer_pattern()
    except Exception as exc:
        log.error("Error processing message: %s", exc)


def _signal_handler(signum, frame):
    global running
    log.info("Received signal %s, shutting down...", signum)
    running = False


def main():
    global buzzer, client

    _validate_tls_files()

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        buzzer = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
        buzzer.on_message = _on_message
        buzzer.on_connect = _on_connect
        buzzer.on_disconnect = _on_disconnect

        try:
            buzzer.tls_set(
                ca_certs=ROOT_CA,
                certfile=CERTIFICATE,
                keyfile=PRIVATE_KEY,
            )
        except Exception as exc:
            log.warning("TLS setup failed: %s. Continuing without TLS.", exc)

        client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
        client.on_connect = _on_connect
        client.on_disconnect = _on_disconnect

        client.connect(HOST, PORT, keepalive=60)
        client.loop_start()

        while running:
            time.sleep(0.5)

    except Exception as exc:
        log.error("MQTT error: %s", exc)
    finally:
        if client is not None:
            try:
                client.loop_stop()
                client.disconnect()
            except Exception:
                pass
        if buzzer is not None:
            try:
                buzzer.cleanup()
            except Exception:
                pass
        log.info("Cleanup complete. Exiting.")


def _on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        log.info("Connected to AWS IoT Core.")
        client.subscribe(TOPIC, qos=1)
    else:
        log.error("Connection failed with reason code: %s", reason_code)


def _on_disconnect(client, userdata, flags, reason_code, properties):
    log.info("Disconnected from AWS IoT Core (reason code: %s).", reason_code)


if __name__ == "__main__":
    main()

