        date = self._bcd_to_int(date_raw)
        month = self._bcd_to_int(month_raw)
        year = self._bcd_to_int(year_raw)

        self._validate_datetime(year, month, date, hours, minutes, seconds)
        return year, month, date, day, hours, minutes, seconds

    def read_datetime(self):
        """Return a timezone.utc datetime object from the RTC."""
        year, month, date, _, hours, minutes, seconds = self.read_all()
        return datetime(
            self.CENTURY_START + year,
            month,
            date,
            hours,
            minutes,
            seconds,
            tzinfo=datetime.timezone.utc,
        )

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        """Write all seven time registers in BCD, enforcing 24-hour mode."""
        self._validate_datetime(year, month, date, hours, minutes, seconds)
        bcd_seconds = self._int_to_bcd(seconds)
        bcd_minutes = self._int_to_bcd(minutes)
        bcd_hours = self._int_to_bcd(hours)
        bcd_day = self._int_to_bcd(day)
        bcd_date = self._int_to_bcd(date)
        bcd_month = self._int_to_bcd(month)
        bcd_year = self._int_to_bcd(year)

        self._write_register(self.REG_SECONDS, bcd_seconds)
        self._write_register(self.REG_MINUTES, bcd_minutes)
        self._write_register(self.REG_HOURS, bcd_hours)
        self._write_register(self.REG_DAY, bcd_day)
        self._write_register(self.REG_DATE, bcd_date)
        self._write_register(self.REG_MONTH, bcd_month)
        self._write_register(self.REG_YEAR, bcd_year)

        # Clear clock-halt bit (DS1338 keeps time when CH=0)
        self._write_register(self.REG_CONTROL, bcd_hours & 0x7F)

    def write_datetime(self, dt):
        """Write a timezone.utc datetime to the RTC."""
        self._validate_datetime(
            dt.year - self.CENTURY_START, dt.month, dt.day, dt.hour, dt.minute, dt.second
        )
        self.write_all(
            dt.year - self.CENTURY_START, dt.month, dt.day, dt.isoweekday(), dt.hour, dt.minute, dt.second
        )

    def write_now(self):
        """Write the current system time to the RTC (24-hour mode)."""
        now = datetime.now(tz=datetime.timezone.utc)
        self.write_datetime(now)


# -- demo ---------------------------------------------------------------
if __name__ == "__main__":
    try:
        with DS1338(bus_number=1, address=0x68) as rtc:
            now = rtc.read_datetime()
            print(f"Current RTC time: {now}")
    except IOError as exc:
        print(f"DS1338 not detected or I2C error: {exc}", file=sys.stderr)
        sys.exit(0)

