import signal
import threading
import time

import spidev

# 25LC040 SPI EEPROM (or compatible 4 Kb SPI EEPROM)
# SPI: SCK=GPIO11, MOSI=GPIO10, MISO=GPIO9, CS=D5
CS_PIN = 5
SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 1_000_000  # 1 MHz
WRITE_BUFFER = b'1234567890ABCDEF'
NUM_BYTES = 16
ADDRESS = 0

# Thread-safety guard
_lock = threading.Lock()


class EepromError(Exception):
    """Raised when the EEPROM cannot be accessed."""


class Eeprom:
    """Thread-safe SPI EEPROM driver for 25LC040 / 4 Kb SPI EEPROM."""

    def __init__(self, spi_bus=SPI_BUS, spi_device=SPI_DEVICE, cs_pin=CS_PIN):
        self.cs_pin = cs_pin
        self.spi = None
        self._closed = False

        try:
            self.spi = spidev.SpiDev()
            self.spi.open(spi_bus, spi_device)
            self.spi.max_speed_hz = SPI_SPEED_HZ
            self.spi.mode = 0
            self.spi.bits_per_word = 8
        except Exception as exc:
            raise EepromError(f"Failed to open SPI bus {spi_bus}.{spi_device}: {exc}") from exc

    # -- public API ---------------------------------------------------------

    def write(self, address, data):
        """Write *data* to *address* (byte-aligned)."""
        if self.spi is None or self._closed:
            raise EepromError("SPI device is not open")
        with _lock:
            if not (0 <= address <= 4095):
                raise EepromError(f"Invalid write address {address}")
            if not isinstance(data, (bytes, bytearray)):
                raise EepromError("data must be bytes or bytearray")
            if len(data) == 0:
                raise EepromError("data cannot be empty")
            if address + len(data) > 4096:
                raise EepromError(f"write exceeds 4 KiB boundary at {address}")

            # 25LC040 SPI: start bit, mode 0, MSB first, MSB first
            tx = [0x01, (0x80 | (address >> 8)) & 0xFF, address & 0xFF, 0x00]
            for byte in data:
                tx.append(byte)
            rx = self.spi.xfer2(tx)
            if len(rx) < len(data) + 3:
                raise EepromError(f"SPI transfer returned {len(rx)} bytes, expected {len(data) + 3}")

    def read(self, address, length):
        """Read *length* bytes starting at *address* (byte-aligned)."""
        if self.spi is None or self._closed:
            raise EepromError("SPI device is not open")
        with _lock:
            if not (0 <= address <= 4095):
                raise EepromError(f"Invalid read address {address}")
            if not (0 <= length <= 4096):
                raise EepromError(f"Invalid read length {length}")
            if address + length > 4096:
                raise EepromError(f"read exceeds 4 KiB boundary at {address}")

            tx = [0x01, (0x80 | (address >> 8)) & 0xFF, address & 0xFF, 0x00]
            for _ in range(length):
                tx.append(0x00)
            rx = self.spi.xfer2(tx)
            if len(rx) < 3:
                raise EepromError(f"SPI transfer returned {len(rx)} bytes, expected 3")
            return bytes(rx[2:2 + length])

    def close(self):
        """Release the SPI bus and CS pin."""
        if self.spi is not None:
            try:
                self.spi.close()
            except Exception:
                pass
            self.spi = None
        self._closed = True

    def __del__(self):
        self.close()


def _write_and_read(eeprom, address, data):
    """Thread target: write *data* to *address* then read it back."""
    try:
        eeprom.write(address, data)
        time.sleep(0.05)  # allow write to settle
        read_data = eeprom.read(address, len(data))
        if read_data != data:
            raise EepromError(f"Write/read mismatch: wrote {data!r}, read {read_data!r}")
    except EepromError as exc:
        print(f"Error: {exc}")
    except Exception as exc:
        print(f"Unexpected error: {exc}")


def main():
    eeprom = None
    shutting_down = False

    def _signal_handler(signum, frame):
        nonlocal shutting_down
        shutting_down = True
        print(f"\nReceived signal {signum}, shutting down...")

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        eeprom = Eeprom()
        print("SPI EEPROM initialized on bus 0, device 0, CS=D5")

        def _worker():
            _write_and_read(eeprom, ADDRESS, WRITE_BUFFER)

        t1 = threading.Thread(target=_worker, name="write-thread", daemon=True)
        t2 = threading.Thread(target=_worker, name="read-thread", daemon=True)

        t1.start()
        t2.start()

        t1.join(timeout=2.0)
        t2.join(timeout=2.0)

        if shutting_down:
            return

        print("Read back:", eeprom.read(ADDRESS, NUM_BYTES))

    except EepromError as exc:
        print(f"EEPROM error: {exc}")
    except Exception as exc:
        print(f"Unexpected error: {exc}")
    finally:
        if eeprom is not None:
            eeprom.close()
        print("Resources released.")


if __name__ == "__main__":
    main()

