import signal
import sys
import time
from datetime import datetime

import serial

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'co2_readings_log.txt'
SAMPLE_INTERVAL = 5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_co2_level(ser):
    """Read one line from the serial port and return the CO2 ppm as int.

    Returns None on any error or when the payload is empty/non-numeric.
    """
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f'[ERROR] Serial read failed: {exc}', file=sys.stderr)
        return None

    if not raw:
        return None

    try:
        data = raw.decode('ascii', errors='replace').strip()
    except Exception as exc:
        print(f'[ERROR] Decode failed: {exc}', file=sys.stderr)
        return None

    if not data:
        return None

    try:
        return int(data)
    except ValueError:
        print(f'[ERROR] Non-numeric payload: {data!r}', file=sys.stderr)
        return None


def log_co2_level(co2_level):
    """Append a timestamped CO2 reading to the log file."""
    timestamp = datetime.now().isoformat(timespec='seconds')
    entry = f'{timestamp} - CO2 Level: {co2_level} ppm\n'
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as fh:
            fh.write(entry)
    except IOError as exc:
        print(f'[ERROR] Failed to write log file: {exc}', file=sys.stderr)


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f'Connected to {SERIAL_PORT} at {BAUD_RATE} baud.')

        while _running:
            co2 = read_co2_level(ser)
            if co2 is not None:
                print(f'CO2 Level: {co2} ppm')
                log_co2_level(co2)
            else:
                print('Failed to read valid CO2 data.')

            for _ in range(SAMPLE_INTERVAL):
                if not _running:
                    break
                time.sleep(1)

    except serial.SerialException as exc:
        print(f'[ERROR] Could not open serial port: {exc}', file=sys.stderr)
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print('Serial port closed.')


if __name__ == '__main__':
    main()

