    global _running
    _running = False


def _log_error(message: str) -> None:
    print(f'Error: {message}', file=sys.stderr, flush=True)


def _log_warning(message: str) -> None:
    print(f'Warning: {message}', file=sys.stderr, flush=True)


def _open_serial_port() -> serial.Serial | None:
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=TIMEOUT,
        )
    except serial.SerialException as exc:
        _log_error(f'Failed to open serial port {SERIAL_PORT}: {exc}')
        return None
    except OSError as exc:
        _log_error(f'OS error opening {SERIAL_PORT}: {exc}')
        return None


def _read_co2_level(ser: serial.Serial) -> int | None:
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        _log_error(f'Serial read error: {exc}')
        return None
    if not raw:
        return None
    text = raw.decode('ascii', errors='replace').strip()
    if not text:
        return None
    try:
        return int(text)
    except ValueError:
        _log_warning(f'Non-numeric data received: {text!r}')
        return None


def _log_reading(co2_level: int) -> None:
    timestamp = datetime.now().isoformat(timespec='seconds')
    line = f'{timestamp} - CO2 Level: {co2_level} ppm\n'
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as fh:
            fh.write(line)
            fh.flush()
    except OSError as exc:
        _log_error(f'Failed to write to log file {LOG_FILE}: {exc}')
    print(line, flush=True)


def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = _open_serial_port()
    if ser is None:
        return 1

    try:
        while _running:
            co2_level = _read_co2_level(ser)
            if co2_level is not None:
                _log_reading(co2_level)
            time.sleep(SAMPLE_INTERVAL)
    finally:
        if ser and ser.is_open:
            try:
                ser.close()
            except serial.SerialException as exc:
                _log_error(f'Error closing serial port: {exc}')
        print('Program terminated.', file=sys.stderr, flush=True)
    return 0


if __name__ == '__main__':
    sys.exit(main())

