import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional

import serial

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


@dataclass
class GPSReadings:
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellite_count: Optional[int] = None


class GPSReader:
    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600):
        self.port = port
        self.baudrate = baudrate
        self.uart: Optional[serial.Serial] = None
        self._running = True

    def connect(self) -> bool:
        try:
            self.uart = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0,
            )
            logging.info("Connected to GPS on %s at %d baud", self.port, self.baudrate)
            return True
        except serial.SerialException as exc:
            logging.error("Failed to connect to GPS on %s: %s", self.port, exc)
            self.uart = None
            return False

    def disconnect(self) -> None:
        if self.uart is not None:
            try:
                if self.uart.is_open:
                    self.uart.close()
            except Exception as exc:  # noqa: BLE001
                logging.warning("Error closing UART: %s", exc)
            finally:
                self.uart = None

    def _read_once(self) -> Optional[GPSReadings]:
        if self.uart is None or not self.uart.is_open:
            return None
        try:
            raw = self.uart.readline()
        except serial.SerialException as exc:
            logging.error("Serial read error: %s", exc)
            return None
        if not raw:
            return None
        try:
            line = raw.decode("ascii", errors="replace").strip()
        except Exception as exc:  # noqa: BLE001
            logging.error("Decode error: %s", exc)
            return None
        if not line:
            return None
        if line.startswith("$GPGGA", 6):
            return self._parse_gpgga(line)
        return None

    def _parse_gpgga(self, line: str) -> GPSReadings:
        parts = line.split(",")
        if len(parts) < 15:
            raise ValueError(f"Short GPGGA sentence: {line!r}")
        talker = parts[0]
        if talker != "$GPGGA":
            raise ValueError(f"Invalid talker: {talker!r}")
        lat = self._to_decimal(parts[2], parts[3]) if parts[2] and parts[3] else None
        lon = self._to_decimal(parts[4], parts[5]) if parts[4] and parts[5] else None
        alt = float(parts[9]) if parts[9] else None
        sats = int(parts[7]) if parts[7] else None
        return GPSReadings(
            latitude=lat,
            longitude=lon,
            altitude=alt,
            satellite_count=sats,
        )

    @staticmethod
    def _to_decimal(field: str, direction: str) -> Optional[float]:
        if not field or not direction:
            return None
        try:
            deg = float(field)
        except ValueError:
            return None
        if direction in ("S", "W"):
            deg = -deg
        return deg

    def read(self) -> Optional[GPSReadings]:
        return self._read_once()

    def stop(self) -> None:
        self._running = False

    def run(self) -> None:
        if not self.connect():
            sys.exit(1)
        try:
            while self._running:
                readings = self.read()
                if readings is not None:
                    logging.info(
                        "Lat=%s, Lon=%s, Alt=%s m, Sats=%s",
                        readings.latitude,
                        readings.longitude,
                        readings.altitude,
                        readings.satellite_count,
                    )
                else:
                    logging.warning("No valid GPGGA sentence received")
        except Exception as exc:  # noqa: BLE001
            logging.error("Unexpected error in read loop: %s", exc)
        finally:
            self.disconnect()


def main() -> None:
    reader = GPSReader(port="/dev/serial0", baudrate=9600)
    def _signal_handler(signum, frame):
        logging.info("Signal %d received, shutting down", signum)
        reader.stop()
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    reader.run()


if __name__ == "__main__":
    main()

