UART_TIMEOUT = 5
UART_READ_DELAY = 1
UART_MAX_RETRIES = 3


class ESP8266:
    def __init__(self, port: str = '/dev/serial0', baudrate: int = UART_BAUDRATE,
                 tx_pin: int = UART_TX_PIN, rx_pin: int = UART_RX_PIN,
