import signal
import sys
import time
import logging
from typing import Optional

import serial

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)


class GPS:
    """
    Driver for a GPS module (e.g. SIM28 / SIM808) connected to the Raspberry Pi
    via the hardware UART on /dev/ttyAMA0 at 9600 baud.

    Usage:
        with GPS(port='/dev/ttyAMA0', baud=9600) as gps:
            while True:
                line = gps.get_data()
                if line:
                    print(line)
    """

    def __init__(self, port: str = '/dev/ttyAMA0', baud: int = 9600) -> None:
        self._port = port
        self._baud = baud
        self._uart: Optional[serial.Serial] = None
        self._closed = False

        try:
            self._uart = serial.Serial(
                port=port,
                baudrate=baud,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0,
            )
        except serial.SerialException as exc:
            logger.error("Failed to open %s: %s", port, exc)
            raise

        self._install_signal_handlers()

    # ------------------------------------------------------------------
    # Context-manager support
    # ------------------------------------------------------------------
    def __enter__(self) -> "GPS":
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self.close()

    # ------------------------------------------------------------------
    # Signal handling
    # ------------------------------------------------------------------
    def _install_signal_handlers(self) -> None:
        for sig in (signal.SIGINT, signal.SIGTERM):
            try:
                signal.signal(sig, self._signal_handler)
            except (ValueError, OSError):
                # Not in main thread or signal not supported
                pass

    def _signal_handler(self, signum, frame) -> None:
        logger.info("Received signal %d; closing GPS port.", signum)
        self.close()
        sys.exit(0)

    # ------------------------------------------------------------------
    # Low-level I/O
    # ------------------------------------------------------------------
    def _write(self, data: str) -> bool:
        if self._uart is None or self._closed:
            logger.error("UART not open; cannot write: %r", data)
            return False
        try:
            written = self._uart.write(data.encode('ascii'))
            if written != len(data):
                logger.warning("Partial write: %d/%d bytes.", written, len(data))
            self._uart.flush()
            return True
        except serial.SerialException as exc:
            logger.error("UART write failed: %s", exc)
            return False

    def _read_line(self) -> Optional[str]:
        if self._uart is None or self._closed:
            return None
        try:
            raw = self._uart.readline()
        except serial.SerialException as exc:
            logger.error("UART read failed: %s", exc)
            return None
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def attach(self) -> bool:
        """Power on the GNSS module via AT+CGNSPWR=1."""
        if self._uart is None or self._closed:
            logger.error("Cannot attach: UART is not open.")
            return False
        try:
            if not self._write('AT+CGNSPWR=1\r\n'):
                return False
            time.sleep(1)
            if not self._write('AT+CGPS=1\r\n'):
                return False
            logger.info("GNSS module powered on.")
            return True
        except serial.SerialException as exc:
            logger.error("GNSS AT command failed: %s", exc)
            return False

    def detach(self) -> bool:
        """Power off the GNSS module via AT+CGNSPWR=0."""
        if self._uart is None or self._closed:
            logger.error("Cannot detach: UART is not open.")
            return False
        try:
            if not self._write('AT+CGNSPWR=0\r\n'):
                return False
            logger.info("GNSS module powered off.")
            return True
        except serial.SerialException as exc:
            logger.error("GNSS AT command failed: %s", exc)
            return False

    def get_data(self) -> Optional[str]:
        """
        Read one line from the UART and parse it as $GPRMC.
        Returns the parsed RMC line, or None if no data, invalid data,
        or the port is closed.
        """
        if self._uart is None or self._closed:
            return None
        try:
            line = self._read_line()
        except serial.SerialException as exc:
            logger.error("UART read failed: %s", exc)
            return None
        if line is None:
            return None
        if not line.startswith('$GPRMC'):
            return line
        parts = line.split(',')
        if len(parts) < 7:
            logger.warning("Incomplete $GPRMC: %r", line)
            return None
        if parts[2] != 'A':
            logger.debug("GNSS not ready (status=%r).", parts[2])
            return None
        return line


# ----------------------------------------------------------------------
# Example usage
# ----------------------------------------------------------------------
if __name__ == '__main__':
    try:
        with GPS(port='/dev/ttyAMA0', baud=9600) as gps:
            if not gps.attach():
                logger.error("Failed to attach GNSS module.")
                sys.exit(1)
            while True:
                line = gps.get_data()
                if line:
                    print(line)
    except serial.SerialException as exc:
        logger.error("Fatal serial error: %s", exc)
        sys.exit(1)
    except KeyboardInterrupt:
        logger.info("Interrupted by user.")
        sys.exit(0)

