import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'health_readings_log.txt'
LOOP_DELAY = 0.1

running = True
serial_port = None

def signal_handler(signum, frame):
    global running
    running = False

def cleanup():
    global serial_port
    if serial_port is not None and serial_port.is_open:
        try:
            serial_port.close()
            print('Serial port closed.')
        except Exception as e:
            print(f'Error closing serial port: {e}')

def main():
    global serial_port, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_port = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f'Connected to {SERIAL_PORT} at {BAUD_RATE} baud.')
    except serial.SerialException as e:
        print(f'Error opening serial port: {e}')
        sys.exit(1)

    try:
        while running:
            try:
                raw = serial_port.readline()
                if not raw:
                    continue

                line = raw.decode('ascii', errors='replace').strip()
                if not line:
                    continue

                parts = line.split(',')
                if len(parts) != 2:
                    print(f'Invalid data format: {line}')
                    continue

                heart_rate, spo2 = parts[0], parts[1]

                timestamp = datetime.now().isoformat(timespec='seconds')
                print(f'{timestamp} - Heart Rate: {heart_rate} bpm, SpO2: {spo2} %')

                try:
                    with open(LOG_FILE, 'a') as f:
                        f.write(f'{timestamp} - Heart Rate: {heart_rate} bpm, SpO2: {spo2} %\n')
                except IOError as e:
                    print(f'Error writing to log file: {e}')

            except ValueError:
                print('Error: Invalid data format received from sensor.')
            except serial.SerialException as e:
                print(f'Serial communication error: {e}')
            except Exception as e:
                print(f'An unexpected error occurred: {e}')

            time.sleep(LOOP_DELAY)

    except KeyboardInterrupt:
        print('\nProgram terminated by user.')
    finally:
        cleanup()

if __name__ == '__main__':
    main()

