import signal
import threading
import time
import json
import logging
from http.server import BaseHTTPRequestHandler, HTTPServer
from typing import List, Optional

import serial

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)

PORT = '/dev/ttyUSB0'
BAUD = 9600
TIMEOUT = 1
WEB_PORT = 5000
DATA_SEED = [{'id': 1, 'name': 'Item 1', 'done': False}, {'id': 2, 'name': 'Item 2', 'done': False}]

running = True
uart_lock = threading.Lock()
uart: Optional[serial.Serial] = None


class Instrument:
    def __init__(self, port: str, baudrate: int, timeout: float):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self._serial: Optional[serial.Serial] = None
        self._open()

    def _open(self) -> None:
        with uart_lock:
            if self._serial is not None and self._serial.is_open:
                return
            try:
                self._serial = serial.Serial(
                    port=self.port,
                    baudrate=self.baudrate,
                    bytesize=serial.EIGHTBITS,
                    parity=serial.PARITY_NONE,
                    stopbits=serial.STOPBITS_ONE,
                    timeout=self.timeout,
                )
                logger.info('UART %s opened at %d baud', self.port, self.baudrate)
            except serial.SerialException as exc:
                logger.error('Failed to open UART %s: %s', self.port, exc)
                self._serial = None

    def close(self) -> None:
        with uart_lock:
            if self._serial is not None and self._serial.is_open:
                try:
                    self._serial.close()
                    logger.info('UART %s closed', self.port)
                except serial.SerialException as exc:
                    logger.error('Error closing UART %s: %s', self.port, exc)
                finally:
                    self._serial = None

    def send_command(self, command: str) -> Optional[str]:
        if self._serial is None or not self._serial.is_open:
            logger.error('UART not open')
            return None
        try:
            self._serial.reset_input_buffer()
            self._serial.write(command.encode('ascii'))
            self._serial.flush()
            response = self._serial.readline()
            if not response:
                logger.warning('No response within timeout')
                return None
            return response.decode('ascii', errors='replace').strip()
        except serial.SerialException as exc:
            logger.error('UART communication error: %s', exc)
            return None

    def get_version(self) -> Optional[str]:
        return self.send_command('*IDN?\n')

    def get_all_data(self) -> List[dict]:
        with uart_lock:
            if self._serial is None or not self._serial.is_open:
                logger.error('UART not open')
                return []
            try:
                self._serial.reset_input_buffer()
                self._serial.write(b'get_data\n')
                self._serial.flush()
                raw = self._serial.readline()
                if not raw:
                    logger.warning('No response within timeout')
                    return []
                return json.loads(raw.decode('ascii'))
            except (json.JSONDecodeError, serial.SerialException) as exc:
                logger.error('Error parsing data: %s', exc)
                return []

    def get_data(self, item_id: int) -> Optional[dict]:
        with uart_lock:
            if self._serial is None or not self._serial.is_open:
                logger.error('UART not open')
                return None
            try:
                self._serial.reset_input_buffer()
                self._serial.write(f'SEARCH {item_id}\n'.encode('ascii'))
                self._serial.flush()
                raw = self._serial.readline()
                if not raw:
                    logger.warning('No response within timeout')
                    return None
                return json.loads(raw.decode('ascii'))
            except (json.JSONDecodeError, serial.SerialException) as exc:
                logger.error('Error searching for data: %s', exc)
                return None

    def add_data(self, name: str, done: bool) -> Optional[dict]:
        with uart_lock:
            if self._serial is None or not self._serial.is_open:
                logger.error('UART not open')
                return None
            try:
                self._serial.reset_input_buffer()
                self._serial.write(f'POST data\n'.encode('ascii'))
                self._serial.flush()
                self._serial.write(f'{name}\n'.encode('ascii'))
                self._serial.flush()
                self._serial.write(f'{done}\n'.encode('ascii'))
                self._serial.flush()
                raw = self._serial.readline()
                if not raw:
                    logger.warning('No response within timeout')
                    return None
                return json.loads(raw.decode('ascii'))
            except (json.JSONDecodeError, serial.SerialException) as exc:
                logger.error('Error adding data: %s', exc)
                return None


class WebHandler(BaseHTTPRequestHandler):
    def do_GET(self) -> None:
        if self.path == '/version':
            version = instrument.get_version()
            self.send_response(200)
            self.send_header('Content-type', 'text/plain')
            self.end_headers()
            if version:
                self.wfile.write(version.encode('ascii'))
            else:
                self.wfile.write(b'No response from instrument')
        elif self.path == '/data':
            if self.path == '/data/1':
                item = instrument.get_data(1)
                self.send_response(200)
                self.send_header('Content-type', 'application/json')
                self.end_headers()
                if item:
                    self.wfile.write(json.dumps(item).encode('ascii'))
                else:
                    self.wfile.write(b'Item not found')
            elif self.path == '/data/2':
                item = instrument.get_data(2)
                self.send_response(200)
                self.send_header('Content-type', 'application/json')
                self.end_headers()
                if item:
                    self.wfile.write(json.dumps(item).encode('ascii'))
                else:
                    self.wfile.write(b'Item not found')
            else:
                self.send_response(404)
                self.end_headers()
        else:
            self.send_response(404)
            self.end_headers()

    def do_POST(self) -> None:
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length == 0:
            self.send_response(400)
            self.end_headers()
            return
        try:
            post_data = self.rfile.read(content_length)
            name = post_data.decode('ascii', errors='replace').strip()
            done = bool(int(self.headers.get('Content-Length', 0)))
            new_item = instrument.add_data(name, done)
            self.send_response(201)
            self.send_header('Content-type', 'application/json')
            self.end_headers()
            if new_item:
                self.wfile.write(json.dumps(new_item).encode('ascii'))
            else:
                self.wfile.write(b'Failed to add item')
        except ValueError:
            self.send_response(400)
            self.end_headers()
        except Exception as exc:
            logger.error('Error processing POST: %s', exc)
            self.send_response(500)
            self.end_headers()


def signal_handler(signum, frame):
    global running
    logger.info('Received signal %d, shutting down...', signum)
    running = False


def main() -> None:
    global instrument
    instrument = Instrument(PORT, BAUD, TIMEOUT)
    if instrument._serial is None or not instrument._serial.is_open:
        logger.error('Failed to open UART %s', PORT)
        return
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    server = HTTPServer(('0.0.0.0', WEB_PORT), WebHandler)
    server_thread = threading.Thread(target=server.serve_forever, daemon=True)
    server_thread.start()
    logger.info('Web service running on 0.0.0.0:%d', WEB_PORT)
    try:
        while running:
            time.sleep(0.5)
    finally:
        server.shutdown()
        server_thread.join(timeout=2)
        instrument.close()
        logger.info('Shutdown complete')


if __name__ == '__main__':
    main()

