import serial
import time
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
READ_INTERVAL = 1


def parse_oximeter_data(raw_data: str) -> tuple[int, int]:
    """Parse a comma-separated oximeter line into (heart_rate, spo2).

    Returns (None, None) if the line is empty or malformed.
    """
    if not raw_data:
        return None, None

    parts = raw_data.split(',')
    if len(parts) != 2:
        raise ValueError(f"Expected 2 fields, got {len(parts)}: '{raw_data}'")

    heart_rate = int(parts[0].strip())
    spo2 = int(parts[1].strip())
