import os
import sys
import time
import signal
import bluetooth

BLUETOOTH_PORT = os.getenv("BLUETOOTH_PORT", "/dev/rfcomm4")
BLUETOOTH_BAUDRATE = int(os.getenv("BLUETOOTH_BAUDRATE", "38400"))
BLUETOOTH_DELAY = 0.1

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _connect_bluetooth():
    try:
        return bluetooth.BluetoothSocket(bluetooth.RFCOMM, BLUETOOTH_PORT)
    except bluetooth.BluetoothError as e:
        raise RuntimeError(f"Bluetooth connection failed: {e}") from e

def _close_bluetooth(socket):
    try:
        if socket:
            socket.close()
    except Exception as e:
        print(f"Warning: error closing Bluetooth socket: {e}", file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bluetooth_socket = None
    try:
        bluetooth_socket = _connect_bluetooth()
        print(f"Connected to Bluetooth device on {BLUETOOTH_PORT} at {BLUETOOTH_BAUDRATE} baud.")

        while _running:
            try:
                command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if command.strip().lower() == "exit":
                break

            try:
                message = f"X{command}\n"
                bluetooth_socket.send(message.encode("utf-8"))
                time.sleep(BLUETOOTH_DELAY)
            except bluetooth.BluetoothError as e:
                print(f"Bluetooth error during transmission: {e}", file=sys.stderr)
                break
            except OSError as e:
                print(f"OS error during transmission: {e}", file=sys.stderr)
                break

    except RuntimeError as e:
        print(f"Fatal error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        _close_bluetooth(bluetooth_socket)
        print("Bluetooth connection closed.")

if __name__ == "__main__":
    main()

